import type { BankQuestion } from "@/lib/bank";

/** Sectors of the Economy and Government Schemes (Indian Economy): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"eco-sectors-schemes-2","question":"The Swachh Bharat Mission was launched on 2 October 2014 to mark the birth anniversary of:","options":["B.R. Ambedkar","Sardar Vallabhbhai Patel","Mahatma Gandhi","Jawaharlal Nehru"],"answer":2,"explanation":"It was launched on Gandhi Jayanti, with the aim of an open-defecation-free India by Gandhi's 150th birth anniversary in 2019.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"स्वच्छ भारत मिशन 2 अक्टूबर 2014 को किसकी जयंती के उपलक्ष्य में शुरू किया गया था?","optionsHi":["बी.आर. अंबेडकर","सरदार वल्लभभाई पटेल","महात्मा गांधी","जवाहरलाल नेहरू"],"explanationHi":"यह गांधी जयंती पर शुरू हुआ, जिसका लक्ष्य 2019 में गांधी जी की 150वीं जयंती तक भारत को खुले में शौच से मुक्त बनाना था।"},
  {"id":"eco-sectors-schemes-3","question":"Under PM-KISAN, launched in 2019, how much income support does an eligible farmer family receive in a year?","options":["₹6,000","₹2,000","₹12,000","₹10,000"],"answer":0,"explanation":"₹6,000 a year is paid in three instalments of ₹2,000 each, directly into the farmer's bank account.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"2019 में शुरू की गई PM-KISAN के अंतर्गत पात्र किसान परिवार को एक वर्ष में कितनी आय सहायता मिलती है?","optionsHi":["₹6,000","₹2,000","₹12,000","₹10,000"],"explanationHi":"₹6,000 प्रति वर्ष, ₹2,000 की तीन किस्तों में, सीधे किसान के बैंक खाते में दिए जाते हैं।"},
  {"id":"eco-sectors-schemes-4","question":"The Pradhan Mantri Ujjwala Yojana, launched in 2016, provides:","options":["Free health insurance cover to poor families","LPG connections to women of poor households","Zero-balance bank accounts for poor women","Free electricity connections to poor households"],"answer":1,"explanation":"Ujjwala gives deposit-free LPG connections in the name of adult women of poor families, to replace firewood and cow-dung cooking fuel. Free household electricity connections came under a different scheme, Saubhagya (2017).","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"2016 में शुरू की गई प्रधानमंत्री उज्ज्वला योजना क्या उपलब्ध कराती है?","optionsHi":["गरीब परिवारों को निःशुल्क स्वास्थ्य बीमा कवर","गरीब परिवारों की महिलाओं को LPG कनेक्शन","गरीब महिलाओं के लिए शून्य शेष वाले बैंक खाते","गरीब परिवारों को निःशुल्क बिजली कनेक्शन"],"explanationHi":"उज्ज्वला गरीब परिवारों की वयस्क महिलाओं के नाम पर बिना जमा राशि के LPG कनेक्शन देती है, ताकि लकड़ी और उपले के खाना पकाने के ईंधन की जगह ले सके। घरों में निःशुल्क बिजली कनेक्शन एक अलग योजना, सौभाग्य (2017), के अंतर्गत आए।"},
  {"id":"eco-sectors-schemes-5","question":"How many days of guaranteed wage employment per year does MGNREGA, enacted in 2005, give a rural household?","options":["150 days","365 days","200 days","100 days"],"answer":3,"explanation":"The Act guarantees 100 days of unskilled manual work per household per financial year. 150 days applies only in special cases such as drought-hit areas or forest-rights holders.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"2005 में अधिनियमित MGNREGA एक ग्रामीण परिवार को प्रति वर्ष कितने दिन के गारंटीशुदा मजदूरी रोज़गार की व्यवस्था देता है?","optionsHi":["150 दिन","365 दिन","200 दिन","100 दिन"],"explanationHi":"अधिनियम प्रति परिवार प्रति वित्तीय वर्ष 100 दिन के अकुशल शारीरिक कार्य की गारंटी देता है। 150 दिन केवल विशेष मामलों में लागू होते हैं, जैसे सूखा प्रभावित क्षेत्र या वन अधिकार धारक।"},
  {"id":"eco-sectors-schemes-6","question":"The Digital India programme, launched on 1 July 2015, is steered by which ministry?","options":["Department of Telecommunications, Ministry of Communications","Ministry of Electronics and Information Technology","Ministry of Science and Technology","Ministry of Information and Broadcasting"],"answer":1,"explanation":"MeitY is the nodal ministry for Digital India, whose three pillars are digital infrastructure, services on demand and digital empowerment. The Department of Telecommunications runs BharatNet, one input to it, but does not steer the programme.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"1 जुलाई 2015 को शुरू किया गया डिजिटल इंडिया कार्यक्रम किस मंत्रालय के नेतृत्व में चलता है?","optionsHi":["दूरसंचार विभाग, संचार मंत्रालय","इलेक्ट्रॉनिकी और सूचना प्रौद्योगिकी मंत्रालय","विज्ञान और प्रौद्योगिकी मंत्रालय","सूचना और प्रसारण मंत्रालय"],"explanationHi":"MeitY डिजिटल इंडिया का नोडल मंत्रालय है, जिसके तीन स्तंभ हैं: डिजिटल अवसंरचना, मांग पर सेवाएँ और डिजिटल सशक्तीकरण। दूरसंचार विभाग भारतनेट चलाता है, जो इसका एक आगत है, पर कार्यक्रम का नेतृत्व नहीं करता।"},
  {"id":"eco-sectors-schemes-7","question":"Under the Pradhan Mantri MUDRA Yojana, launched in 2015, the ‘Shishu’ category covers loans of up to:","options":["₹50,000","₹1 lakh","₹5 lakh","₹10 lakh"],"answer":0,"explanation":"Shishu: up to ₹50,000; Kishore: ₹50,000 to ₹5 lakh; Tarun: ₹5 lakh to ₹10 lakh (a Tarun Plus slab up to ₹20 lakh was added in 2024).","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"2015 में शुरू की गई प्रधानमंत्री मुद्रा योजना के अंतर्गत ‘शिशु’ श्रेणी कितने तक के ऋण को कवर करती है?","optionsHi":["₹50,000","₹1 लाख","₹5 लाख","₹10 लाख"],"explanationHi":"शिशु: ₹50,000 तक; किशोर: ₹50,000 से ₹5 लाख; तरुण: ₹5 लाख से ₹10 लाख (2024 में ₹20 लाख तक का ‘तरुण प्लस’ स्लैब जोड़ा गया)।"},
  {"id":"eco-sectors-schemes-8","question":"According to the Periodic Labour Force Survey 2023-24, which sector employs the largest share of India's workforce?","options":["Construction","Trade, hotels and restaurants","Agriculture","Manufacturing"],"answer":2,"explanation":"Agriculture still employs about 46% of workers, even though services contribute the largest share of GVA.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"आवधिक श्रम बल सर्वेक्षण 2023-24 के अनुसार, कौन-सा क्षेत्र भारत के कार्यबल के सबसे बड़े हिस्से को रोज़गार देता है?","optionsHi":["निर्माण","व्यापार, होटल और रेस्तरां","कृषि","विनिर्माण"],"explanationHi":"यद्यपि सकल मूल्य वर्धन (GVA) में सबसे बड़ा हिस्सा सेवाओं का है, कृषि अब भी लगभग 46% श्रमिकों को रोज़गार देती है।"},
  {"id":"eco-sectors-schemes-9","question":"Ayushman Bharat – PM-JAY, launched in 2018, gives a health cover per family per year of:","options":["₹10 lakh","₹1 lakh","₹5 lakh","₹2 lakh"],"answer":2,"explanation":"PM-JAY covers up to ₹5 lakh per family per year for secondary and tertiary hospitalisation in empanelled hospitals.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"2018 में शुरू की गई आयुष्मान भारत – PM-JAY प्रति परिवार प्रति वर्ष कितना स्वास्थ्य कवर देती है?","optionsHi":["₹10 लाख","₹1 लाख","₹5 लाख","₹2 लाख"],"explanationHi":"PM-JAY सूचीबद्ध अस्पतालों में द्वितीयक और तृतीयक अस्पताल में भर्ती के लिए प्रति परिवार प्रति वर्ष ₹5 लाख तक का कवर देती है।"},
  {"id":"eco-sectors-schemes-10","question":"The Soil Health Card Scheme was launched in February 2015 at:","options":["Ballia, Uttar Pradesh","Sehore, Madhya Pradesh","Gorakhpur, Uttar Pradesh","Suratgarh, Rajasthan"],"answer":3,"explanation":"It was launched at Suratgarh (Sri Ganganagar). PM-KISAN was launched at Gorakhpur (2019), PM Ujjwala at Ballia (2016) and PMFBY at Sehore (2016).","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"मृदा स्वास्थ्य कार्ड योजना फरवरी 2015 में कहाँ शुरू की गई थी?","optionsHi":["बलिया, उत्तर प्रदेश","सीहोर, मध्य प्रदेश","गोरखपुर, उत्तर प्रदेश","सूरतगढ़, राजस्थान"],"explanationHi":"यह सूरतगढ़ (श्री गंगानगर) में शुरू हुई। PM-KISAN गोरखपुर (2019), PM उज्ज्वला बलिया (2016) और PMFBY सीहोर (2016) में शुरू हुईं।"},
  {"id":"eco-sectors-schemes-11","question":"The Startup India initiative, launched on 16 January 2016, is coordinated by:","options":["NITI Aayog's Atal Innovation Mission","DPIIT, Ministry of Commerce and Industry","Ministry of Micro, Small and Medium Enterprises","Small Industries Development Bank of India (SIDBI)"],"answer":1,"explanation":"DPIIT, under the Ministry of Commerce and Industry, recognises startups and coordinates the Startup India programme. SIDBI only manages the Fund of Funds for Startups on its behalf.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"16 जनवरी 2016 को शुरू की गई स्टार्टअप इंडिया पहल का समन्वय कौन करता है?","optionsHi":["नीति आयोग का अटल नवाचार मिशन","DPIIT, वाणिज्य एवं उद्योग मंत्रालय","सूक्ष्म, लघु और मध्यम उद्यम मंत्रालय","भारतीय लघु उद्योग विकास बैंक (SIDBI)"],"explanationHi":"वाणिज्य एवं उद्योग मंत्रालय के अधीन DPIIT स्टार्टअप को मान्यता देता है और स्टार्टअप इंडिया कार्यक्रम का समन्वय करता है। SIDBI उसकी ओर से केवल स्टार्टअप्स के लिए फंड ऑफ फंड्स का प्रबंधन करता है।"},
  {"id":"eco-sectors-schemes-12","question":"The Atal Pension Yojana, launched in 2015, is administered by:","options":["PFRDA","SEBI","LIC","IRDAI"],"answer":0,"explanation":"The Pension Fund Regulatory and Development Authority administers APY, which guarantees a monthly pension of ₹1,000 to ₹5,000 after age 60 to those who join between 18 and 40.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"2015 में शुरू की गई अटल पेंशन योजना का प्रशासन कौन करता है?","optionsHi":["PFRDA","SEBI","LIC","IRDAI"],"explanationHi":"पेंशन निधि विनियामक और विकास प्राधिकरण APY का प्रशासन करता है, जो 18 से 40 वर्ष की आयु के बीच जुड़ने वालों को 60 वर्ष की आयु के बाद ₹1,000 से ₹5,000 की मासिक पेंशन की गारंटी देती है।"},
  {"id":"eco-sectors-schemes-13","question":"Under the Pradhan Mantri Fasal Bima Yojana, launched in 2016, what is the maximum premium a farmer pays for Rabi food and oilseed crops?","options":["0.5% of the sum insured","1.5% of the sum insured","5% of the sum insured","2% of the sum insured"],"answer":1,"explanation":"Farmers pay 2% for Kharif, 1.5% for Rabi and 5% for annual commercial or horticultural crops; the government pays the rest.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"2016 में शुरू की गई प्रधानमंत्री फसल बीमा योजना के अंतर्गत रबी खाद्य और तिलहन फसलों के लिए किसान अधिकतम कितना प्रीमियम देता है?","optionsHi":["बीमित राशि का 0.5%","बीमित राशि का 1.5%","बीमित राशि का 5%","बीमित राशि का 2%"],"explanationHi":"किसान खरीफ के लिए 2%, रबी के लिए 1.5% और वार्षिक वाणिज्यिक या बागवानी फसलों के लिए 5% देते हैं; शेष सरकार देती है।"},
  {"id":"eco-sectors-schemes-14","question":"Stand-Up India, launched in 2016, helps SC/ST and women entrepreneurs get bank loans in which range for greenfield enterprises?","options":["₹10 lakh to ₹1 crore","₹50,000 to ₹5 lakh","₹1 crore to ₹5 crore","Up to ₹10 lakh"],"answer":0,"explanation":"Each bank branch is expected to give at least one SC/ST and one woman borrower a loan between ₹10 lakh and ₹1 crore. Loans up to ₹10 lakh fall under MUDRA.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"2016 में शुरू की गई स्टैंड-अप इंडिया नए (ग्रीनफील्ड) उद्यमों के लिए SC/ST और महिला उद्यमियों को किस सीमा में बैंक ऋण दिलाने में मदद करती है?","optionsHi":["₹10 लाख से ₹1 करोड़","₹50,000 से ₹5 लाख","₹1 करोड़ से ₹5 करोड़","₹10 लाख तक"],"explanationHi":"प्रत्येक बैंक शाखा से अपेक्षा है कि वह कम से कम एक SC/ST और एक महिला उधारकर्ता को ₹10 लाख से ₹1 करोड़ के बीच ऋण दे। ₹10 लाख तक के ऋण मुद्रा के अंतर्गत आते हैं।"},
  {"id":"eco-sectors-schemes-15","question":"PM SVANidhi, launched in June 2020, provides collateral-free working capital loans to:","options":["Self-help groups","Small farmers","Artisans in traditional trades","Street vendors"],"answer":3,"explanation":"PM SVANidhi, run by the Ministry of Housing and Urban Affairs, began with ₹10,000 loans so street vendors could restart after the COVID-19 lockdown. Artisans are covered by PM Vishwakarma.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"जून 2020 में शुरू की गई PM SVANidhi किन्हें बिना गारंटी के कार्यशील पूंजी ऋण देती है?","optionsHi":["स्वयं सहायता समूह","लघु किसान","पारंपरिक व्यवसायों के कारीगर","रेहड़ी-पटरी वाले (स्ट्रीट वेंडर)"],"explanationHi":"आवास और शहरी कार्य मंत्रालय द्वारा संचालित PM SVANidhi ₹10,000 के ऋणों से शुरू हुई ताकि रेहड़ी-पटरी वाले COVID-19 लॉकडाउन के बाद काम फिर शुरू कर सकें। कारीगर PM विश्वकर्मा के अंतर्गत आते हैं।"},
  {"id":"eco-sectors-schemes-16","question":"Under the MSME classification revised in 2020, a micro enterprise has investment up to ₹1 crore and annual turnover up to:","options":["₹1 crore","₹10 crore","₹5 crore","₹50 crore"],"answer":2,"explanation":"2020 criteria: micro ≤ ₹1 crore investment and ≤ ₹5 crore turnover; small ≤ ₹10 crore and ≤ ₹50 crore; medium ≤ ₹50 crore and ≤ ₹250 crore.","difficulty":"hard","source":"IBPS PO · SBI PO · State PSC","questionHi":"2020 में संशोधित MSME वर्गीकरण के अंतर्गत, सूक्ष्म उद्यम में निवेश ₹1 करोड़ तक और वार्षिक टर्नओवर कितने तक होता है?","optionsHi":["₹1 करोड़","₹10 करोड़","₹5 करोड़","₹50 करोड़"],"explanationHi":"2020 के मानदंड: सूक्ष्म ≤ ₹1 करोड़ निवेश और ≤ ₹5 करोड़ टर्नओवर; लघु ≤ ₹10 करोड़ और ≤ ₹50 करोड़; मध्यम ≤ ₹50 करोड़ और ≤ ₹250 करोड़।"},
  {"id":"eco-sectors-schemes-17","question":"Which of the following is NOT one of the eight core industries tracked by the Index of Eight Core Industries?","options":["Textiles","Natural gas","Cement","Fertilizers"],"answer":0,"explanation":"The eight core industries are coal, crude oil, natural gas, refinery products, fertilizers, steel, cement and electricity. Textiles is not among them.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"निम्नलिखित में से कौन आठ प्रमुख उद्योगों के सूचकांक द्वारा ट्रैक किए जाने वाले आठ प्रमुख उद्योगों में से नहीं है?","optionsHi":["वस्त्र","प्राकृतिक गैस","सीमेंट","उर्वरक"],"explanationHi":"आठ प्रमुख उद्योग हैं: कोयला, कच्चा तेल, प्राकृतिक गैस, रिफाइनरी उत्पाद, उर्वरक, इस्पात, सीमेंट और बिजली। वस्त्र इनमें नहीं है।"},
  {"id":"eco-sectors-schemes-18","question":"The National Agriculture Market (e-NAM), launched in April 2016, is implemented by:","options":["Food Corporation of India","National Agricultural Cooperative Marketing Federation (NAFED)","Small Farmers' Agribusiness Consortium (SFAC)","National Bank for Agriculture and Rural Development"],"answer":2,"explanation":"SFAC, under the Ministry of Agriculture and Farmers Welfare, is the lead agency for e-NAM, the online trading portal that links APMC mandis.","difficulty":"hard","source":"IBPS PO · SBI PO · State PSC","questionHi":"अप्रैल 2016 में शुरू किए गए राष्ट्रीय कृषि बाज़ार (e-NAM) का क्रियान्वयन कौन करता है?","optionsHi":["भारतीय खाद्य निगम","राष्ट्रीय कृषि सहकारी विपणन संघ (NAFED)","लघु कृषक कृषि-व्यापार संघ (SFAC)","राष्ट्रीय कृषि और ग्रामीण विकास बैंक"],"explanationHi":"कृषि एवं किसान कल्याण मंत्रालय के अधीन SFAC e-NAM की प्रमुख एजेंसी है, जो APMC मंडियों को जोड़ने वाला ऑनलाइन व्यापार पोर्टल है।"},
  {"id":"eco-sectors-schemes-19","question":"The Kisan Credit Card scheme, introduced in 1998, was based on the recommendations of which committee?","options":["Narasimham Committee","Rangarajan Committee","M.S. Swaminathan Committee","R.V. Gupta Committee"],"answer":3,"explanation":"NABARD prepared the KCC scheme on the R.V. Gupta Committee's recommendations to give farmers timely, flexible credit. Narasimham dealt with banking reforms.","difficulty":"hard","source":"IBPS PO · SBI PO · State PSC","questionHi":"1998 में शुरू की गई किसान क्रेडिट कार्ड योजना किस समिति की सिफारिशों पर आधारित थी?","optionsHi":["नरसिम्हम समिति","रंगराजन समिति","एम.एस. स्वामीनाथन समिति","आर.वी. गुप्ता समिति"],"explanationHi":"NABARD ने किसानों को समय पर, लचीला ऋण देने के लिए आर.वी. गुप्ता समिति की सिफारिशों पर KCC योजना तैयार की। नरसिम्हम समिति बैंकिंग सुधारों से संबंधित थी।"},
  {"id":"eco-sectors-schemes-20","question":"After the 2022 revision, what are the life cover and annual premium under the Pradhan Mantri Jeevan Jyoti Bima Yojana (launched in 2015)?","options":["₹5 lakh cover for ₹436 a year","₹2 lakh cover for ₹436 a year","₹1 lakh cover for ₹330 a year","₹2 lakh cover for ₹20 a year"],"answer":1,"explanation":"PMJJBY gives ₹2 lakh life cover for ₹436 a year (raised from ₹330 in 2022). ₹20 a year is the premium of PMSBY, the accident cover scheme.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"2022 के संशोधन के बाद, प्रधानमंत्री जीवन ज्योति बीमा योजना (2015 में शुरू) के अंतर्गत जीवन बीमा कवर और वार्षिक प्रीमियम क्या हैं?","optionsHi":["₹5 लाख का कवर, ₹436 वार्षिक","₹2 लाख का कवर, ₹436 वार्षिक","₹1 लाख का कवर, ₹330 वार्षिक","₹2 लाख का कवर, ₹20 वार्षिक"],"explanationHi":"PMJJBY ₹436 वार्षिक पर ₹2 लाख का जीवन बीमा कवर देती है (2022 में ₹330 से बढ़ाया गया)। ₹20 वार्षिक दुर्घटना बीमा योजना PMSBY का प्रीमियम है।"},
  {"id":"eco-sectors-schemes-21","question":"The PM Vishwakarma scheme, launched on 17 September 2023, is implemented mainly by which ministry?","options":["Ministry of Social Justice and Empowerment","Ministry of Rural Development","Ministry of Micro, Small and Medium Enterprises","Ministry of Textiles (Development Commissioner, Handicrafts)"],"answer":2,"explanation":"The MSME Ministry runs it jointly with the Ministry of Skill Development and the Department of Financial Services, to support artisans in traditional trades.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"17 सितंबर 2023 को शुरू की गई PM विश्वकर्मा योजना का क्रियान्वयन मुख्यतः किस मंत्रालय द्वारा होता है?","optionsHi":["सामाजिक न्याय और अधिकारिता मंत्रालय","ग्रामीण विकास मंत्रालय","सूक्ष्म, लघु और मध्यम उद्यम मंत्रालय","वस्त्र मंत्रालय (विकास आयुक्त, हस्तशिल्प)"],"explanationHi":"MSME मंत्रालय इसे कौशल विकास मंत्रालय और वित्तीय सेवा विभाग के साथ मिलकर चलाता है, ताकि पारंपरिक व्यवसायों के कारीगरों को सहायता मिल सके।"},
  {"id":"eco-sectors-schemes-22","question":"The Sukanya Samriddhi Yojana was launched in January 2015 as part of which campaign?","options":["Digital India","Pradhan Mantri Jan Dhan Yojana","Swachh Bharat Mission","Beti Bachao Beti Padhao"],"answer":3,"explanation":"Both were launched at Panipat on 22 January 2015. Sukanya Samriddhi is a small savings account for a girl child below 10 years.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सुकन्या समृद्धि योजना जनवरी 2015 में किस अभियान के भाग के रूप में शुरू की गई थी?","optionsHi":["डिजिटल इंडिया","प्रधानमंत्री जन धन योजना","स्वच्छ भारत मिशन","बेटी बचाओ बेटी पढ़ाओ"],"explanationHi":"दोनों 22 जनवरी 2015 को पानीपत में शुरू हुईं। सुकन्या समृद्धि 10 वर्ष से कम आयु की बालिका के लिए एक लघु बचत खाता है।"},
  {"id":"eco-sectors-schemes-23","question":"The Jal Jeevan Mission, announced in 2019 to provide tap-water connections to every rural household, comes under which ministry?","options":["Ministry of Environment, Forest and Climate Change","Ministry of Jal Shakti","Ministry of Housing and Urban Affairs","Ministry of Rural Development"],"answer":1,"explanation":"The Ministry of Jal Shakti, formed in 2019 by merging the water resources and drinking water ministries, runs the ‘Har Ghar Jal’ mission.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"प्रत्येक ग्रामीण परिवार को नल से जल कनेक्शन देने के लिए 2019 में घोषित जल जीवन मिशन किस मंत्रालय के अधीन आता है?","optionsHi":["पर्यावरण, वन और जलवायु परिवर्तन मंत्रालय","जल शक्ति मंत्रालय","आवास और शहरी कार्य मंत्रालय","ग्रामीण विकास मंत्रालय"],"explanationHi":"2019 में जल संसाधन और पेयजल मंत्रालयों को मिलाकर बना जल शक्ति मंत्रालय ‘हर घर जल’ मिशन चलाता है।"},
  {"id":"eco-sectors-schemes-24","question":"The SVAMITVA scheme, launched on National Panchayati Raj Day (24 April) in 2020, aims to:","options":["Map inhabited village land by drone and give owners property cards","Give collateral-free crop loans to tenant and sharecropping farmers","Build pucca houses with basic amenities for the rural homeless","Provide solar pumps and grid-connected solar plants to farmers"],"answer":0,"explanation":"SVAMITVA, run by the Ministry of Panchayati Raj, surveys inhabited village land with drones and issues ‘record of rights’ cards that owners can use to take loans.","difficulty":"hard","source":"IBPS PO · SBI PO · State PSC","questionHi":"राष्ट्रीय पंचायती राज दिवस (24 अप्रैल) 2020 को शुरू की गई स्वामित्व (SVAMITVA) योजना का उद्देश्य क्या है?","optionsHi":["आबादी वाली ग्रामीण भूमि का ड्रोन से मानचित्रण कर स्वामियों को संपत्ति कार्ड देना","काश्तकार और बटाईदार किसानों को बिना गारंटी फसल ऋण देना","ग्रामीण बेघरों के लिए बुनियादी सुविधाओं वाले पक्के मकान बनाना","किसानों को सौर पंप और ग्रिड से जुड़े सौर संयंत्र उपलब्ध कराना"],"explanationHi":"पंचायती राज मंत्रालय द्वारा संचालित SVAMITVA ड्रोन से आबादी वाली ग्रामीण भूमि का सर्वेक्षण करती है और ‘अधिकार अभिलेख’ कार्ड जारी करती है, जिनका उपयोग स्वामी ऋण लेने के लिए कर सकते हैं।"},
  {"id":"eco-sectors-schemes-25","question":"Arrange these schemes in the order they were launched: 1. Pradhan Mantri Jan Dhan Yojana 2. PM-KISAN 3. Stand-Up India 4. Pradhan Mantri MUDRA Yojana","options":["1, 3, 4, 2","1, 4, 3, 2","4, 1, 3, 2","1, 4, 2, 3"],"answer":1,"explanation":"Jan Dhan (August 2014), MUDRA (April 2015), Stand-Up India (April 2016), PM-KISAN (February 2019). Order: 1, 4, 3, 2.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"इन योजनाओं को उनके शुरू होने के क्रम में व्यवस्थित कीजिए: 1. प्रधानमंत्री जन धन योजना 2. PM-KISAN 3. स्टैंड-अप इंडिया 4. प्रधानमंत्री मुद्रा योजना","optionsHi":["1, 3, 4, 2","1, 4, 3, 2","4, 1, 3, 2","1, 4, 2, 3"],"explanationHi":"जन धन (अगस्त 2014), मुद्रा (अप्रैल 2015), स्टैंड-अप इंडिया (अप्रैल 2016), PM-KISAN (फरवरी 2019)। क्रम: 1, 4, 3, 2।"},
  {"id":"eco-sectors-schemes-26","question":"Match the scheme with its nodal ministry: 1. PM Ujjwala Yojana 2. PMAY-Gramin 3. PM MITRA parks 4. PM-JAY; a. Health and Family Welfare b. Textiles c. Rural Development d. Petroleum and Natural Gas","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-a, 4-b"],"answer":0,"explanation":"Ujjwala – Petroleum and Natural Gas, PMAY-G – Rural Development, PM MITRA (mega textile parks, 2021) – Textiles, PM-JAY – Health and Family Welfare (implemented through the National Health Authority).","difficulty":"very-hard","source":"IBPS PO · SBI PO · State PSC","questionHi":"योजना का उसके नोडल मंत्रालय से मिलान कीजिए: 1. PM उज्ज्वला योजना 2. PMAY-ग्रामीण 3. PM MITRA पार्क 4. PM-JAY; a. स्वास्थ्य और परिवार कल्याण b. वस्त्र c. ग्रामीण विकास d. पेट्रोलियम और प्राकृतिक गैस","optionsHi":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-a, 4-b"],"explanationHi":"उज्ज्वला – पेट्रोलियम और प्राकृतिक गैस, PMAY-G – ग्रामीण विकास, PM MITRA (मेगा टेक्सटाइल पार्क, 2021) – वस्त्र, PM-JAY – स्वास्थ्य और परिवार कल्याण (राष्ट्रीय स्वास्थ्य प्राधिकरण के माध्यम से क्रियान्वित)।"},
  {"id":"eco-sectors-schemes-27","question":"How many of these statements about the Pradhan Mantri MUDRA Yojana are correct? I. It was launched in April 2015. II. The ‘Kishore’ category covers loans from ₹50,000 to ₹5 lakh. III. The ‘Tarun’ category covers loans from ₹5 lakh to ₹10 lakh. IV. MUDRA loans can be given only for crop cultivation.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: MUDRA funds non-farm micro enterprises in manufacturing, trading and services, plus activities allied to agriculture, not crop loans.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"प्रधानमंत्री मुद्रा योजना के बारे में इनमें से कितने कथन सही हैं? I. इसे अप्रैल 2015 में शुरू किया गया। II. ‘किशोर’ श्रेणी ₹50,000 से ₹5 लाख तक के ऋण कवर करती है। III. ‘तरुण’ श्रेणी ₹5 लाख से ₹10 लाख तक के ऋण कवर करती है। IV. मुद्रा ऋण केवल फसल की खेती के लिए दिए जा सकते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: मुद्रा विनिर्माण, व्यापार और सेवाओं में गैर-कृषि सूक्ष्म उद्यमों तथा कृषि से संबद्ध गतिविधियों को वित्त देती है, फसल ऋण को नहीं।"},
  {"id":"eco-sectors-schemes-28","question":"Assertion (A): PM-KISAN money is transferred directly into the bank accounts of beneficiary farmers. Reason (R): PM-KISAN is a Central Sector Scheme fully funded by the Government of India.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but the direct transfer comes from the scheme's Direct Benefit Transfer design, not from who funds it. A centrally funded scheme could in principle pay out through other channels.","difficulty":"very-hard","source":"IBPS PO · SBI PO · State PSC","questionHi":"अभिकथन (A): PM-KISAN की राशि सीधे लाभार्थी किसानों के बैंक खातों में अंतरित की जाती है। कारण (R): PM-KISAN एक केंद्रीय क्षेत्र की योजना है जिसे पूरी तरह भारत सरकार वित्तपोषित करती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं, पर सीधा अंतरण योजना की प्रत्यक्ष लाभ अंतरण (DBT) की बनावट से आता है, इस बात से नहीं कि वित्तपोषण कौन करता है। केंद्र द्वारा वित्तपोषित योजना सिद्धांततः अन्य माध्यमों से भी भुगतान कर सकती है।"},
  {"id":"eco-sectors-schemes-29","question":"Under the MSME criteria notified in 2020, an enterprise with ₹8 crore invested in plant and machinery and an annual turnover of ₹60 crore is classified as:","options":["Micro","Large","Small","Medium"],"answer":3,"explanation":"Both limits must be met. Investment ₹8 crore fits ‘small’ (≤ ₹10 crore), but turnover ₹60 crore exceeds the small limit of ₹50 crore, so it is ‘medium’ (≤ ₹50 crore investment, ≤ ₹250 crore turnover).","difficulty":"very-hard","source":"IBPS PO · SBI PO · State PSC","questionHi":"2020 में अधिसूचित MSME मानदंडों के अंतर्गत, जिस उद्यम का संयंत्र और मशीनरी में निवेश ₹8 करोड़ और वार्षिक टर्नओवर ₹60 करोड़ है, उसे वर्गीकृत किया जाएगा:","optionsHi":["सूक्ष्म","बड़ा","लघु","मध्यम"],"explanationHi":"दोनों सीमाएँ पूरी होनी चाहिए। ₹8 करोड़ का निवेश ‘लघु’ (≤ ₹10 करोड़) में आता है, पर ₹60 करोड़ का टर्नओवर लघु की ₹50 करोड़ की सीमा से अधिक है, इसलिए यह ‘मध्यम’ है (≤ ₹50 करोड़ निवेश, ≤ ₹250 करोड़ टर्नओवर)।"},
  {"id":"eco-sectors-schemes-30","question":"How many of these statements about the Pradhan Mantri Fasal Bima Yojana are correct? I. It was launched in 2016, replacing NAIS and the modified NAIS. II. The farmer's premium for annual commercial and horticultural crops is 5%. III. It is run by the Ministry of Agriculture and Farmers Welfare. IV. Since Kharif 2020, enrolment is voluntary for all farmers, including loanee farmers.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Before 2020, enrolment was compulsory for farmers taking crop loans; the 2020 revamp made it voluntary for everyone.","difficulty":"very-hard","source":"IBPS PO · SBI PO · State PSC","questionHi":"प्रधानमंत्री फसल बीमा योजना के बारे में इनमें से कितने कथन सही हैं? I. इसे 2016 में शुरू किया गया, जिसने NAIS और संशोधित NAIS का स्थान लिया। II. वार्षिक वाणिज्यिक और बागवानी फसलों के लिए किसान का प्रीमियम 5% है। III. इसका संचालन कृषि एवं किसान कल्याण मंत्रालय करता है। IV. खरीफ 2020 से सभी किसानों, ऋणी किसानों सहित, के लिए नामांकन स्वैच्छिक है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। 2020 से पहले फसल ऋण लेने वाले किसानों के लिए नामांकन अनिवार्य था; 2020 के नवीनीकरण ने इसे सभी के लिए स्वैच्छिक बना दिया।"},
  {"id":"eco-sectors-schemes-31","question":"Match the scheme with its main beneficiaries: 1. PM SVANidhi 2. Stand-Up India 3. PM Vishwakarma 4. PM-KUSUM; a. Artisans and craftspeople b. Street vendors c. Farmers installing solar pumps d. SC/ST and women entrepreneurs","options":["1-b, 2-a, 3-d, 4-c","1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-c, 4-a","1-b, 2-d, 3-a, 4-c"],"answer":3,"explanation":"SVANidhi – street vendors, Stand-Up India – SC/ST and women entrepreneurs, PM Vishwakarma – artisans, PM-KUSUM (2019) – solar pumps and solar plants for farmers.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"योजना का उसके मुख्य लाभार्थियों से मिलान कीजिए: 1. PM SVANidhi 2. स्टैंड-अप इंडिया 3. PM विश्वकर्मा 4. PM-KUSUM; a. कारीगर और शिल्पकार b. रेहड़ी-पटरी वाले c. सौर पंप लगाने वाले किसान d. SC/ST और महिला उद्यमी","optionsHi":["1-b, 2-a, 3-d, 4-c","1-d, 2-b, 3-a, 4-c","1-b, 2-d, 3-c, 4-a","1-b, 2-d, 3-a, 4-c"],"explanationHi":"SVANidhi – रेहड़ी-पटरी वाले, स्टैंड-अप इंडिया – SC/ST और महिला उद्यमी, PM विश्वकर्मा – कारीगर, PM-KUSUM (2019) – किसानों के लिए सौर पंप और सौर संयंत्र।"},
  {"id":"eco-sectors-schemes-32","question":"Which pair of scheme and launch year is NOT correct?","options":["PM Garib Kalyan Anna Yojana – 2016","Smart Cities Mission – 2015","Pradhan Mantri Jan Dhan Yojana – 2014","PM Gati Shakti – 2021"],"answer":0,"explanation":"PM Garib Kalyan Anna Yojana began in April 2020 as COVID-19 food relief; 2016 is the year of demonetisation and Ujjwala, a common mix-up. Jan Dhan (August 2014), Smart Cities Mission (June 2015) and PM Gati Shakti (October 2021) are correct.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"योजना और उसके शुरू होने के वर्ष का कौन-सा युग्म सही नहीं है?","optionsHi":["PM गरीब कल्याण अन्न योजना – 2016","स्मार्ट सिटी मिशन – 2015","प्रधानमंत्री जन धन योजना – 2014","PM गति शक्ति – 2021"],"explanationHi":"PM गरीब कल्याण अन्न योजना अप्रैल 2020 में COVID-19 खाद्य राहत के रूप में शुरू हुई; 2016 नोटबंदी और उज्ज्वला का वर्ष है, जो एक आम भूल है। जन धन (अगस्त 2014), स्मार्ट सिटी मिशन (जून 2015) और PM गति शक्ति (अक्टूबर 2021) सही हैं।"},
  {"id":"eco-sectors-schemes-33","question":"Assertion (A): MGNREGA, enacted in 2005, is called a demand-driven scheme. Reason (R): If work is not given within 15 days of applying, the applicant is entitled to an unemployment allowance.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: work must be provided whenever a household demands it, and the legal penalty of an unemployment allowance is what makes the guarantee demand-driven rather than budget-capped.","difficulty":"very-hard","source":"IBPS PO · SBI PO · State PSC","questionHi":"अभिकथन (A): 2005 में अधिनियमित MGNREGA को मांग-आधारित योजना कहा जाता है। कारण (R): यदि आवेदन के 15 दिन के भीतर काम नहीं दिया जाता, तो आवेदक बेरोज़गारी भत्ते का हकदार है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है: जब भी कोई परिवार मांग करे, काम देना होता है, और बेरोज़गारी भत्ते का कानूनी दंड ही गारंटी को बजट-सीमित के बजाय मांग-आधारित बनाता है।"},
  {"id":"eco-sectors-schemes-34","question":"Arrange these agricultural initiatives in the order they were launched: 1. e-NAM 2. Kisan Credit Card 3. PM-KUSUM 4. Soil Health Card","options":["2, 4, 3, 1","2, 1, 4, 3","4, 2, 1, 3","2, 4, 1, 3"],"answer":3,"explanation":"Kisan Credit Card (1998), Soil Health Card (February 2015), e-NAM (April 2016), PM-KUSUM (2019). Order: 2, 4, 1, 3.","difficulty":"very-hard","source":"IBPS PO · SBI PO · State PSC","questionHi":"इन कृषि पहलों को उनके शुरू होने के क्रम में व्यवस्थित कीजिए: 1. e-NAM 2. किसान क्रेडिट कार्ड 3. PM-KUSUM 4. मृदा स्वास्थ्य कार्ड","optionsHi":["2, 4, 3, 1","2, 1, 4, 3","4, 2, 1, 3","2, 4, 1, 3"],"explanationHi":"किसान क्रेडिट कार्ड (1998), मृदा स्वास्थ्य कार्ड (फरवरी 2015), e-NAM (अप्रैल 2016), PM-KUSUM (2019)। क्रम: 2, 4, 1, 3।"},
  {"id":"eco-sectors-schemes-35","question":"A 30-year-old enrols in both PMJJBY and PMSBY in 2023. What is the total annual premium?","options":["₹436","₹342","₹456","₹330"],"answer":2,"explanation":"PMJJBY costs ₹436 and PMSBY ₹20 a year (both revised in June 2022), so the total is ₹456. ₹342 (₹330 + ₹12) was the total before the revision.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"30 वर्ष का एक व्यक्ति 2023 में PMJJBY और PMSBY दोनों में नामांकन कराता है। कुल वार्षिक प्रीमियम क्या है?","optionsHi":["₹436","₹342","₹456","₹330"],"explanationHi":"PMJJBY का प्रीमियम ₹436 और PMSBY का ₹20 वार्षिक है (दोनों जून 2022 में संशोधित), इसलिए कुल ₹456 है। ₹342 (₹330 + ₹12) संशोधन से पहले का कुल था।"},
  {"id":"eco-sectors-schemes-36","question":"How many of these statements about Ayushman Bharat – PM-JAY are correct? I. It was launched in September 2018 from Ranchi. II. It covers up to ₹5 lakh per family per year for secondary and tertiary hospitalisation. III. It is implemented by the National Health Authority. IV. It covers routine OPD consultations at any private clinic.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: PM-JAY covers hospitalisation, including pre- and post-hospitalisation expenses, not routine outpatient visits.","difficulty":"very-hard","source":"IBPS PO · SBI PO · State PSC","questionHi":"आयुष्मान भारत – PM-JAY के बारे में इनमें से कितने कथन सही हैं? I. इसे सितंबर 2018 में राँची से शुरू किया गया। II. यह द्वितीयक और तृतीयक अस्पताल में भर्ती के लिए प्रति परिवार प्रति वर्ष ₹5 लाख तक कवर करती है। III. इसका क्रियान्वयन राष्ट्रीय स्वास्थ्य प्राधिकरण करता है। IV. यह किसी भी निजी क्लिनिक में नियमित OPD परामर्श कवर करती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: PM-JAY अस्पताल में भर्ती, भर्ती से पहले और बाद के खर्चों सहित, कवर करती है, नियमित बाह्य रोगी परामर्श नहीं।"},
  {"id":"eco-sectors-schemes-37","question":"Arrange these core industries in descending order of their weight in the Index of Eight Core Industries (base 2011-12): 1. Coal 2. Electricity 3. Steel 4. Refinery products","options":["4, 3, 2, 1","4, 2, 3, 1","2, 4, 3, 1","4, 2, 1, 3"],"answer":1,"explanation":"Refinery products 28.04%, electricity 19.85%, steel 17.92%, coal 10.33%. Order: 4, 2, 3, 1.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"आठ प्रमुख उद्योगों के सूचकांक (आधार 2011-12) में इन प्रमुख उद्योगों को उनके भारांक के घटते क्रम में व्यवस्थित कीजिए: 1. कोयला 2. बिजली 3. इस्पात 4. रिफाइनरी उत्पाद","optionsHi":["4, 3, 2, 1","4, 2, 3, 1","2, 4, 3, 1","4, 2, 1, 3"],"explanationHi":"रिफाइनरी उत्पाद 28.04%, बिजली 19.85%, इस्पात 17.92%, कोयला 10.33%। क्रम: 4, 2, 3, 1।"},
  {"id":"eco-sectors-schemes-38","question":"How many of these activities belong to the tertiary sector? Banking, Transport, Construction, Mining","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Banking and transport are services (tertiary). Construction is part of the secondary (industry) sector and mining is primary. So only two.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"इनमें से कितनी गतिविधियाँ तृतीयक क्षेत्र की हैं? बैंकिंग, परिवहन, निर्माण, खनन","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"बैंकिंग और परिवहन सेवाएँ (तृतीयक) हैं। निर्माण द्वितीयक (उद्योग) क्षेत्र का भाग है और खनन प्राथमिक। इसलिए केवल दो।"},
  {"id":"eco-sectors-schemes-39","question":"The PM Surya Ghar Muft Bijli Yojana, launched in 2024, aims at rooftop solar for how many households, with up to how many free units of electricity a month?","options":["1 crore households, 300 units","1 crore households, 200 units","5 crore households, 100 units","10 crore households, 300 units"],"answer":0,"explanation":"The scheme of the Ministry of New and Renewable Energy targets 1 crore households, giving up to 300 units a month of free electricity through subsidised rooftop solar panels.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"2024 में शुरू की गई PM सूर्य घर मुफ़्त बिजली योजना का उद्देश्य कितने घरों में रूफटॉप सौर ऊर्जा लगाना है और प्रति माह अधिकतम कितनी यूनिट मुफ़्त बिजली देना है?","optionsHi":["1 करोड़ परिवार, 300 यूनिट","1 करोड़ परिवार, 200 यूनिट","5 करोड़ परिवार, 100 यूनिट","10 करोड़ परिवार, 300 यूनिट"],"explanationHi":"नवीन और नवीकरणीय ऊर्जा मंत्रालय की यह योजना 1 करोड़ परिवारों को लक्षित करती है और अनुदानित रूफटॉप सौर पैनलों के माध्यम से प्रति माह 300 यूनिट तक मुफ़्त बिजली देती है।"},
  {"id":"eco-sectors-schemes-40","question":"How many of these statements about PM Vishwakarma (2023) are correct? I. It was launched on 17 September 2023. II. It covers artisans in 18 traditional trades. III. Collateral-free credit of up to ₹3 lakh is given in two tranches. IV. The loans carry a concessional interest rate of 5%.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: launched on Vishwakarma Jayanti, 18 trades (such as carpenters, blacksmiths, potters and tailors), ₹1 lakh followed by ₹2 lakh, at 5% interest.","difficulty":"very-hard","source":"IBPS PO · SBI PO · State PSC","questionHi":"PM विश्वकर्मा (2023) के बारे में इनमें से कितने कथन सही हैं? I. इसे 17 सितंबर 2023 को शुरू किया गया। II. यह 18 पारंपरिक व्यवसायों के कारीगरों को कवर करती है। III. ₹3 लाख तक का बिना गारंटी का ऋण दो किस्तों में दिया जाता है। IV. ऋणों पर 5% की रियायती ब्याज दर लगती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: विश्वकर्मा जयंती पर शुरू हुई, 18 व्यवसाय (जैसे बढ़ई, लोहार, कुम्हार और दर्जी), ₹1 लाख और उसके बाद ₹2 लाख, 5% ब्याज पर।"},
  {"id":"eco-sectors-schemes-41","question":"Which of these activities belongs to the primary sector of the economy?","options":["Fishing","Banking","Making sugar in a mill","Writing software"],"answer":0,"explanation":"The primary sector directly uses natural resources: farming, fishing, forestry and mining. Sugar milling is secondary (manufacturing); banking and software are tertiary (services).","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"इनमें से कौन-सी गतिविधि अर्थव्यवस्था के प्राथमिक क्षेत्र की है?","optionsHi":["मत्स्य पालन","बैंकिंग","मिल में चीनी बनाना","सॉफ्टवेयर लिखना"],"explanationHi":"प्राथमिक क्षेत्र सीधे प्राकृतिक संसाधनों का उपयोग करता है: कृषि, मत्स्य पालन, वानिकी और खनन। चीनी मिल का काम द्वितीयक (विनिर्माण) है; बैंकिंग और सॉफ्टवेयर तृतीयक (सेवाएँ) हैं।"},
  {"id":"eco-sectors-schemes-42","question":"Turning sugarcane into sugar in a factory is an activity of the:","options":["Primary sector","Secondary sector","Tertiary sector","Informal service sector"],"answer":1,"explanation":"The secondary (industrial) sector transforms raw materials into goods through manufacturing. Growing the cane is primary; selling or transporting the sugar is tertiary.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"कारखाने में गन्ने से चीनी बनाना किस क्षेत्र की गतिविधि है?","optionsHi":["प्राथमिक क्षेत्र","द्वितीयक क्षेत्र","तृतीयक क्षेत्र","अनौपचारिक सेवा क्षेत्र"],"explanationHi":"द्वितीयक (औद्योगिक) क्षेत्र विनिर्माण द्वारा कच्चे माल को वस्तुओं में बदलता है। गन्ना उगाना प्राथमिक है; चीनी बेचना या ढोना तृतीयक है।"},
  {"id":"eco-sectors-schemes-43","question":"The tertiary sector of the economy is also known as the:","options":["Industrial sector","Agricultural sector","Service sector","Extractive sector"],"answer":2,"explanation":"The tertiary sector produces services rather than goods: trade, transport, banking, communication, health, education and so on.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"अर्थव्यवस्था का तृतीयक क्षेत्र और किस नाम से जाना जाता है?","optionsHi":["औद्योगिक क्षेत्र","कृषि क्षेत्र","सेवा क्षेत्र","निष्कर्षण क्षेत्र"],"explanationHi":"तृतीयक क्षेत्र वस्तुओं के बजाय सेवाएँ उत्पन्न करता है: व्यापार, परिवहन, बैंकिंग, संचार, स्वास्थ्य, शिक्षा आदि।"},
  {"id":"eco-sectors-schemes-44","question":"Eight members of a family work on a small farm that needs only five people. The extra three are an example of:","options":["Seasonal unemployment","Frictional unemployment","Open unemployment","Disguised unemployment"],"answer":3,"explanation":"In disguised unemployment people appear to be working, but their marginal contribution is nearly zero: output would not fall if they left. It is common in Indian agriculture.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"एक परिवार के आठ सदस्य एक छोटे खेत पर काम करते हैं जिसे केवल पाँच लोगों की ज़रूरत है। अतिरिक्त तीन सदस्य किसका उदाहरण हैं?","optionsHi":["मौसमी बेरोज़गारी","घर्षणात्मक बेरोज़गारी","खुली बेरोज़गारी","छिपी हुई (प्रच्छन्न) बेरोज़गारी"],"explanationHi":"प्रच्छन्न बेरोज़गारी में लोग काम करते दिखते हैं, पर उनका सीमांत योगदान लगभग शून्य होता है: उनके हट जाने पर भी उत्पादन नहीं घटेगा। यह भारतीय कृषि में आम है।"},
  {"id":"eco-sectors-schemes-45","question":"Farm labourers who find work only during sowing and harvesting, and sit idle for the rest of the year, face:","options":["Seasonal unemployment","Structural unemployment","Disguised unemployment","Cyclical unemployment"],"answer":0,"explanation":"Seasonal unemployment arises because some activities, like rain-fed farming, need labour only in certain months. Structural unemployment comes from a long-term mismatch between skills and jobs.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"वे खेतिहर मज़दूर जिन्हें केवल बुवाई और कटाई के समय काम मिलता है और शेष वर्ष वे बेकार बैठे रहते हैं, किस प्रकार की बेरोज़गारी का सामना करते हैं?","optionsHi":["मौसमी बेरोज़गारी","संरचनात्मक बेरोज़गारी","प्रच्छन्न बेरोज़गारी","चक्रीय बेरोज़गारी"],"explanationHi":"मौसमी बेरोज़गारी इसलिए होती है कि कुछ गतिविधियों, जैसे वर्षा-आधारित खेती, में श्रम की ज़रूरत कुछ ही महीनों में होती है। संरचनात्मक बेरोज़गारी कौशल और रोज़गार के बीच दीर्घकालिक असंगति से आती है।"},
  {"id":"eco-sectors-schemes-46","question":"Which feature best distinguishes organised-sector employment from unorganised-sector employment?","options":["It is located mainly in cities, while the unorganised sector is rural","It always pays workers piece rates rather than monthly wages","It is never run by private firms, only by the government","It is registered and follows rules on wages, hours and social security"],"answer":1,"explanation":"Organised-sector enterprises are registered and must follow laws such as the Factories Act, giving regular jobs, paid leave and provident fund. Private firms can be organised too.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"कौन-सी विशेषता संगठित क्षेत्र के रोज़गार को असंगठित क्षेत्र के रोज़गार से सबसे अच्छी तरह अलग करती है?","optionsHi":["यह मुख्यतः शहरों में स्थित है, जबकि असंगठित क्षेत्र ग्रामीण है","यह हमेशा मासिक वेतन के बजाय नग-दर (पीस रेट) पर भुगतान करता है","इसे कभी निजी फर्में नहीं चलातीं, केवल सरकार चलाती है","यह पंजीकृत होता है और मज़दूरी, कार्य-घंटों और सामाजिक सुरक्षा के नियमों का पालन करता है"],"explanationHi":"संगठित क्षेत्र के उद्यम पंजीकृत होते हैं और कारखाना अधिनियम जैसे कानूनों का पालन करते हैं, जिससे नियमित नौकरियाँ, सवेतन अवकाश और भविष्य निधि मिलती है। निजी फर्में भी संगठित हो सकती हैं।"},
  {"id":"eco-sectors-schemes-47","question":"Indian Railways, which is owned and run by the government, is an example of the:","options":["Private sector","Joint sector","Public sector","Cooperative sector"],"answer":2,"explanation":"When the government owns most assets and provides the service, the enterprise is in the public sector. A joint sector unit has both government and private ownership.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"भारतीय रेल, जो सरकार के स्वामित्व और संचालन में है, किसका उदाहरण है?","optionsHi":["निजी क्षेत्र","संयुक्त क्षेत्र","सार्वजनिक क्षेत्र","सहकारी क्षेत्र"],"explanationHi":"जब अधिकांश परिसंपत्तियाँ सरकार की हों और सेवा भी वही दे, तो उद्यम सार्वजनिक क्षेत्र में होता है। संयुक्त क्षेत्र की इकाई में सरकारी और निजी दोनों का स्वामित्व होता है।"},
  {"id":"eco-sectors-schemes-48","question":"The “JAM trinity” used to deliver benefits directly to people refers to:","options":["Jobs, Agriculture, Manufacturing","Jan Aushadhi, Ayushman, MGNREGA","Jute, Apparel, Machinery","Jan Dhan, Aadhaar, Mobile"],"answer":3,"explanation":"Linking Jan Dhan bank accounts, Aadhaar identity and mobile phones lets the government credit subsidies straight to beneficiaries and confirm their identity, cutting out intermediaries.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"लोगों तक सीधे लाभ पहुँचाने के लिए प्रयुक्त “JAM त्रयी” से क्या तात्पर्य है?","optionsHi":["रोज़गार, कृषि, विनिर्माण","जन औषधि, आयुष्मान, MGNREGA","जूट, परिधान, मशीनरी","जन धन, आधार, मोबाइल"],"explanationHi":"जन धन बैंक खातों, आधार पहचान और मोबाइल फ़ोन को जोड़ने से सरकार सब्सिडी सीधे लाभार्थियों के खाते में जमा कर सकती है और उनकी पहचान की पुष्टि कर सकती है, जिससे बिचौलिए हट जाते हैं।"},
  {"id":"eco-sectors-schemes-49","question":"The main aim of Direct Benefit Transfer (DBT) is to:","options":["Cut leakages by paying benefits into bank accounts","Raise more revenue by taxing all welfare benefits","Replace all subsidies with repayable low-interest bank loans","Give benefits only in kind through fair price shops"],"answer":0,"explanation":"DBT sends cash benefits straight to Aadhaar-seeded bank accounts, removing middlemen and fake beneficiaries. It complements, not abolishes, in-kind support like PDS grain.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"प्रत्यक्ष लाभ अंतरण (DBT) का मुख्य उद्देश्य क्या है?","optionsHi":["लाभ बैंक खातों में देकर रिसाव घटाना","सभी कल्याणकारी लाभों पर कर लगाकर अधिक राजस्व जुटाना","सभी सब्सिडियों की जगह चुकाने योग्य कम ब्याज वाले बैंक ऋण देना","लाभ केवल उचित मूल्य की दुकानों से वस्तु रूप में देना"],"explanationHi":"DBT नकद लाभ सीधे आधार से जुड़े बैंक खातों में भेजता है, जिससे बिचौलिए और फर्जी लाभार्थी हट जाते हैं। यह PDS अनाज जैसी वस्तु-रूप सहायता का पूरक है, उसका अंत नहीं करता।"},
  {"id":"eco-sectors-schemes-50","question":"The National Food Security Act, 2013 provides for coverage of up to:","options":["50% of the rural and 75% of the urban population","75% of the rural and 50% of the urban population","100% of the population","Only families below the poverty line in rural areas"],"answer":1,"explanation":"The Act covers up to 75% of rural and 50% of urban people, about two-thirds of the population, through Antyodaya and priority households. The reversed percentages are the usual trap.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"राष्ट्रीय खाद्य सुरक्षा अधिनियम, 2013 कितनी जनसंख्या तक कवरेज का प्रावधान करता है?","optionsHi":["ग्रामीण जनसंख्या का 50% और शहरी जनसंख्या का 75%","ग्रामीण जनसंख्या का 75% और शहरी जनसंख्या का 50%","जनसंख्या का 100%","केवल ग्रामीण क्षेत्रों के गरीबी रेखा से नीचे के परिवार"],"explanationHi":"अधिनियम अंत्योदय और प्राथमिकता परिवारों के माध्यम से ग्रामीण जनसंख्या के 75% और शहरी के 50% तक को, यानी लगभग दो-तिहाई जनसंख्या को, कवर करता है। उलटे प्रतिशत आम जाल हैं।"},
  {"id":"eco-sectors-schemes-51","question":"Under the National Food Security Act, 2013, a priority household is entitled to how much subsidised foodgrain, while an Antyodaya household gets a fixed amount per family?","options":["10 kg per family per month","35 kg per person per month","5 kg per person per month","2 kg per person per week"],"answer":2,"explanation":"Priority households get 5 kg per person per month; Antyodaya Anna Yojana households, the poorest, get 35 kg per household per month. Mixing up per-person and per-household is the trap.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"राष्ट्रीय खाद्य सुरक्षा अधिनियम, 2013 के अंतर्गत, प्राथमिकता परिवार कितना सब्सिडी वाला खाद्यान्न पाने का हकदार है, जबकि अंत्योदय परिवार को प्रति परिवार एक निश्चित मात्रा मिलती है?","optionsHi":["प्रति परिवार प्रति माह 10 kg","प्रति व्यक्ति प्रति माह 35 kg","प्रति व्यक्ति प्रति माह 5 kg","प्रति व्यक्ति प्रति सप्ताह 2 kg"],"explanationHi":"प्राथमिकता परिवारों को प्रति व्यक्ति प्रति माह 5 kg मिलता है; अंत्योदय अन्न योजना के परिवारों, जो सबसे गरीब हैं, को प्रति परिवार प्रति माह 35 kg मिलता है। प्रति व्यक्ति और प्रति परिवार को आपस में मिला देना जाल है।"},
  {"id":"eco-sectors-schemes-52","question":"The One Nation One Ration Card system allows:","options":["Every citizen to get free grain without needing a ration card","Only one ration card per state, issued and verified by the Centre","Ration cards to be used as identity proof for voting","NFSA beneficiaries to draw ration at any fair price shop"],"answer":3,"explanation":"Through biometric authentication at ePoS machines, a ration card is portable, which helps migrant workers draw grain wherever they live while their family uses the same card at home.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"‘एक राष्ट्र एक राशन कार्ड’ व्यवस्था क्या अनुमति देती है?","optionsHi":["हर नागरिक को राशन कार्ड के बिना निःशुल्क अनाज मिलना","प्रत्येक राज्य में केवल एक राशन कार्ड, जिसे केंद्र जारी और सत्यापित करे","राशन कार्ड का मतदान के लिए पहचान प्रमाण के रूप में उपयोग","NFSA लाभार्थियों का किसी भी उचित मूल्य की दुकान से राशन लेना"],"explanationHi":"ePoS मशीनों पर बायोमेट्रिक प्रमाणीकरण के माध्यम से राशन कार्ड पोर्टेबल हो जाता है, जिससे प्रवासी मज़दूर जहाँ रहते हैं वहीं अनाज ले सकते हैं, जबकि उनका परिवार घर पर उसी कार्ड का उपयोग करता है।"},
  {"id":"eco-sectors-schemes-53","question":"Under MGNREGA, if work is provided beyond a radius of 5 km from the worker's village, the worker is entitled to:","options":["Extra wages of 10% of the wage rate","Free transport only","Double wages","Nothing extra, as distance does not matter"],"answer":0,"explanation":"The Act's Schedule II says work should normally be within 5 km; if it is farther, it must be within the block and the worker gets 10% extra wages to cover travel and living costs.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"MGNREGA के अंतर्गत, यदि काम श्रमिक के गाँव से 5 km की त्रिज्या से बाहर दिया जाए, तो श्रमिक किसका हकदार है?","optionsHi":["मज़दूरी दर का 10% अतिरिक्त वेतन","केवल निःशुल्क परिवहन","दोगुना वेतन","कुछ अतिरिक्त नहीं, क्योंकि दूरी मायने नहीं रखती"],"explanationHi":"अधिनियम की अनुसूची II कहती है कि काम सामान्यतः 5 km के भीतर होना चाहिए; यदि दूर हो, तो वह खंड के भीतर होना चाहिए और श्रमिक को यात्रा तथा रहने के खर्च के लिए 10% अतिरिक्त मज़दूरी मिलती है।"},
  {"id":"eco-sectors-schemes-54","question":"MGNREGA requires that, as far as possible, women make up at least what share of the beneficiaries?","options":["One-half","One-third","One-fourth","One-tenth"],"answer":1,"explanation":"The Act gives priority to women so that at least one-third of beneficiaries are women who have registered and asked for work. In practice women's share of person-days has often been higher.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"MGNREGA की अपेक्षा है कि यथासंभव महिलाएँ लाभार्थियों का कम से कम कितना हिस्सा हों?","optionsHi":["एक-आधा","एक-तिहाई","एक-चौथाई","एक-दसवाँ"],"explanationHi":"अधिनियम महिलाओं को प्राथमिकता देता है ताकि पंजीकृत होकर काम मांगने वाले लाभार्थियों में कम से कम एक-तिहाई महिलाएँ हों। व्यवहार में व्यक्ति-दिवसों में महिलाओं का हिस्सा प्रायः अधिक रहा है।"},
  {"id":"eco-sectors-schemes-55","question":"Under MGNREGA, the social audit of all works taken up in a Gram Panchayat is carried out by the:","options":["Comptroller and Auditor General","District Collector","Gram Sabha","State Election Commission"],"answer":2,"explanation":"Section 17 makes the Gram Sabha responsible for monitoring works and conducting regular social audits, so villagers themselves can check muster rolls and spending.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"MGNREGA के अंतर्गत किसी ग्राम पंचायत में लिए गए सभी कार्यों की सामाजिक अंकेक्षण (सोशल ऑडिट) कौन करता है?","optionsHi":["नियंत्रक एवं महालेखा परीक्षक","जिला कलेक्टर","ग्राम सभा","राज्य निर्वाचन आयोग"],"explanationHi":"धारा 17 ग्राम सभा को कार्यों की निगरानी और नियमित सामाजिक अंकेक्षण का दायित्व देती है, ताकि ग्रामीण स्वयं मस्टर रोल और खर्च की जाँच कर सकें।"},
  {"id":"eco-sectors-schemes-56","question":"For works taken up by a Gram Panchayat under MGNREGA, the ratio of wage cost to material cost must be at least:","options":["40:60","50:50","75:25","60:40"],"answer":3,"explanation":"The Act caps the material component at 40% at the Gram Panchayat level so that most spending goes into wages for unskilled labour, which is the purpose of the scheme.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"MGNREGA के अंतर्गत ग्राम पंचायत द्वारा लिए गए कार्यों के लिए मज़दूरी लागत और सामग्री लागत का अनुपात कम से कम कितना होना चाहिए?","optionsHi":["40:60","50:50","75:25","60:40"],"explanationHi":"अधिनियम ग्राम पंचायत स्तर पर सामग्री घटक को 40% तक सीमित करता है, ताकि अधिकांश व्यय अकुशल श्रम की मज़दूरी में जाए, जो योजना का उद्देश्य है।"},
  {"id":"eco-sectors-schemes-57","question":"Activities centred on research, information and knowledge, such as R&D, data processing and consulting, are often grouped as the:","options":["Quaternary sector","Primary sector","Secondary sector","Unorganised sector"],"answer":0,"explanation":"Geographers split services further: the quaternary sector covers knowledge-based work, and the quinary sector covers top-level decision-makers in government and business.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"अनुसंधान, सूचना और ज्ञान पर केंद्रित गतिविधियाँ, जैसे R&D, डेटा प्रोसेसिंग और परामर्श, प्रायः किस रूप में वर्गीकृत की जाती हैं?","optionsHi":["चतुर्थक क्षेत्र","प्राथमिक क्षेत्र","द्वितीयक क्षेत्र","असंगठित क्षेत्र"],"explanationHi":"भूगोलवेत्ता सेवाओं को और विभाजित करते हैं: चतुर्थक क्षेत्र में ज्ञान-आधारित कार्य आते हैं, और पंचक (क्विनरी) क्षेत्र में सरकार और व्यवसाय के शीर्ष निर्णयकर्ता।"},
  {"id":"eco-sectors-schemes-58","question":"Kudumbashree, launched in 1998, is a poverty-eradication and women's empowerment programme of which state, organised around neighbourhood groups of women?","options":["Tamil Nadu","Kerala","Andhra Pradesh","Gujarat"],"answer":1,"explanation":"Kerala's Kudumbashree works through a three-tier structure of neighbourhood groups, area development societies and community development societies linked to local governments.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"1998 में शुरू हुआ कुदुम्बश्री, महिलाओं के पड़ोस समूहों पर आधारित, किस राज्य का गरीबी उन्मूलन और महिला सशक्तीकरण कार्यक्रम है?","optionsHi":["तमिलनाडु","केरल","आंध्र प्रदेश","गुजरात"],"explanationHi":"केरल का कुदुम्बश्री पड़ोस समूहों, क्षेत्र विकास समितियों और सामुदायिक विकास समितियों की त्रिस्तरीय संरचना के माध्यम से काम करता है, जो स्थानीय सरकारों से जुड़ी हैं।"},
  {"id":"eco-sectors-schemes-59","question":"The Self-Help Group–Bank Linkage Programme, which lets banks lend to informal groups of poor people, was launched in 1992 by:","options":["SIDBI","The State Bank of India","NABARD","The Ministry of Finance's Department of Revenue"],"answer":2,"explanation":"NABARD's pilot of 1992 grew into one of the world's largest microfinance programmes, with banks lending to SHGs on the basis of their savings and group guarantee rather than collateral.","difficulty":"hard","source":"IBPS PO · SBI PO · NABARD Grade A","questionHi":"स्वयं सहायता समूह–बैंक सहबद्धता कार्यक्रम, जो बैंकों को गरीबों के अनौपचारिक समूहों को ऋण देने देता है, 1992 में किसने शुरू किया?","optionsHi":["SIDBI","भारतीय स्टेट बैंक","NABARD","वित्त मंत्रालय का राजस्व विभाग"],"explanationHi":"NABARD का 1992 का प्रायोगिक कार्यक्रम विश्व के सबसे बड़े सूक्ष्म वित्त कार्यक्रमों में से एक बन गया, जिसमें बैंक SHG को उनकी बचत और समूह गारंटी के आधार पर, बिना संपार्श्विक के, ऋण देते हैं।"},
  {"id":"eco-sectors-schemes-60","question":"The National Rural Livelihoods Mission (Aajeevika), launched in 2011, reaches poor rural households mainly by:","options":["Giving them land titles under land reform laws","Building all-weather roads to their villages","Guaranteeing 100 days of wage employment a year","Organising rural women into self-help groups"],"answer":3,"explanation":"Now called DAY-NRLM under the Ministry of Rural Development, it mobilises one woman from each poor household into SHGs, then links them to bank credit and livelihoods. The 100-day wage guarantee is MGNREGA, a separate programme.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"2011 में शुरू किया गया राष्ट्रीय ग्रामीण आजीविका मिशन (आजीविका) गरीब ग्रामीण परिवारों तक मुख्यतः कैसे पहुँचता है?","optionsHi":["भूमि सुधार कानूनों के अंतर्गत उन्हें भूमि के पट्टे देकर","उनके गाँवों तक सभी मौसम की सड़कें बनाकर","प्रति वर्ष 100 दिन की मज़दूरी रोज़गार की गारंटी देकर","ग्रामीण महिलाओं को स्वयं सहायता समूहों में संगठित करके"],"explanationHi":"अब ग्रामीण विकास मंत्रालय के अंतर्गत DAY-NRLM कहलाने वाला यह मिशन हर गरीब परिवार की एक महिला को SHG में जोड़ता है, फिर उन्हें बैंक ऋण और आजीविकाओं से जोड़ता है। 100 दिन की मज़दूरी गारंटी MGNREGA है, जो एक अलग कार्यक्रम है।"},
  {"id":"eco-sectors-schemes-61","question":"Bharatmala Pariyojana is mainly a programme for:","options":["Building highways, corridors and border roads","Linking rivers through a national water grid of canals","Port-led development of ports and coastal shipping","Laying rural broadband through optical fibre"],"answer":0,"explanation":"Bharatmala focuses on national highways: economic corridors, inter-corridor and feeder routes, border and international connectivity roads. Port-led development is Sagarmala.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारतमाला परियोजना मुख्यतः किसका कार्यक्रम है?","optionsHi":["राजमार्ग, गलियारे और सीमा सड़कें बनाने का","नहरों के राष्ट्रीय जल ग्रिड से नदियों को जोड़ने का","बंदरगाहों और तटीय नौवहन के बंदरगाह-आधारित विकास का","ऑप्टिकल फाइबर से ग्रामीण ब्रॉडबैंड बिछाने का"],"explanationHi":"भारतमाला राष्ट्रीय राजमार्गों पर केंद्रित है: आर्थिक गलियारे, अंतर-गलियारा और फीडर मार्ग, सीमा और अंतरराष्ट्रीय संपर्क सड़कें। बंदरगाह-आधारित विकास सागरमाला है।"},
  {"id":"eco-sectors-schemes-62","question":"Under a Production Linked Incentive (PLI) scheme, the incentive given to a manufacturer is generally linked to its:","options":["Number of new workers it adds to its formal payroll","Extra sales of India-made goods over a base year","Value of finished goods it imports for resale","Land and buildings it owns in industrial parks"],"answer":1,"explanation":"PLI schemes pay a percentage of additional sales of domestically manufactured products above a base year, rewarding firms that scale up production in India.","difficulty":"hard","source":"UPSC Prelims · IBPS PO","questionHi":"उत्पादन से जुड़ी प्रोत्साहन (PLI) योजना के अंतर्गत विनिर्माता को दिया जाने वाला प्रोत्साहन सामान्यतः किससे जुड़ा होता है?","optionsHi":["अपने औपचारिक वेतन-पत्रक में जोड़े गए नए श्रमिकों की संख्या","आधार वर्ष से अधिक भारत में बनी वस्तुओं की अतिरिक्त बिक्री","पुनर्विक्रय के लिए आयातित तैयार वस्तुओं का मूल्य","औद्योगिक पार्कों में उसके स्वामित्व की भूमि और भवन"],"explanationHi":"PLI योजनाएँ आधार वर्ष से ऊपर घरेलू रूप से निर्मित उत्पादों की अतिरिक्त बिक्री के एक प्रतिशत का भुगतान करती हैं, जो भारत में उत्पादन बढ़ाने वाली फर्मों को पुरस्कृत करता है।"},
  {"id":"eco-sectors-schemes-63","question":"The Government e-Marketplace (GeM), launched in 2016, is an online platform for:","options":["Farmers to sell crops online across linked mandis","Retail investors to buy government bonds directly","Government departments to buy goods and services","Businesses to file GST returns and pay tax online"],"answer":2,"explanation":"GeM, under the Ministry of Commerce and Industry, lets ministries and public bodies buy from registered sellers transparently. Online crop trading is e-NAM, and direct retail purchase of bonds is the RBI Retail Direct scheme.","difficulty":"hard","source":"UPSC Prelims · IBPS PO","questionHi":"2016 में शुरू किया गया सरकारी ई-मार्केटप्लेस (GeM) किसके लिए ऑनलाइन मंच है?","optionsHi":["किसानों के लिए, जुड़ी हुई मंडियों में फसलें ऑनलाइन बेचने हेतु","खुदरा निवेशकों के लिए, सरकारी बॉन्ड सीधे खरीदने हेतु","सरकारी विभागों के लिए, वस्तुएँ और सेवाएँ खरीदने हेतु","व्यवसायों के लिए, GST रिटर्न दाखिल करने और कर चुकाने हेतु"],"explanationHi":"वाणिज्य एवं उद्योग मंत्रालय के अधीन GeM मंत्रालयों और सार्वजनिक निकायों को पंजीकृत विक्रेताओं से पारदर्शी ढंग से खरीद की सुविधा देता है। फसलों का ऑनलाइन व्यापार e-NAM है, और बॉन्ड की सीधी खुदरा खरीद RBI रिटेल डायरेक्ट योजना है।"},
  {"id":"eco-sectors-schemes-64","question":"For trade operations, duties and tariffs, a Special Economic Zone in India is treated as:","options":["A Union Territory","A tax haven exempt from all laws","A part of the nearest state's industrial area with no special status","A territory deemed to be outside the customs territory of India"],"answer":3,"explanation":"SEZs are deemed foreign territory for customs purposes, so goods brought in from the rest of India count as exports. All other Indian laws still apply inside them.","difficulty":"hard","source":"UPSC Prelims · IBPS PO","questionHi":"व्यापार संचालन, शुल्कों और टैरिफ के लिए भारत में विशेष आर्थिक क्षेत्र (SEZ) को किस रूप में माना जाता है?","optionsHi":["केंद्र शासित प्रदेश","कर स्वर्ग, जो सभी कानूनों से मुक्त है","निकटतम राज्य के औद्योगिक क्षेत्र का भाग, बिना किसी विशेष दर्जे के","भारत के सीमा शुल्क क्षेत्र से बाहर माना गया क्षेत्र"],"explanationHi":"SEZ को सीमा शुल्क के प्रयोजन से विदेशी क्षेत्र माना जाता है, इसलिए शेष भारत से लाया गया माल निर्यात गिना जाता है। भारत के अन्य सभी कानून फिर भी इनके भीतर लागू रहते हैं।"},
  {"id":"eco-sectors-schemes-65","question":"Under the Hybrid Annuity Model (HAM) for highway projects:","options":["Government pays about 40% of cost during construction, the rest as annuities","The developer bears the full cost and recovers it by collecting all the toll","The government funds the whole cost and the contractor only designs and builds","Foreign investors own the highway permanently after paying an upfront fee"],"answer":0,"explanation":"HAM blends EPC and BOT: the authority pays 40% during construction, the developer arranges 60%, and is repaid with interest through annuities; the authority collects the toll. Full toll recovery is BOT (Toll), and full government funding is EPC.","difficulty":"hard","source":"UPSC Prelims · IBPS PO","questionHi":"राजमार्ग परियोजनाओं के लिए हाइब्रिड एन्युइटी मॉडल (HAM) के अंतर्गत:","optionsHi":["सरकार निर्माण के दौरान लागत का लगभग 40% देती है, शेष वार्षिकियों के रूप में","डेवलपर पूरी लागत वहन करता है और पूरा टोल वसूलकर उसे वापस पाता है","सरकार पूरी लागत वहन करती है और ठेकेदार केवल डिज़ाइन और निर्माण करता है","विदेशी निवेशक अग्रिम शुल्क चुकाकर राजमार्ग के स्थायी स्वामी बन जाते हैं"],"explanationHi":"HAM, EPC और BOT का मिश्रण है: प्राधिकरण निर्माण के दौरान 40% देता है, डेवलपर 60% जुटाता है, और ब्याज सहित वार्षिकियों से उसे चुकाया जाता है; टोल प्राधिकरण वसूलता है। पूरा टोल वसूलना BOT (टोल) है, और पूरा सरकारी वित्तपोषण EPC है।"},
  {"id":"eco-sectors-schemes-66","question":"How many of these statements about highway project models are correct? I. In BOT (Toll), the private partner collects toll during the concession period. II. In EPC, the government finances the project and the contractor only designs and builds it. III. In HAM, the government pays about 40% of the cost during construction. IV. In HAM, the private developer bears the traffic (toll revenue) risk.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. In HAM the authority collects the toll and pays fixed annuities, so traffic risk stays with the government; IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"राजमार्ग परियोजना मॉडलों के बारे में इनमें से कितने कथन सही हैं? I. BOT (टोल) में निजी भागीदार रियायत अवधि में टोल वसूलता है। II. EPC में सरकार परियोजना का वित्तपोषण करती है और ठेकेदार केवल डिज़ाइन और निर्माण करता है। III. HAM में सरकार निर्माण के दौरान लागत का लगभग 40% देती है। IV. HAM में निजी डेवलपर यातायात (टोल राजस्व) का जोखिम वहन करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। HAM में प्राधिकरण टोल वसूलता है और निश्चित वार्षिकियाँ देता है, इसलिए यातायात का जोखिम सरकार के पास रहता है; IV गलत है।"},
  {"id":"eco-sectors-schemes-67","question":"Match the type of unemployment with its description. A. Disguised  B. Seasonal  C. Frictional  D. Structural; 1. Temporary joblessness while moving between jobs  2. Mismatch between workers' skills and available jobs due to changes in the economy  3. More people engaged in work than required, adding nothing to output  4. Work available only in certain months of the year","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1","A-2, B-4, C-1, D-3","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"Disguised unemployment hides inside apparent work; seasonal follows the farm calendar; frictional is the short gap of job-search; structural reflects a lasting mismatch, for example when technology makes old skills obsolete.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"बेरोज़गारी के प्रकार का उसके विवरण से मिलान कीजिए। A. प्रच्छन्न  B. मौसमी  C. घर्षणात्मक  D. संरचनात्मक; 1. नौकरियों के बीच जाते समय अस्थायी बेरोज़गारी  2. अर्थव्यवस्था में परिवर्तन के कारण श्रमिकों के कौशल और उपलब्ध रोज़गार के बीच असंगति  3. आवश्यकता से अधिक लोगों का काम में लगा होना, जो उत्पादन में कुछ नहीं जोड़ता  4. वर्ष के केवल कुछ महीनों में काम उपलब्ध होना","optionsHi":["A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1","A-2, B-4, C-1, D-3","A-3, B-4, C-1, D-2"],"explanationHi":"प्रच्छन्न बेरोज़गारी प्रत्यक्ष काम के भीतर छिपी रहती है; मौसमी कृषि कैलेंडर के अनुसार चलती है; घर्षणात्मक नौकरी की खोज का छोटा अंतराल है; संरचनात्मक स्थायी असंगति दर्शाती है, उदाहरण के लिए जब तकनीक पुराने कौशल को अप्रचलित कर देती है।"},
  {"id":"eco-sectors-schemes-68","question":"How many of these statements about the National Food Security Act, 2013 are correct? I. The eldest woman of at least 18 years is treated as the head of the household for issuing ration cards. II. Children aged six months to fourteen years are entitled to a free meal through the local anganwadi. III. Each state is to set up a State Food Commission to monitor the Act. IV. Coverage is limited to households identified as below the poverty line in a 2011 survey.","options":["Only three","Only one","Only two","All four"],"answer":2,"explanation":"I and III are correct. II is wrong: the anganwadi meal entitlement covers children from six months to six years; children of 6–14 get midday meals in school. IV is wrong: coverage is up to 75% rural and 50% urban, not tied to a BPL list.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"राष्ट्रीय खाद्य सुरक्षा अधिनियम, 2013 के बारे में इनमें से कितने कथन सही हैं? I. राशन कार्ड जारी करने के लिए कम से कम 18 वर्ष की सबसे बड़ी महिला को परिवार की मुखिया माना जाता है। II. छह माह से चौदह वर्ष की आयु के बच्चे स्थानीय आँगनवाड़ी के माध्यम से निःशुल्क भोजन के हकदार हैं। III. अधिनियम की निगरानी के लिए प्रत्येक राज्य को राज्य खाद्य आयोग बनाना है। IV. कवरेज 2011 के सर्वेक्षण में गरीबी रेखा से नीचे पहचाने गए परिवारों तक सीमित है।","optionsHi":["केवल तीन","केवल एक","केवल दो","सभी चार"],"explanationHi":"I और III सही हैं। II गलत है: आँगनवाड़ी भोजन की पात्रता छह माह से छह वर्ष के बच्चों के लिए है; 6–14 वर्ष के बच्चों को स्कूल में मध्याह्न भोजन मिलता है। IV गलत है: कवरेज ग्रामीण के 75% और शहरी के 50% तक है, किसी BPL सूची से बँधा नहीं।"},
  {"id":"eco-sectors-schemes-69","question":"Assertion (A): Paying the LPG subsidy through DBT reduced the diversion of subsidised cylinders to commercial use. Reason (R): Under DBT, cylinders are sold at market price and the subsidy is credited to the consumer's bank account.","options":["A is true but R is false","Both A and R are true and R is the correct explanation of A","A is false but R is true","Both A and R are true but R is not the correct explanation of A"],"answer":1,"explanation":"Once every cylinder carries the same market price, there is no cheap cylinder to divert to hotels or businesses; the subsidy reaches only the verified household's account.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): DBT के माध्यम से LPG सब्सिडी देने से सब्सिडी वाले सिलेंडरों का वाणिज्यिक उपयोग में विचलन घटा। कारण (R): DBT के अंतर्गत सिलेंडर बाज़ार मूल्य पर बेचे जाते हैं और सब्सिडी उपभोक्ता के बैंक खाते में जमा की जाती है।","optionsHi":["A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A असत्य है परंतु R सत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है"],"explanationHi":"जब हर सिलेंडर पर एक ही बाज़ार मूल्य लगता है, तो होटलों या व्यवसायों की ओर मोड़ने के लिए कोई सस्ता सिलेंडर नहीं रहता; सब्सिडी केवल सत्यापित परिवार के खाते में पहुँचती है।"},
  {"id":"eco-sectors-schemes-70","question":"Arrange these programmes in the order they were launched: 1. MGNREGA  2. Pradhan Mantri Gram Sadak Yojana  3. National Rural Livelihoods Mission  4. Pradhan Mantri Jan Dhan Yojana","options":["1-2-3-4","2-3-1-4","2-1-3-4","2-1-4-3"],"answer":2,"explanation":"PMGSY began in 2000, MGNREGA came into force in 2006 (Act of 2005), NRLM was launched in 2011 and Jan Dhan in 2014.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इन कार्यक्रमों को उनके शुरू होने के क्रम में व्यवस्थित कीजिए: 1. MGNREGA  2. प्रधानमंत्री ग्राम सड़क योजना  3. राष्ट्रीय ग्रामीण आजीविका मिशन  4. प्रधानमंत्री जन धन योजना","optionsHi":["1-2-3-4","2-3-1-4","2-1-3-4","2-1-4-3"],"explanationHi":"PMGSY 2000 में शुरू हुई, MGNREGA 2006 में लागू हुआ (अधिनियम 2005 का), NRLM 2011 में शुरू हुआ और जन धन 2014 में।"},
  {"id":"eco-sectors-schemes-71","question":"Which of these workers is most likely to be part of the unorganised sector?","options":["A clerk in a nationalised bank","A teacher in a government school","A street vendor selling vegetables","An engineer in a public sector steel plant"],"answer":2,"explanation":"Street vendors work in small, unregistered units with no fixed wages, paid leave or social security. The others hold regular, rule-bound organised-sector jobs.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"इनमें से कौन-सा श्रमिक असंगठित क्षेत्र का भाग होने की सबसे अधिक संभावना रखता है?","optionsHi":["राष्ट्रीयकृत बैंक का क्लर्क","सरकारी स्कूल का शिक्षक","सब्ज़ी बेचने वाला रेहड़ी-पटरी विक्रेता","सार्वजनिक क्षेत्र के इस्पात संयंत्र का इंजीनियर"],"explanationHi":"रेहड़ी-पटरी वाले छोटी, अपंजीकृत इकाइयों में काम करते हैं जहाँ निश्चित मज़दूरी, सवेतन अवकाश या सामाजिक सुरक्षा नहीं होती। अन्य के पास नियमित, नियम-बद्ध संगठित क्षेत्र की नौकरियाँ हैं।"},
  {"id":"eco-sectors-schemes-72","question":"MGNREGA is implemented at the central level by the Ministry of:","options":["Labour and Employment","Rural Development","Agriculture and Farmers Welfare","Panchayati Raj"],"answer":1,"explanation":"The Ministry of Rural Development administers MGNREGA, with Gram Panchayats executing a large share of the works.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"केंद्र स्तर पर MGNREGA का क्रियान्वयन किस मंत्रालय द्वारा होता है?","optionsHi":["श्रम और रोज़गार मंत्रालय","ग्रामीण विकास मंत्रालय","कृषि एवं किसान कल्याण मंत्रालय","पंचायती राज मंत्रालय"],"explanationHi":"ग्रामीण विकास मंत्रालय MGNREGA का प्रशासन करता है, और ग्राम पंचायतें कार्यों का एक बड़ा हिस्सा निष्पादित करती हैं।"},
  {"id":"eco-sectors-schemes-73","question":"The “Make in India” initiative, launched in 2014, mainly aims to:","options":["Promote India as a global manufacturing hub","Encourage imports of cheaper consumer goods","Raise farm subsidies and support prices","Build all-weather village roads"],"answer":0,"explanation":"Make in India seeks to attract investment, foster innovation and build manufacturing infrastructure so that more goods are made in India.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"2014 में शुरू की गई “मेक इन इंडिया” पहल का मुख्य उद्देश्य क्या है?","optionsHi":["भारत को वैश्विक विनिर्माण केंद्र के रूप में बढ़ावा देना","सस्ते उपभोक्ता सामान के आयात को प्रोत्साहित करना","कृषि सब्सिडी और समर्थन मूल्य बढ़ाना","गाँवों के लिए सभी मौसम की सड़कें बनाना"],"explanationHi":"मेक इन इंडिया निवेश आकर्षित करने, नवाचार को बढ़ावा देने और विनिर्माण अवसंरचना बनाने का प्रयास करता है, ताकि अधिक वस्तुएँ भारत में बनें।"},
  {"id":"eco-sectors-schemes-74","question":"The Beti Bachao Beti Padhao campaign was launched in January 2015 at:","options":["Varanasi, Uttar Pradesh","Jaipur, Rajasthan","Rohtak, Haryana","Panipat, Haryana"],"answer":3,"explanation":"It was launched at Panipat in Haryana, a state with a very low child sex ratio, to address falling sex ratio and promote girls' education.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"बेटी बचाओ बेटी पढ़ाओ अभियान जनवरी 2015 में कहाँ शुरू किया गया था?","optionsHi":["वाराणसी, उत्तर प्रदेश","जयपुर, राजस्थान","रोहतक, हरियाणा","पानीपत, हरियाणा"],"explanationHi":"यह हरियाणा के पानीपत में शुरू हुआ, जो बहुत कम बाल लिंगानुपात वाला राज्य है, ताकि गिरते लिंगानुपात का समाधान हो और बालिकाओं की शिक्षा को बढ़ावा मिले।"},
  {"id":"eco-sectors-schemes-75","question":"PM-POSHAN, the renamed mid-day meal scheme, provides:","options":["Cash to pregnant women and new mothers for better nutrition","Hot cooked meals to children in government and aided schools","Free grain every month to all ration card holding families","Take-home nutrition kits only to pregnant women"],"answer":1,"explanation":"PM-POSHAN continues the mid-day meal: a cooked meal on school days for children in elementary classes of government and aided schools, improving nutrition and attendance. Cash support to mothers is PM Matru Vandana Yojana.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"PM-POSHAN, यानी नाम बदली हुई मध्याह्न भोजन योजना, क्या उपलब्ध कराती है?","optionsHi":["गर्भवती महिलाओं और नई माताओं को बेहतर पोषण के लिए नकद राशि","सरकारी और सहायता प्राप्त स्कूलों में बच्चों को गरम पका हुआ भोजन","राशन कार्ड धारक सभी परिवारों को हर माह निःशुल्क अनाज","केवल गर्भवती महिलाओं को घर ले जाने वाली पोषण किट"],"explanationHi":"PM-POSHAN मध्याह्न भोजन को जारी रखती है: सरकारी और सहायता प्राप्त स्कूलों की प्रारंभिक कक्षाओं के बच्चों को स्कूल के दिनों में पका हुआ भोजन, जिससे पोषण और उपस्थिति सुधरती है। माताओं को नकद सहायता PM मातृ वंदना योजना है।"},
  {"id":"eco-sectors-schemes-76","question":"POSHAN Abhiyaan (the National Nutrition Mission) was launched on 8 March 2018 at:","options":["Jhunjhunu, Rajasthan","Gandhinagar, Gujarat","Patna, Bihar","Bhubaneswar, Odisha"],"answer":0,"explanation":"The mission was launched on International Women's Day 2018 at Jhunjhunu to reduce stunting, under-nutrition, anaemia and low birth weight.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"पोषण अभियान (राष्ट्रीय पोषण मिशन) 8 मार्च 2018 को कहाँ शुरू किया गया था?","optionsHi":["झुंझुनूं, राजस्थान","गांधीनगर, गुजरात","पटना, बिहार","भुवनेश्वर, ओडिशा"],"explanationHi":"मिशन अंतरराष्ट्रीय महिला दिवस 2018 पर झुंझुनूं में शुरू हुआ, जिसका लक्ष्य बौनापन, कुपोषण, एनीमिया और कम जन्म भार को घटाना है।"},
  {"id":"eco-sectors-schemes-77","question":"The Pradhan Mantri Kaushal Vikas Yojana (PMKVY) mainly provides:","options":["Crop insurance to farmers against natural calamities","Monthly pensions to unorganised workers after the age of 60","Short-term, certified skill training for young people","Low-interest housing loans to first-time buyers"],"answer":2,"explanation":"PMKVY, run by the Ministry of Skill Development and Entrepreneurship, offers industry-relevant short-term training and recognition of prior learning.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"प्रधानमंत्री कौशल विकास योजना (PMKVY) मुख्यतः क्या प्रदान करती है?","optionsHi":["किसानों को प्राकृतिक आपदाओं के विरुद्ध फसल बीमा","असंगठित श्रमिकों को 60 वर्ष की आयु के बाद मासिक पेंशन","युवाओं के लिए अल्पकालिक, प्रमाणित कौशल प्रशिक्षण","पहली बार घर खरीदने वालों को कम ब्याज वाले आवास ऋण"],"explanationHi":"कौशल विकास और उद्यमिता मंत्रालय द्वारा संचालित PMKVY उद्योग-प्रासंगिक अल्पकालिक प्रशिक्षण और पूर्व अधिगम की मान्यता प्रदान करती है।"},
  {"id":"eco-sectors-schemes-78","question":"Mission Indradhanush, launched in December 2014, aims to:","options":["Electrify every village and every rural household","Build separate toilets for girls in every school","Clean the river Ganga and its main tributaries","Full immunisation of children and pregnant women"],"answer":3,"explanation":"Named after the seven colours of the rainbow (originally seven vaccine-preventable diseases), it targets children and pregnant women left out of routine immunisation.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"दिसंबर 2014 में शुरू किए गए मिशन इंद्रधनुष का उद्देश्य क्या है?","optionsHi":["हर गाँव और हर ग्रामीण परिवार का विद्युतीकरण","हर स्कूल में लड़कियों के लिए अलग शौचालय बनाना","गंगा नदी और उसकी मुख्य सहायक नदियों की सफाई","बच्चों और गर्भवती महिलाओं का पूर्ण टीकाकरण"],"explanationHi":"इंद्रधनुष के सात रंगों के नाम पर (मूल रूप से सात टीका-निवारणीय रोग), यह नियमित टीकाकरण से छूटे बच्चों और गर्भवती महिलाओं को लक्षित करता है।"},
  {"id":"eco-sectors-schemes-79","question":"The AMRUT mission, launched in 2015, focuses mainly on:","options":["Water supply, sewerage and basic urban infrastructure","All-weather road connectivity for rural habitations","Organic farming clusters and certification in the hills","Coastal shipping and port-led industrial growth"],"answer":0,"explanation":"The Atal Mission for Rejuvenation and Urban Transformation targets urban water supply, sewerage, drainage, green spaces and non-motorised transport.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"2015 में शुरू किया गया अमृत (AMRUT) मिशन मुख्यतः किस पर केंद्रित है?","optionsHi":["जल आपूर्ति, सीवरेज और बुनियादी शहरी अवसंरचना","ग्रामीण बस्तियों के लिए सभी मौसम की सड़क संपर्कता","पहाड़ों में जैविक खेती समूह और प्रमाणन","तटीय नौवहन और बंदरगाह-आधारित औद्योगिक वृद्धि"],"explanationHi":"अटल कायाकल्प और शहरी परिवर्तन मिशन शहरी जल आपूर्ति, सीवरेज, जल निकासी, हरित स्थान और गैर-मोटर चालित परिवहन को लक्षित करता है।"},
  {"id":"eco-sectors-schemes-80","question":"Disinvestment, in the Indian context, means:","options":["Foreign investors withdrawing their investment from India","The RBI cutting its policy rate to reduce investment","The government closing down loss-making private firms","The government selling some or all of its stake in PSUs"],"answer":2,"explanation":"Disinvestment raises resources and can improve efficiency by bringing in private shareholders. It is different from nationalisation, which moves ownership to the state.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"भारतीय संदर्भ में विनिवेश का क्या अर्थ है?","optionsHi":["विदेशी निवेशकों द्वारा भारत से अपना निवेश निकालना","RBI द्वारा निवेश घटाने के लिए अपनी नीतिगत दर घटाना","सरकार द्वारा घाटे में चल रही निजी फर्मों को बंद करना","सरकार द्वारा PSU में अपनी हिस्सेदारी का कुछ या पूरा भाग बेचना"],"explanationHi":"विनिवेश संसाधन जुटाता है और निजी शेयरधारकों को लाकर दक्षता सुधार सकता है। यह राष्ट्रीयकरण से भिन्न है, जिसमें स्वामित्व राज्य के पास चला जाता है।"},
  {"id":"eco-sectors-schemes-81","question":"Strategic disinvestment differs from an ordinary minority stake sale because it:","options":["Is open only to foreign buyers with sector expertise","Hands management control of the enterprise to the buyer","Raises the government's stake by buying out minority holders","Can be carried out only through sales on the stock exchange"],"answer":1,"explanation":"In a strategic sale the government sells a substantial block, usually 50% or more, together with management control. A minority sale keeps control with the government.","difficulty":"hard","source":"IBPS PO · SBI PO · UPSC Prelims","questionHi":"रणनीतिक विनिवेश एक सामान्य अल्पांश हिस्सेदारी की बिक्री से किस प्रकार भिन्न है?","optionsHi":["यह केवल क्षेत्र विशेषज्ञता वाले विदेशी क्रेताओं के लिए खुला है","यह उद्यम का प्रबंधन नियंत्रण क्रेता को सौंप देता है","यह अल्पांश धारकों को खरीदकर सरकार की हिस्सेदारी बढ़ाता है","इसे केवल स्टॉक एक्सचेंज पर बिक्री के माध्यम से किया जा सकता है"],"explanationHi":"रणनीतिक बिक्री में सरकार प्रबंधन नियंत्रण के साथ एक बड़ा हिस्सा, प्रायः 50% या अधिक, बेचती है। अल्पांश बिक्री में नियंत्रण सरकार के पास रहता है।"},
  {"id":"eco-sectors-schemes-82","question":"The National Agriculture Market (e-NAM) aims to:","options":["Fix minimum support prices for all notified crops","Replace all APMC mandis with private markets run by traders","Let farmers export produce directly without a licence","Link existing APMC mandis on one online trading platform"],"answer":3,"explanation":"e-NAM networks regulated mandis so that buyers anywhere can bid online, aiming at better price discovery for farmers. MSP is set separately on CACP's recommendation.","difficulty":"hard","source":"UPSC Prelims · IBPS PO","questionHi":"राष्ट्रीय कृषि बाज़ार (e-NAM) का उद्देश्य क्या है?","optionsHi":["सभी अधिसूचित फसलों के न्यूनतम समर्थन मूल्य तय करना","सभी APMC मंडियों की जगह व्यापारियों द्वारा चलाए जाने वाले निजी बाज़ार लाना","किसानों को बिना लाइसेंस सीधे उपज निर्यात करने देना","मौजूदा APMC मंडियों को एक ऑनलाइन व्यापार मंच पर जोड़ना"],"explanationHi":"e-NAM विनियमित मंडियों को जोड़ता है ताकि कहीं के भी क्रेता ऑनलाइन बोली लगा सकें, जिससे किसानों को बेहतर मूल्य खोज मिले। MSP अलग से CACP की सिफारिश पर तय होता है।"},
  {"id":"eco-sectors-schemes-83","question":"In the “Anand pattern” of dairy cooperatives spread through Operation Flood, the three tiers are:","options":["Village milk society, district milk union, state federation","Farmer, private milk trader, and a processing company","Village cooperative, district bank, State Cooperative Bank","Gram panchayat, block samiti, zila parishad"],"answer":0,"explanation":"Milk is collected by village societies, processed by district unions and marketed by a state federation, as with Amul in Gujarat. The village–district–state bank chain is the short-term cooperative credit structure, not dairying.","difficulty":"hard","source":"UPSC Prelims · NABARD Grade A","questionHi":"ऑपरेशन फ्लड द्वारा फैलाए गए डेयरी सहकारी समितियों के “आनंद पैटर्न” में तीन स्तर कौन-से हैं?","optionsHi":["ग्राम दुग्ध समिति, ज़िला दुग्ध संघ, राज्य महासंघ","किसान, निजी दूध व्यापारी और एक प्रसंस्करण कंपनी","ग्राम सहकारी समिति, ज़िला बैंक, राज्य सहकारी बैंक","ग्राम पंचायत, खंड समिति, ज़िला परिषद"],"explanationHi":"दूध ग्राम समितियाँ एकत्र करती हैं, ज़िला संघ प्रसंस्कृत करते हैं और राज्य महासंघ विपणन करता है, जैसे गुजरात में अमूल। ग्राम–ज़िला–राज्य बैंक की शृंखला अल्पकालिक सहकारी ऋण संरचना है, डेयरी नहीं।"},
  {"id":"eco-sectors-schemes-84","question":"Which of the following is NOT one of the four labour codes that consolidate India's central labour laws?","options":["Code on Wages","Industrial Relations Code","Code on Social Security","Code on Child Labour"],"answer":3,"explanation":"The four codes are on Wages, Industrial Relations, Social Security, and Occupational Safety, Health and Working Conditions; together they subsume 29 central laws. There is no separate child-labour code.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कौन भारत के केंद्रीय श्रम कानूनों को समेकित करने वाली चार श्रम संहिताओं में से नहीं है?","optionsHi":["मज़दूरी संहिता","औद्योगिक संबंध संहिता","सामाजिक सुरक्षा संहिता","बाल श्रम संहिता"],"explanationHi":"चार संहिताएँ हैं: मज़दूरी, औद्योगिक संबंध, सामाजिक सुरक्षा, और व्यावसायिक सुरक्षा, स्वास्थ्य तथा कार्य दशाएँ; ये मिलकर 29 केंद्रीय कानूनों को समाहित करती हैं। कोई अलग बाल श्रम संहिता नहीं है।"},
  {"id":"eco-sectors-schemes-85","question":"How many of these statements about the Pradhan Mantri Jan Dhan Yojana are correct? I. Accounts can be opened with zero balance. II. Account holders get a RuPay debit card with accident insurance cover. III. An overdraft facility is available to eligible account holders. IV. Only rural households may open accounts under it.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Jan Dhan aims at universal banking for every unbanked adult, urban or rural, so IV is wrong.","difficulty":"very-hard","source":"IBPS PO · SBI PO · UPSC Prelims","questionHi":"प्रधानमंत्री जन धन योजना के बारे में इनमें से कितने कथन सही हैं? I. खाते शून्य शेष पर खोले जा सकते हैं। II. खाताधारकों को दुर्घटना बीमा कवर के साथ रुपे (RuPay) डेबिट कार्ड मिलता है। III. पात्र खाताधारकों को ओवरड्राफ्ट सुविधा उपलब्ध है। IV. इसके अंतर्गत केवल ग्रामीण परिवार ही खाते खोल सकते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। जन धन का लक्ष्य हर बैंक-विहीन वयस्क, शहरी या ग्रामीण, के लिए सार्वभौमिक बैंकिंग है, इसलिए IV गलत है।"},
  {"id":"eco-sectors-schemes-86","question":"How many of these statements about the Atal Pension Yojana are correct? I. Citizens aged 18 to 40 can join. II. It offers a guaranteed minimum monthly pension from age 60 in fixed slabs. III. After the subscriber's death the spouse receives the pension, and later the nominee gets the accumulated corpus. IV. Income-tax payers have been barred from joining since October 2022.","options":["Only three","Only one","Only two","All four"],"answer":3,"explanation":"All four are correct: citizens aged 18 to 40 can join; it guarantees a minimum monthly pension from 60 in fixed slabs; the spouse then gets the pension and the nominee the corpus; and from 1 October 2022 income-tax payers cannot join.","difficulty":"very-hard","source":"IBPS PO · SBI PO · UPSC Prelims","questionHi":"अटल पेंशन योजना के बारे में इनमें से कितने कथन सही हैं? I. 18 से 40 वर्ष की आयु के नागरिक जुड़ सकते हैं। II. यह 60 वर्ष की आयु से निश्चित स्लैब में गारंटीशुदा न्यूनतम मासिक पेंशन देती है। III. अभिदाता की मृत्यु के बाद पति/पत्नी को पेंशन मिलती है, और बाद में नामांकित को संचित कोष मिलता है। IV. अक्टूबर 2022 से आयकर दाताओं के जुड़ने पर रोक है।","optionsHi":["केवल तीन","केवल एक","केवल दो","सभी चार"],"explanationHi":"चारों सही हैं: 18 से 40 वर्ष के नागरिक जुड़ सकते हैं; यह 60 वर्ष से निश्चित स्लैब में न्यूनतम मासिक पेंशन की गारंटी देती है; फिर पति/पत्नी को पेंशन और नामांकित को कोष मिलता है; और 1 अक्टूबर 2022 से आयकर दाता नहीं जुड़ सकते।"},
  {"id":"eco-sectors-schemes-87","question":"Match the infrastructure model with its description. A. BOT (Toll)  B. EPC  C. HAM  D. TOT; 1. Government funds the project fully; the contractor only designs and builds  2. Government pays about 40% during construction and the rest as annuities  3. Private firm builds, collects toll for the concession period, then hands the asset back  4. Existing public highways are leased for an upfront lump sum, letting the private party collect toll","options":["A-3, B-2, C-1, D-4","A-3, B-1, C-2, D-4","A-4, B-1, C-2, D-3","A-3, B-1, C-4, D-2"],"answer":1,"explanation":"BOT shifts financing and traffic risk to the private firm; EPC keeps both with the government; HAM splits funding 40:60; Toll-Operate-Transfer monetises highways already built.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अवसंरचना मॉडल का उसके विवरण से मिलान कीजिए। A. BOT (टोल)  B. EPC  C. HAM  D. TOT; 1. सरकार परियोजना को पूरी तरह वित्त देती है; ठेकेदार केवल डिज़ाइन और निर्माण करता है  2. सरकार निर्माण के दौरान लगभग 40% और शेष वार्षिकियों के रूप में देती है  3. निजी फर्म निर्माण करती है, रियायत अवधि में टोल वसूलती है, फिर परिसंपत्ति लौटा देती है  4. मौजूदा सार्वजनिक राजमार्ग एकमुश्त अग्रिम राशि पर पट्टे पर दिए जाते हैं, जिससे निजी पक्ष टोल वसूलता है","optionsHi":["A-3, B-2, C-1, D-4","A-3, B-1, C-2, D-4","A-4, B-1, C-2, D-3","A-3, B-1, C-4, D-2"],"explanationHi":"BOT वित्तपोषण और यातायात जोखिम निजी फर्म पर डालता है; EPC दोनों सरकार के पास रखता है; HAM वित्तपोषण 40:60 में बाँटता है; टोल-ऑपरेट-ट्रांसफर पहले से बने राजमार्गों का मुद्रीकरण करता है।"},
  {"id":"eco-sectors-schemes-88","question":"Assertion (A): Disguised unemployment is difficult to detect in official statistics. Reason (R): Those affected appear to be working, although removing them would not reduce total output.","options":["Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"Because such workers are counted as employed on family farms or businesses, surveys record them as working; their zero marginal product is what makes the unemployment ‘disguised’.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): प्रच्छन्न बेरोज़गारी का आधिकारिक आँकड़ों में पता लगाना कठिन है। कारण (R): प्रभावित लोग काम करते दिखते हैं, जबकि उन्हें हटाने से कुल उत्पादन नहीं घटेगा।","optionsHi":["A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है"],"explanationHi":"क्योंकि ऐसे श्रमिक पारिवारिक खेतों या व्यवसायों में नियोजित गिने जाते हैं, सर्वेक्षण उन्हें काम करता हुआ दर्ज करते हैं; उनका शून्य सीमांत उत्पाद ही इस बेरोज़गारी को ‘प्रच्छन्न’ बनाता है।"},
  {"id":"eco-sectors-schemes-89","question":"How many of these statements about classifying economic activity are correct? I. The primary/secondary/tertiary split is based on the nature of the activity. II. The organised/unorganised split is based on ownership. III. The public/private split is based on conditions of employment. IV. Construction is part of the tertiary sector.","options":["Only one","Only two","All four","Only three"],"answer":0,"explanation":"Only I is correct. The organised/unorganised split rests on conditions of employment and the public/private split on ownership, so II and III swap them. IV is wrong: construction is part of the secondary sector.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"आर्थिक गतिविधि के वर्गीकरण के बारे में इनमें से कितने कथन सही हैं? I. प्राथमिक/द्वितीयक/तृतीयक विभाजन गतिविधि के स्वरूप पर आधारित है। II. संगठित/असंगठित विभाजन स्वामित्व पर आधारित है। III. सार्वजनिक/निजी विभाजन रोज़गार की शर्तों पर आधारित है। IV. निर्माण तृतीयक क्षेत्र का भाग है।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"केवल I सही है। संगठित/असंगठित विभाजन रोज़गार की शर्तों पर और सार्वजनिक/निजी विभाजन स्वामित्व पर टिका है, इसलिए II और III इन्हें आपस में बदल देते हैं। IV गलत है: निर्माण द्वितीयक क्षेत्र का भाग है।"},
  {"id":"eco-sectors-schemes-90","question":"Arrange these food-security measures in the order they were introduced: 1. Antyodaya Anna Yojana  2. Targeted Public Distribution System  3. National Food Security Act  4. One Nation One Ration Card","options":["2-1-3-4","1-2-3-4","2-3-1-4","1-3-2-4"],"answer":0,"explanation":"TPDS replaced the universal PDS in 1997, AAY followed in December 2000 for the poorest, the NFSA came in 2013, and ration-card portability began in 2019 before covering all states.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इन खाद्य सुरक्षा उपायों को उनके लागू होने के क्रम में व्यवस्थित कीजिए: 1. अंत्योदय अन्न योजना  2. लक्षित सार्वजनिक वितरण प्रणाली  3. राष्ट्रीय खाद्य सुरक्षा अधिनियम  4. एक राष्ट्र एक राशन कार्ड","optionsHi":["2-1-3-4","1-2-3-4","2-3-1-4","1-3-2-4"],"explanationHi":"TPDS ने 1997 में सार्वभौमिक PDS का स्थान लिया, AAY दिसंबर 2000 में सबसे गरीबों के लिए आई, NFSA 2013 में आया, और राशन कार्ड की पोर्टेबिलिटी 2019 में शुरू होकर सभी राज्यों तक पहुँची।"},
  {"id":"eco-sectors-schemes-91","question":"Match the programme with its main objective. A. PMGSY  B. UDAN  C. Sagarmala  D. Smart Cities Mission; 1. Port-led development and coastal shipping  2. All-weather roads to unconnected rural habitations  3. Area-based urban development using technology-driven solutions  4. Affordable regional air connectivity","options":["A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1"],"answer":0,"explanation":"PMGSY (2000) builds rural roads; UDAN (Ude Desh ka Aam Nagrik) subsidises regional flights; Sagarmala modernises ports and coastal logistics; the Smart Cities Mission (2015) funds area-based urban projects.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"कार्यक्रम का उसके मुख्य उद्देश्य से मिलान कीजिए। A. PMGSY  B. UDAN  C. सागरमाला  D. स्मार्ट सिटी मिशन; 1. बंदरगाह-आधारित विकास और तटीय नौवहन  2. असंबद्ध ग्रामीण बस्तियों तक सभी मौसम की सड़कें  3. प्रौद्योगिकी-संचालित समाधानों से क्षेत्र-आधारित शहरी विकास  4. किफायती क्षेत्रीय हवाई संपर्कता","optionsHi":["A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1"],"explanationHi":"PMGSY (2000) ग्रामीण सड़कें बनाती है; UDAN (उड़े देश का आम नागरिक) क्षेत्रीय उड़ानों पर सब्सिडी देती है; सागरमाला बंदरगाहों और तटीय लॉजिस्टिक्स का आधुनिकीकरण करती है; स्मार्ट सिटी मिशन (2015) क्षेत्र-आधारित शहरी परियोजनाओं को निधि देता है।"},
  {"id":"eco-sectors-schemes-92","question":"How many of these statements are correct? I. SEZ units can import inputs duty-free. II. Export Oriented Units (EOUs) can be set up anywhere in India, not only inside zones. III. Kandla set up Asia's first Export Processing Zone in 1965. IV. The SEZ Act was passed in 2005.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The EPZs of the 1960s–80s were converted into SEZs from 2000, and the SEZ Act, 2005 gave the scheme a statutory basis.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. SEZ इकाइयाँ इनपुट शुल्क-मुक्त आयात कर सकती हैं। II. निर्यात उन्मुख इकाइयाँ (EOU) भारत में कहीं भी स्थापित की जा सकती हैं, केवल क्षेत्रों के भीतर नहीं। III. कांडला ने 1965 में एशिया का पहला निर्यात प्रसंस्करण क्षेत्र स्थापित किया। IV. SEZ अधिनियम 2005 में पारित हुआ।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। 1960 से 1980 के दशकों के EPZ 2000 से SEZ में बदले गए, और SEZ अधिनियम, 2005 ने योजना को सांविधिक आधार दिया।"},
  {"id":"eco-sectors-schemes-93","question":"How many of these statements about foodgrain management are correct? I. The Food Corporation of India procures wheat and rice at the minimum support price. II. Grain for PDS is released to states at the central issue price, below its economic cost. III. Buffer stock norms are laid down for different quarters of the year. IV. Under decentralised procurement, some states procure and distribute grain themselves.","options":["Only two","Only one","All four","Only three"],"answer":2,"explanation":"All four are correct. The gap between the economic cost and the issue price is the food subsidy, and stocking norms are fixed for 1 April, 1 July, 1 October and 1 January.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"खाद्यान्न प्रबंधन के बारे में इनमें से कितने कथन सही हैं? I. भारतीय खाद्य निगम न्यूनतम समर्थन मूल्य पर गेहूँ और चावल की खरीद करता है। II. PDS के अनाज को राज्यों को केंद्रीय निर्गम मूल्य पर, उसकी आर्थिक लागत से कम पर, जारी किया जाता है। III. वर्ष की विभिन्न तिमाहियों के लिए बफर स्टॉक मानदंड तय किए गए हैं। IV. विकेंद्रीकृत खरीद के अंतर्गत कुछ राज्य स्वयं अनाज की खरीद और वितरण करते हैं।","optionsHi":["केवल दो","केवल एक","सभी चार","केवल तीन"],"explanationHi":"चारों सही हैं। आर्थिक लागत और निर्गम मूल्य का अंतर खाद्य सब्सिडी है, और भंडारण मानदंड 1 अप्रैल, 1 जुलाई, 1 अक्टूबर और 1 जनवरी के लिए तय हैं।"},
  {"id":"eco-sectors-schemes-94","question":"Assertion (A): The expansion of IT and business services has contributed to the growth of India's tertiary sector. Reason (R): The tertiary sector is defined as the sector producing tangible goods.","options":["Both A and R are true and R is the correct explanation of A","A is true but R is false","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"A is true: software and business services are services. R is false: the tertiary sector produces intangible services, while tangible goods come from the primary and secondary sectors.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): IT और व्यावसायिक सेवाओं के विस्तार ने भारत के तृतीयक क्षेत्र की वृद्धि में योगदान दिया है। कारण (R): तृतीयक क्षेत्र को मूर्त वस्तुएँ उत्पादित करने वाले क्षेत्र के रूप में परिभाषित किया जाता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A असत्य है परंतु R सत्य है"],"explanationHi":"A सत्य है: सॉफ्टवेयर और व्यावसायिक सेवाएँ सेवाएँ ही हैं। R असत्य है: तृतीयक क्षेत्र अमूर्त सेवाएँ उत्पादित करता है, जबकि मूर्त वस्तुएँ प्राथमिक और द्वितीयक क्षेत्रों से आती हैं।"},
  {"id":"eco-sectors-schemes-95","question":"How many of these statements about self-help groups (SHGs) are correct? I. An SHG usually has about 10 to 20 members. II. Members save regularly and lend from the pooled savings to one another. III. Banks may lend to SHGs without demanding collateral. IV. An SHG must be registered as a company to receive bank loans.","options":["Only one","Only three","Only two","All four"],"answer":1,"explanation":"I, II and III are correct. SHGs are informal groups; banks lend on the strength of their savings record and peer pressure, and no company registration is needed, so IV is wrong.","difficulty":"very-hard","source":"IBPS PO · NABARD Grade A · State PSC","questionHi":"स्वयं सहायता समूहों (SHG) के बारे में इनमें से कितने कथन सही हैं? I. एक SHG में सामान्यतः लगभग 10 से 20 सदस्य होते हैं। II. सदस्य नियमित बचत करते हैं और जमा बचत से आपस में ऋण देते हैं। III. बैंक संपार्श्विक माँगे बिना SHG को ऋण दे सकते हैं। IV. बैंक ऋण पाने के लिए SHG का कंपनी के रूप में पंजीकृत होना आवश्यक है।","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"I, II और III सही हैं। SHG अनौपचारिक समूह हैं; बैंक उनकी बचत के रिकॉर्ड और साथियों के दबाव के आधार पर ऋण देते हैं, और कंपनी पंजीकरण की आवश्यकता नहीं, इसलिए IV गलत है।"},
  {"id":"eco-sectors-schemes-96","question":"Match the committee or commission with its subject. A. Shanta Kumar Committee  B. M.S. Swaminathan (National Commission on Farmers)  C. C. Rangarajan Expert Group  D. Ashok Dalwai Committee; 1. Measurement of poverty  2. Restructuring of the Food Corporation of India  3. Doubling farmers' income  4. Farmers' distress, including MSP at cost plus 50%","options":["A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3"],"answer":2,"explanation":"Shanta Kumar's panel (report 2015) reviewed the FCI; Swaminathan's commission (2004–06) recommended MSP at least 50% above the weighted cost; Rangarajan (2014) re-estimated poverty; Dalwai's committee drafted the strategy for doubling farmers' income.","difficulty":"very-hard","source":"UPSC Prelims · NABARD Grade A","questionHi":"समिति या आयोग का उसके विषय से मिलान कीजिए। A. शांता कुमार समिति  B. एम.एस. स्वामीनाथन (राष्ट्रीय किसान आयोग)  C. सी. रंगराजन विशेषज्ञ समूह  D. अशोक दलवई समिति; 1. गरीबी का मापन  2. भारतीय खाद्य निगम का पुनर्गठन  3. किसानों की आय दोगुनी करना  4. किसानों की व्यथा, जिसमें लागत जमा 50% पर MSP शामिल है","optionsHi":["A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3"],"explanationHi":"शांता कुमार के पैनल (रिपोर्ट 2015) ने FCI की समीक्षा की; स्वामीनाथन आयोग (2004–06) ने भारित लागत से कम से कम 50% ऊपर MSP की सिफारिश की; रंगराजन (2014) ने गरीबी का पुनः आकलन किया; दलवई समिति ने किसानों की आय दोगुनी करने की रणनीति का प्रारूप बनाया।"},
  {"id":"eco-sectors-schemes-97","question":"How many of these statements about cooperatives in India are correct? I. A separate Union Ministry of Cooperation was created in 2021. II. The 97th Constitutional Amendment added the right to form cooperative societies to Article 19(1)(c). III. Cooperative societies are a subject in the State List. IV. In 2021 the Supreme Court upheld Part IXB of the Constitution in full, including for state cooperative societies.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The Supreme Court struck down the provisions of Part IXB relating to state cooperatives for want of ratification by the states, keeping it only for multi-state societies, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत में सहकारी समितियों के बारे में इनमें से कितने कथन सही हैं? I. 2021 में एक अलग केंद्रीय सहकारिता मंत्रालय बनाया गया। II. 97वें संविधान संशोधन ने सहकारी समितियाँ बनाने का अधिकार अनुच्छेद 19(1)(c) में जोड़ा। III. सहकारी समितियाँ राज्य सूची का विषय हैं। IV. 2021 में उच्चतम न्यायालय ने संविधान के भाग IXB को राज्य सहकारी समितियों सहित पूर्ण रूप से बरकरार रखा।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। उच्चतम न्यायालय ने राज्यों द्वारा अनुसमर्थन न होने के कारण भाग IXB के राज्य सहकारी समितियों से संबंधित प्रावधानों को रद्द कर दिया, उसे केवल बहु-राज्य समितियों के लिए रखा, इसलिए IV गलत है।"},
  {"id":"eco-sectors-schemes-98","question":"How many of these statements about the Pradhan Mantri Gram Sadak Yojana are correct? I. It was launched in 2000. II. It aims to connect eligible unconnected rural habitations with all-weather roads. III. In hill and special areas, smaller habitations qualify than in the plains. IV. It mainly funds roads inside large cities.","options":["Only three","Only one","Only two","All four"],"answer":0,"explanation":"I, II and III are correct; the habitation-size threshold was 500 in the plains and 250 in hill, desert and tribal areas. PMGSY is a rural scheme, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"प्रधानमंत्री ग्राम सड़क योजना के बारे में इनमें से कितने कथन सही हैं? I. इसे 2000 में शुरू किया गया। II. इसका लक्ष्य पात्र असंबद्ध ग्रामीण बस्तियों को सभी मौसम की सड़कों से जोड़ना है। III. पहाड़ी और विशेष क्षेत्रों में मैदानों की तुलना में छोटी बस्तियाँ पात्र होती हैं। IV. यह मुख्यतः बड़े शहरों के भीतर की सड़कों को वित्त देती है।","optionsHi":["केवल तीन","केवल एक","केवल दो","सभी चार"],"explanationHi":"I, II और III सही हैं; बस्ती के आकार की सीमा मैदानों में 500 और पहाड़ी, रेगिस्तानी तथा जनजातीय क्षेत्रों में 250 थी। PMGSY ग्रामीण योजना है, इसलिए IV गलत है।"},
  {"id":"eco-sectors-schemes-99","question":"Assertion (A): MGNREGA is described as largely self-targeting. Reason (R): It offers unskilled manual work at the statutory wage, so mainly those who need the work ask for it.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because the work is physically demanding and pays only the notified wage, better-off households rarely apply, so the scheme screens itself without a beneficiary list.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): MGNREGA को बड़े पैमाने पर स्व-लक्षित योजना बताया जाता है। कारण (R): यह वैधानिक मज़दूरी पर अकुशल शारीरिक काम देती है, इसलिए मुख्यतः वही लोग काम मांगते हैं जिन्हें उसकी ज़रूरत होती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"क्योंकि काम शारीरिक रूप से कठिन है और केवल अधिसूचित मज़दूरी देता है, संपन्न परिवार शायद ही आवेदन करते हैं, इसलिए योजना बिना लाभार्थी सूची के स्वयं छँटाई कर लेती है।"},
  {"id":"eco-sectors-schemes-100","question":"Match the scheme with its main target group. A. PM-POSHAN  B. POSHAN Abhiyaan  C. Antyodaya Anna Yojana  D. Atal Pension Yojana; 1. The poorest of the poor households  2. Workers in the unorganised sector  3. Schoolchildren  4. Children under six, pregnant women and lactating mothers","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"PM-POSHAN feeds schoolchildren; POSHAN Abhiyaan targets early childhood and maternal nutrition; AAY gives the poorest households 35 kg of grain; APY offers pensions to unorganised workers.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"योजना का उसके मुख्य लक्ष्य समूह से मिलान कीजिए। A. PM-POSHAN  B. पोषण अभियान  C. अंत्योदय अन्न योजना  D. अटल पेंशन योजना; 1. सबसे गरीब परिवार  2. असंगठित क्षेत्र के श्रमिक  3. स्कूली बच्चे  4. छह वर्ष से कम के बच्चे, गर्भवती महिलाएँ और स्तनपान कराने वाली माताएँ","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"explanationHi":"PM-POSHAN स्कूली बच्चों को भोजन देती है; पोषण अभियान बाल्यावस्था और मातृ पोषण को लक्षित करता है; AAY सबसे गरीब परिवारों को 35 kg अनाज देती है; APY असंगठित श्रमिकों को पेंशन देती है।"},
  {"id":"eco-sectors-schemes-101","question":"According to the Clark–Fisher model of economic development, as an economy develops:","options":["the share of the primary sector in output and employment keeps rising","output and employment shift from primary to secondary to tertiary","the tertiary sector expands first and manufacturing takes over only last","all three sectors keep roughly constant shares of output and employment"],"answer":1,"explanation":"Rising incomes and productivity release labour from farming, first into industry and then into services. India is often cited as an exception, with services growing fast while agriculture still employs a large share of workers.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"आर्थिक विकास के क्लार्क–फिशर मॉडल के अनुसार, अर्थव्यवस्था के विकसित होने पर:","optionsHi":["उत्पादन और रोज़गार में प्राथमिक क्षेत्र का हिस्सा बढ़ता ही रहता है","उत्पादन और रोज़गार प्राथमिक से द्वितीयक और फिर तृतीयक क्षेत्र की ओर खिसकते हैं","तृतीयक क्षेत्र पहले फैलता है और विनिर्माण सबसे अंत में आता है","तीनों क्षेत्रों का उत्पादन और रोज़गार में हिस्सा लगभग स्थिर रहता है"],"explanationHi":"बढ़ती आय और उत्पादकता खेती से श्रम को पहले उद्योग में और फिर सेवाओं में मुक्त करती है। भारत को अक्सर अपवाद के रूप में उद्धृत किया जाता है, जहाँ सेवाएँ तेज़ी से बढ़ीं जबकि कृषि अब भी श्रमिकों के बड़े हिस्से को रोज़गार देती है।"},
  {"id":"eco-sectors-schemes-102","question":"'Quinary' activities, sometimes called gold-collar work, are associated with:","options":["extraction of raw materials such as minerals and timber from nature","processing of raw materials into finished goods in large factories","top-level decisions by senior executives, officials and policy makers","research, data processing and information services"],"answer":2,"explanation":"Quinary activities are a subset of services at the very top, where policy and strategy are decided. Research, data and information work is quaternary, the closest trap; extraction is primary and manufacturing secondary.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"‘पंचक’ (क्विनरी) गतिविधियाँ, जिन्हें कभी-कभी गोल्ड-कॉलर कार्य कहा जाता है, किससे संबद्ध हैं?","optionsHi":["प्रकृति से खनिज और लकड़ी जैसे कच्चे माल का निष्कर्षण","बड़े कारखानों में कच्चे माल को तैयार माल में संसाधित करना","वरिष्ठ अधिकारियों, पदाधिकारियों और नीति निर्माताओं के शीर्ष-स्तरीय निर्णय","अनुसंधान, डेटा प्रसंस्करण और सूचना सेवाएँ"],"explanationHi":"पंचक गतिविधियाँ सेवाओं का सबसे शीर्ष उपसमूह हैं, जहाँ नीति और रणनीति तय होती है। अनुसंधान, डेटा और सूचना कार्य चतुर्थक है, जो सबसे निकट का जाल है; निष्कर्षण प्राथमिक और विनिर्माण द्वितीयक है।"},
  {"id":"eco-sectors-schemes-103","question":"In a survey, out of 1,000 persons of working age, 570 are employed, 30 are without work but seeking or available for work, and 400 are neither working nor seeking work. The unemployment rate is:","options":["5%","3%","7.5%","5.3%"],"answer":0,"explanation":"Labour force = 570 + 30 = 600, so the unemployment rate = 30/600 = 5%. Dividing by all 1,000 persons gives 3%, which confuses the unemployment rate with a population ratio; the participation rate here is 60% and the worker–population ratio 57%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"एक सर्वेक्षण में कार्य-आयु के 1,000 व्यक्तियों में से 570 नियोजित हैं, 30 काम के बिना हैं पर काम की तलाश में या उपलब्ध हैं, और 400 न काम कर रहे हैं और न तलाश रहे हैं। बेरोज़गारी दर है:","optionsHi":["5%","3%","7.5%","5.3%"],"explanationHi":"श्रम बल = 570 + 30 = 600, इसलिए बेरोज़गारी दर = 30/600 = 5%। सभी 1,000 व्यक्तियों से भाग देने पर 3% आता है, जो बेरोज़गारी दर को जनसंख्या अनुपात से उलझाता है; यहाँ भागीदारी दर 60% और श्रमिक–जनसंख्या अनुपात 57% है।"},
  {"id":"eco-sectors-schemes-104","question":"In the Periodic Labour Force Survey, how does the 'usual status' approach differ from the 'current weekly status' (CWS) approach?","options":["Usual status looks at the preceding 7 days, CWS at the preceding 365 days","Both look at the preceding 30 days but classify activity differently","Usual status is used only for urban areas and CWS only for rural areas","Usual status looks at the preceding 365 days, CWS at the preceding 7 days"],"answer":3,"explanation":"Usual status captures a person's long-term activity, while CWS reflects the last week and so picks up short-term and seasonal unemployment; CWS unemployment rates are therefore generally higher.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"आवधिक श्रम बल सर्वेक्षण में ‘सामान्य स्थिति’ दृष्टिकोण ‘वर्तमान साप्ताहिक स्थिति’ (CWS) दृष्टिकोण से किस प्रकार भिन्न है?","optionsHi":["सामान्य स्थिति पिछले 7 दिनों को देखती है, CWS पिछले 365 दिनों को","दोनों पिछले 30 दिनों को देखते हैं पर गतिविधि को अलग ढंग से वर्गीकृत करते हैं","सामान्य स्थिति केवल शहरी क्षेत्रों के लिए और CWS केवल ग्रामीण क्षेत्रों के लिए प्रयुक्त होती है","सामान्य स्थिति पिछले 365 दिनों को देखती है, CWS पिछले 7 दिनों को"],"explanationHi":"सामान्य स्थिति व्यक्ति की दीर्घकालिक गतिविधि को पकड़ती है, जबकि CWS पिछले सप्ताह को दर्शाती है और इसलिए अल्पकालिक तथा मौसमी बेरोज़गारी को पकड़ती है; इसलिए CWS की बेरोज़गारी दरें सामान्यतः अधिक होती हैं।"},
  {"id":"eco-sectors-schemes-105","question":"Under the Open Market Sale Scheme (Domestic), the Food Corporation of India:","options":["buys wheat and rice from farmers in open markets at the minimum support price","sells central-pool wheat and rice in the open market to moderate prices","exports surplus central-pool foodgrains to neighbouring countries at set prices","distributes free grain to priority households through fair price shops"],"answer":1,"explanation":"OMSS offloads surplus stocks, mainly to bulk buyers such as flour mills, when market prices are high; purchase at MSP is procurement, and free grain under the NFSA reaches households through the PDS.","difficulty":"hard","source":"UPSC Prelims","questionHi":"खुला बाज़ार बिक्री योजना (घरेलू) के अंतर्गत भारतीय खाद्य निगम:","optionsHi":["किसानों से खुले बाज़ारों में न्यूनतम समर्थन मूल्य पर गेहूँ और चावल खरीदता है","कीमतों को नियंत्रित करने के लिए केंद्रीय पूल का गेहूँ और चावल खुले बाज़ार में बेचता है","केंद्रीय पूल के अधिशेष खाद्यान्न को निर्धारित कीमतों पर पड़ोसी देशों को निर्यात करता है","उचित मूल्य की दुकानों के माध्यम से प्राथमिकता वाले परिवारों को निःशुल्क अनाज बाँटता है"],"explanationHi":"OMSS बाज़ार कीमतें ऊँची होने पर अधिशेष भंडार, मुख्यतः आटा मिलों जैसे थोक क्रेताओं को, बेचती है; MSP पर खरीद प्रापण है, और NFSA के अंतर्गत निःशुल्क अनाज PDS के माध्यम से परिवारों तक पहुँचता है।"},
  {"id":"eco-sectors-schemes-106","question":"The Price Stabilisation Fund operated by the Centre is meant to:","options":["build buffer stocks of volatile items like pulses and onion","pay the minimum support price for the wheat and paddy procured by FCI","compensate exporters for losses caused by swings in the rupee's value","subsidise the retail price of urea and other fertilisers for farmers"],"answer":0,"explanation":"The fund finances procurement and storage of perishable or volatile items so that releases can damp price spikes for consumers while protecting farmers from distress sales.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"केंद्र द्वारा संचालित मूल्य स्थिरीकरण कोष का उद्देश्य क्या है?","optionsHi":["दालों और प्याज जैसी अस्थिर वस्तुओं के बफर स्टॉक बनाना","FCI द्वारा खरीदे गए गेहूँ और धान के लिए न्यूनतम समर्थन मूल्य चुकाना","रुपये के मूल्य के उतार-चढ़ाव से हुए घाटे की भरपाई निर्यातकों को करना","किसानों के लिए यूरिया और अन्य उर्वरकों के खुदरा मूल्य पर सब्सिडी देना"],"explanationHi":"यह कोष नाशवान या अस्थिर वस्तुओं की खरीद और भंडारण को वित्त देता है, ताकि निर्गम से उपभोक्ताओं के लिए कीमतों के उछाल को थामा जा सके और किसानों को संकटकालीन बिक्री से बचाया जा सके।"},
  {"id":"eco-sectors-schemes-107","question":"Under the Decentralised Procurement (DCP) system for foodgrains:","options":["only the Food Corporation of India procures and stores grain in every single state","private traders procure grain on behalf of the Centre for a commission","States procure, store and distribute grain, with the Centre meeting costs","the system applies only to pulses and oilseeds bought under price support"],"answer":2,"explanation":"DCP, begun in 1997–98, lets states buy grain locally at MSP and use it directly, cutting transport costs and widening procurement to more states; any surplus is handed to the FCI for the central pool.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"खाद्यान्न की विकेंद्रीकृत खरीद (DCP) प्रणाली के अंतर्गत:","optionsHi":["केवल भारतीय खाद्य निगम हर राज्य में अनाज की खरीद और भंडारण करता है","निजी व्यापारी कमीशन पर केंद्र की ओर से अनाज खरीदते हैं","राज्य अनाज की खरीद, भंडारण और वितरण करते हैं, और लागत केंद्र वहन करता है","यह प्रणाली केवल मूल्य समर्थन के अंतर्गत खरीदी जाने वाली दालों और तिलहनों पर लागू होती है"],"explanationHi":"1997–98 में शुरू हुई DCP राज्यों को स्थानीय रूप से MSP पर अनाज खरीदकर सीधे उपयोग करने देती है, जिससे परिवहन लागत घटती है और खरीद अधिक राज्यों तक फैलती है; कोई भी अधिशेष केंद्रीय पूल के लिए FCI को सौंप दिया जाता है।"},
  {"id":"eco-sectors-schemes-108","question":"The Industrial Policy Resolution of 1956 classified industries into:","options":["Schedules A, B and C: State-only, mixed with growing State role, and the rest private","two lists only: a public sector list and a private sector list, with no overlap","a short list of industries needing licences, with licensing abolished for all others","industries to be fully privatised in phases within ten years"],"answer":0,"explanation":"The 1956 Resolution (Schedules A, B and C) gave the public sector the 'commanding heights'. Abolition of licensing for most industries came with the 1991 New Industrial Policy, the trap here.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"1956 के औद्योगिक नीति संकल्प ने उद्योगों को किस प्रकार वर्गीकृत किया?","optionsHi":["अनुसूची A, B और C: केवल राज्य, राज्य की बढ़ती भूमिका के साथ मिश्रित, और शेष निजी","केवल दो सूचियाँ: एक सार्वजनिक क्षेत्र की और एक निजी क्षेत्र की, बिना अतिव्यापन के","लाइसेंस की ज़रूरत वाले उद्योगों की एक छोटी सूची, जिसमें अन्य सभी के लिए लाइसेंसिंग समाप्त","ऐसे उद्योग जिनका दस वर्षों में चरणबद्ध ढंग से पूर्ण निजीकरण किया जाना है"],"explanationHi":"1956 के संकल्प (अनुसूची A, B और C) ने सार्वजनिक क्षेत्र को ‘कमांडिंग हाइट्स’ दीं। अधिकांश उद्योगों के लिए लाइसेंसिंग की समाप्ति 1991 की नई औद्योगिक नीति से आई, जो यहाँ का जाल है।"},
  {"id":"eco-sectors-schemes-109","question":"Viability Gap Funding (VGF) for infrastructure projects under public–private partnership is:","options":["a soft loan to State governments to cover gaps in their budgets","a capital grant making a socially justified but unprofitable PPP project bankable","a ten-year tax holiday for all private firms building infrastructure","a penalty that private partners must pay the government for delays in completing projects"],"answer":1,"explanation":"Projects such as roads in remote areas may yield high social returns but low revenue; VGF bridges the gap, usually awarded to the bidder seeking the least grant.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सार्वजनिक–निजी भागीदारी के अंतर्गत अवसंरचना परियोजनाओं के लिए व्यवहार्यता अंतर वित्तपोषण (VGF) क्या है?","optionsHi":["राज्य सरकारों को उनके बजट के अंतर पाटने के लिए रियायती ऋण","पूंजीगत अनुदान, जो सामाजिक रूप से उचित पर अलाभकारी PPP परियोजना को बैंक-योग्य बनाता है","अवसंरचना बनाने वाली सभी निजी फर्मों के लिए दस वर्ष का कर अवकाश","परियोजनाएँ पूरी करने में देरी के लिए निजी भागीदारों को सरकार को चुकाना पड़ने वाला दंड"],"explanationHi":"दूरस्थ क्षेत्रों की सड़कों जैसी परियोजनाओं का सामाजिक प्रतिफल ऊँचा पर राजस्व कम हो सकता है; VGF इस अंतर को पाटता है, और प्रायः उस बोलीदाता को दिया जाता है जो सबसे कम अनुदान माँगे।"},
  {"id":"eco-sectors-schemes-110","question":"The PM Gati Shakti National Master Plan, launched in 2021, is mainly:","options":["a new access-controlled expressway linking Delhi and Mumbai through Gujarat and Rajasthan","a freight subsidy for exporters using rail and coastal shipping","a GIS-based platform for joint infrastructure planning across ministries","a high-speed rail project linking the four metro cities"],"answer":2,"explanation":"Gati Shakti layers data on existing and planned assets so that projects across ministries can be planned together, cutting delays and logistics costs; it is a planning tool, not a single project.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"2021 में शुरू किया गया PM गति शक्ति राष्ट्रीय मास्टर प्लान मुख्यतः क्या है?","optionsHi":["गुजरात और राजस्थान से होकर दिल्ली और मुंबई को जोड़ने वाला नया नियंत्रित-प्रवेश एक्सप्रेसवे","रेल और तटीय नौवहन का उपयोग करने वाले निर्यातकों के लिए माल-भाड़ा सब्सिडी","मंत्रालयों में संयुक्त अवसंरचना नियोजन के लिए GIS-आधारित मंच","चारों महानगरों को जोड़ने वाली हाई-स्पीड रेल परियोजना"],"explanationHi":"गति शक्ति मौजूदा और नियोजित परिसंपत्तियों का डेटा परत-दर-परत जोड़ती है ताकि मंत्रालयों की परियोजनाओं की योजना साथ-साथ बन सके, जिससे देरी और लॉजिस्टिक्स लागत घटती है; यह नियोजन का उपकरण है, एक परियोजना नहीं।"},
  {"id":"eco-sectors-schemes-111","question":"Farmer Producer Organisations (FPOs) are best described as:","options":["government agencies that procure grain from farmers at the minimum support price, as FCI does","private agribusiness firms that undertake contract farming with growers","rural branches of NABARD that lend directly to small and marginal farmers","farmer collectives, registered as companies or cooperatives, that pool trade"],"answer":3,"explanation":"By aggregating small and marginal farmers, FPOs gain economies of scale in buying inputs, accessing credit and selling produce; NABARD and SFAC only promote and support them.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"किसान उत्पादक संगठन (FPO) का सबसे उपयुक्त वर्णन क्या है?","optionsHi":["सरकारी एजेंसियाँ जो FCI की तरह न्यूनतम समर्थन मूल्य पर किसानों से अनाज खरीदती हैं","निजी कृषि-व्यवसाय फर्में जो उत्पादकों के साथ अनुबंध खेती करती हैं","NABARD की ग्रामीण शाखाएँ जो लघु और सीमांत किसानों को सीधे ऋण देती हैं","किसान सामूहिक संगठन, जो कंपनियों या सहकारी समितियों के रूप में पंजीकृत होकर व्यापार को एकत्र करते हैं"],"explanationHi":"लघु और सीमांत किसानों को एकत्र करके FPO आगतों की खरीद, ऋण तक पहुँच और उपज की बिक्री में पैमाने की मितव्ययिता पाते हैं; NABARD और SFAC उन्हें केवल बढ़ावा और सहायता देते हैं।"},
  {"id":"eco-sectors-schemes-112","question":"Consider the following statements: I. Payments banks can accept deposits but cannot lend. II. Small finance banks can accept deposits and lend, with a focus on unserved and underserved sections. III. Payments banks can issue credit cards to their customers. Which of the statements given above is/are correct?","options":["I only","I and II only","II and III only","I, II and III"],"answer":1,"explanation":"Payments banks can offer deposits, remittances and debit cards, but since they cannot lend they cannot issue credit cards, so III is wrong. Both types were created after the Nachiket Mor Committee's report to deepen financial inclusion.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: I. भुगतान बैंक जमा स्वीकार कर सकते हैं पर ऋण नहीं दे सकते। II. लघु वित्त बैंक जमा स्वीकार कर सकते हैं और ऋण दे सकते हैं, जिनका ध्यान असेवित और अल्प-सेवित वर्गों पर रहता है। III. भुगतान बैंक अपने ग्राहकों को क्रेडिट कार्ड जारी कर सकते हैं। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल I","केवल I और II","केवल II और III","I, II और III"],"explanationHi":"भुगतान बैंक जमा, प्रेषण और डेबिट कार्ड दे सकते हैं, पर चूँकि वे ऋण नहीं दे सकते, इसलिए क्रेडिट कार्ड जारी नहीं कर सकते; III गलत है। दोनों प्रकार वित्तीय समावेशन गहरा करने के लिए नचिकेत मोर समिति की रिपोर्ट के बाद बनाए गए।"},
  {"id":"eco-sectors-schemes-113","question":"The share capital of a Regional Rural Bank is held by the Central Government, the sponsor bank and the State Government in the ratio:","options":["50 : 35 : 15","50 : 15 : 35","35 : 50 : 15","40 : 40 : 20"],"answer":0,"explanation":"The Centre holds half, the sponsor bank 35% and the State 15%. RRBs, set up from 1975, combine local feel with commercial banking discipline to serve small farmers, labourers and artisans.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"क्षेत्रीय ग्रामीण बैंक की शेयर पूंजी केंद्र सरकार, प्रायोजक बैंक और राज्य सरकार के पास किस अनुपात में होती है?","optionsHi":["50 : 35 : 15","50 : 15 : 35","35 : 50 : 15","40 : 40 : 20"],"explanationHi":"केंद्र के पास आधा, प्रायोजक बैंक के पास 35% और राज्य के पास 15% होता है। 1975 से स्थापित RRB स्थानीय समझ को वाणिज्यिक बैंकिंग अनुशासन से जोड़कर लघु किसानों, मज़दूरों और कारीगरों की सेवा करते हैं।"},
  {"id":"eco-sectors-schemes-114","question":"Match the institution with its main role. A. NABARD  B. SIDBI  C. National Housing Bank  D. EXIM Bank; 1. Refinance and promotion of housing finance  2. Financing of foreign trade  3. Apex institution for agriculture and rural development credit  4. Principal institution for financing and promoting MSMEs","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"NABARD (1982) refinances rural credit, SIDBI (1990) serves small industry, the NHB (1988) supports housing finance and the EXIM Bank (1982) finances exports and imports.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"संस्था का उसकी मुख्य भूमिका से मिलान कीजिए। A. NABARD  B. SIDBI  C. राष्ट्रीय आवास बैंक  D. EXIM बैंक; 1. आवास वित्त का पुनर्वित्त और संवर्धन  2. विदेश व्यापार का वित्तपोषण  3. कृषि और ग्रामीण विकास ऋण की शीर्ष संस्था  4. MSME के वित्तपोषण और संवर्धन की प्रमुख संस्था","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"explanationHi":"NABARD (1982) ग्रामीण ऋण का पुनर्वित्त करता है, SIDBI (1990) लघु उद्योग की सेवा करता है, NHB (1988) आवास वित्त को सहारा देता है और EXIM बैंक (1982) निर्यात और आयात का वित्तपोषण करता है।"},
  {"id":"eco-sectors-schemes-115","question":"Which labour code, for the first time in Indian law, defines 'gig workers' and 'platform workers' and provides for social security schemes for them?","options":["Code on Wages, 2019","Industrial Relations Code, 2020","Code on Social Security, 2020","Occupational Safety, Health and Working Conditions Code, 2020"],"answer":2,"explanation":"The Code on Social Security brings gig and platform workers, who fall outside the traditional employer–employee relationship, under schemes that may be funded partly by contributions from aggregators.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारतीय कानून में पहली बार कौन-सी श्रम संहिता ‘गिग श्रमिकों’ और ‘प्लेटफ़ॉर्म श्रमिकों’ को परिभाषित करती है और उनके लिए सामाजिक सुरक्षा योजनाओं का प्रावधान करती है?","optionsHi":["मज़दूरी संहिता, 2019","औद्योगिक संबंध संहिता, 2020","सामाजिक सुरक्षा संहिता, 2020","व्यावसायिक सुरक्षा, स्वास्थ्य और कार्य दशा संहिता, 2020"],"explanationHi":"सामाजिक सुरक्षा संहिता गिग और प्लेटफ़ॉर्म श्रमिकों को, जो पारंपरिक नियोक्ता–कर्मचारी संबंध से बाहर हैं, उन योजनाओं के अंतर्गत लाती है जिन्हें आंशिक रूप से एग्रीगेटरों के अंशदान से वित्तपोषित किया जा सकता है।"},
  {"id":"eco-sectors-schemes-116","question":"NITI Aayog's National Multidimensional Poverty Index is built on which three equally weighted dimensions?","options":["Income, consumption and assets","Health, education and standard of living","Employment, income and housing","Nutrition, sanitation and access to electricity"],"answer":1,"explanation":"Following the global MPI, it uses health, education and standard of living (with indicators such as nutrition, schooling, sanitation and cooking fuel). Nutrition, sanitation and electricity are indicators within these dimensions, not dimensions themselves.","difficulty":"hard","source":"UPSC Prelims","questionHi":"नीति आयोग का राष्ट्रीय बहुआयामी गरीबी सूचकांक किन तीन समान भारांक वाले आयामों पर बना है?","optionsHi":["आय, उपभोग और परिसंपत्तियाँ","स्वास्थ्य, शिक्षा और जीवन स्तर","रोज़गार, आय और आवास","पोषण, स्वच्छता और बिजली तक पहुँच"],"explanationHi":"वैश्विक MPI का अनुसरण करते हुए यह स्वास्थ्य, शिक्षा और जीवन स्तर (पोषण, स्कूली शिक्षा, स्वच्छता और खाना पकाने के ईंधन जैसे संकेतकों के साथ) का उपयोग करता है। पोषण, स्वच्छता और बिजली इन आयामों के भीतर के संकेतक हैं, स्वयं आयाम नहीं।"},
  {"id":"eco-sectors-schemes-117","question":"Two regions have the same head-count ratio of poverty, but the poor in Region X are on average much further below the poverty line than those in Region Y. Which measure will be higher for Region X?","options":["The head-count ratio","The Human Development Index","The literacy rate","The poverty gap index"],"answer":3,"explanation":"The head-count ratio only counts how many are poor; the poverty gap index also measures how far below the line they are, so it is higher where poverty is deeper.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"दो क्षेत्रों में गरीबी का हेड-काउंट अनुपात समान है, पर क्षेत्र X के गरीब औसतन गरीबी रेखा से क्षेत्र Y के गरीबों की तुलना में बहुत नीचे हैं। क्षेत्र X के लिए कौन-सा माप अधिक होगा?","optionsHi":["हेड-काउंट अनुपात","मानव विकास सूचकांक","साक्षरता दर","गरीबी अंतराल सूचकांक"],"explanationHi":"हेड-काउंट अनुपात केवल गिनता है कि कितने लोग गरीब हैं; गरीबी अंतराल सूचकांक यह भी मापता है कि वे रेखा से कितने नीचे हैं, इसलिए जहाँ गरीबी गहरी है वहाँ यह अधिक होता है।"},
  {"id":"eco-sectors-schemes-118","question":"The Human Development Index of the UNDP combines indicators of:","options":["life expectancy, mean and expected schooling, and GNI per capita (PPP)","infant mortality, the adult literacy rate and real GDP growth per capita","life expectancy, the employment rate and consumer price inflation","nutrition, sanitation and per capita household consumption spending"],"answer":0,"explanation":"The HDI averages three dimensions: a long and healthy life, knowledge and a decent standard of living. GDP growth and inflation are not part of it.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"UNDP का मानव विकास सूचकांक किन संकेतकों को जोड़ता है?","optionsHi":["जीवन प्रत्याशा, औसत और अपेक्षित स्कूली शिक्षा, और प्रति व्यक्ति GNI (PPP)","शिशु मृत्यु दर, वयस्क साक्षरता दर और प्रति व्यक्ति वास्तविक GDP वृद्धि","जीवन प्रत्याशा, रोज़गार दर और उपभोक्ता मूल्य मुद्रास्फीति","पोषण, स्वच्छता और प्रति व्यक्ति घरेलू उपभोग व्यय"],"explanationHi":"HDI तीन आयामों का औसत लेता है: लंबा और स्वस्थ जीवन, ज्ञान और सम्मानजनक जीवन स्तर। GDP वृद्धि और मुद्रास्फीति इसका भाग नहीं हैं।"},
  {"id":"eco-sectors-schemes-119","question":"The 'Kuznets curve' hypothesis suggests that as per capita income rises:","options":["income inequality falls steadily from the start of growth","inequality first rises and then falls in an inverted U","income inequality first falls and then rises, tracing a U-shape","the share of agriculture in GDP first rises and then falls"],"answer":1,"explanation":"Kuznets argued that early industrialisation widens gaps between the modern and traditional sectors, which narrow later as labour moves and education spreads. The same inverted-U shape was later applied to pollution as the 'environmental Kuznets curve'.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"‘कुज़नेट्स वक्र’ की परिकल्पना सुझाती है कि प्रति व्यक्ति आय बढ़ने पर:","optionsHi":["वृद्धि की शुरुआत से ही आय असमानता लगातार घटती जाती है","असमानता पहले बढ़ती है और फिर उलटे U आकार में घटती है","आय असमानता पहले घटती है और फिर बढ़ती है, U आकार बनाते हुए","GDP में कृषि का हिस्सा पहले बढ़ता है और फिर घटता है"],"explanationHi":"कुज़नेट्स ने तर्क दिया कि आरंभिक औद्योगीकरण आधुनिक और पारंपरिक क्षेत्रों के बीच अंतर बढ़ाता है, जो बाद में श्रम के स्थानांतरण और शिक्षा के प्रसार से घटते हैं। यही उलटा-U आकार बाद में प्रदूषण पर ‘पर्यावरणीय कुज़नेट्स वक्र’ के रूप में लागू किया गया।"},
  {"id":"eco-sectors-schemes-120","question":"W. Arthur Lewis's dual-sector model explains development as:","options":["export-led growth based on static comparative advantage in primary goods","a 'big push' of simultaneous investment across many complementary industries at once","balanced growth of agriculture led by new high-yielding seed technology","surplus farm labour moving to a modern industry at a near-constant wage"],"answer":3,"explanation":"In Lewis's model the modern sector can expand without raising wages as long as surplus labour lasts, and reinvested profits drive growth. The 'big push' is Rosenstein-Rodan's idea.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"डब्ल्यू. आर्थर लुईस का द्वि-क्षेत्रक मॉडल विकास की व्याख्या किस रूप में करता है?","optionsHi":["प्राथमिक वस्तुओं में स्थिर तुलनात्मक लाभ पर आधारित निर्यात-नेतृत्व वाली वृद्धि","एक साथ अनेक पूरक उद्योगों में एक ही समय निवेश का ‘बिग पुश’","नई उच्च उपज वाली बीज तकनीक से प्रेरित कृषि की संतुलित वृद्धि","अधिशेष कृषि श्रम का लगभग स्थिर मज़दूरी पर आधुनिक उद्योग की ओर जाना"],"explanationHi":"लुईस के मॉडल में जब तक अधिशेष श्रम रहता है, आधुनिक क्षेत्र मज़दूरी बढ़ाए बिना फैल सकता है, और पुनर्निवेशित लाभ वृद्धि को आगे बढ़ाते हैं। ‘बिग पुश’ रोज़ेनस्टाइन-रोडन का विचार है।"},
  {"id":"eco-sectors-schemes-121","question":"In a year, gross value added (GVA) at basic prices is ₹250 lakh crore, product taxes are ₹30 lakh crore and product subsidies ₹10 lakh crore. GDP at market prices is:","options":["₹290 lakh crore","₹250 lakh crore","₹270 lakh crore","₹230 lakh crore"],"answer":2,"explanation":"GDP = GVA at basic prices + product taxes − product subsidies = 250 + 30 − 10 = 270. Adding the subsidies (290) or ignoring the taxes (230) are the common slips.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"किसी वर्ष में आधार कीमतों पर सकल मूल्य वर्धन (GVA) ₹250 लाख करोड़, उत्पाद कर ₹30 लाख करोड़ और उत्पाद सब्सिडी ₹10 लाख करोड़ है। बाज़ार कीमतों पर GDP है:","optionsHi":["₹290 लाख करोड़","₹250 लाख करोड़","₹270 लाख करोड़","₹230 लाख करोड़"],"explanationHi":"GDP = आधार कीमतों पर GVA + उत्पाद कर − उत्पाद सब्सिडी = 250 + 30 − 10 = 270। सब्सिडी जोड़ देना (290) या करों को छोड़ देना (230) आम भूलें हैं।"},
  {"id":"eco-sectors-schemes-122","question":"The Rural Infrastructure Development Fund (RIDF), operated by NABARD since 1995–96, gets its money mainly from:","options":["a cess levied on agricultural exports by the Commerce Ministry","annual budgetary grants from the Union Ministry of Agriculture","long-term loans from the World Bank and the Asian Development Bank","deposits by banks that miss their priority-sector lending targets"],"answer":3,"explanation":"Banks that miss their agriculture or priority-sector targets must deposit the shortfall in RIDF and similar funds; NABARD lends this money to States for rural roads, irrigation and other infrastructure.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"1995–96 से NABARD द्वारा संचालित ग्रामीण अवसंरचना विकास कोष (RIDF) को धन मुख्यतः कहाँ से मिलता है?","optionsHi":["वाणिज्य मंत्रालय द्वारा कृषि निर्यात पर लगाया गया उपकर","केंद्रीय कृषि मंत्रालय के वार्षिक बजटीय अनुदान","विश्व बैंक और एशियाई विकास बैंक से दीर्घकालिक ऋण","प्राथमिकता क्षेत्र ऋण लक्ष्य चूकने वाले बैंकों की जमाएँ"],"explanationHi":"कृषि या प्राथमिकता क्षेत्र के लक्ष्य चूकने वाले बैंकों को कमी की राशि RIDF और ऐसी ही निधियों में जमा करनी पड़ती है; NABARD यह धन राज्यों को ग्रामीण सड़कों, सिंचाई और अन्य अवसंरचना के लिए उधार देता है।"},
  {"id":"eco-sectors-schemes-123","question":"A 'demographic dividend' becomes available to an economy when:","options":["the total population starts to shrink as fertility falls below replacement","the death rate rises above the birth rate and population falls","the working-age share rises relative to dependent children and the elderly","the share of elderly people in the population rises sharply"],"answer":2,"explanation":"A falling dependency ratio frees resources for saving and investment and enlarges the labour force; the dividend is realised only if these workers are healthy, skilled and productively employed. An ageing population reverses it.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"किसी अर्थव्यवस्था को ‘जनसांख्यिकीय लाभांश’ तब उपलब्ध होता है जब:","optionsHi":["प्रजनन दर प्रतिस्थापन स्तर से नीचे गिरने पर कुल जनसंख्या घटने लगे","मृत्यु दर जन्म दर से अधिक हो जाए और जनसंख्या घटे","आश्रित बच्चों और बुजुर्गों की तुलना में कार्य-आयु वर्ग का हिस्सा बढ़े","जनसंख्या में बुजुर्गों का हिस्सा तेज़ी से बढ़े"],"explanationHi":"घटता आश्रितता अनुपात बचत और निवेश के लिए संसाधन मुक्त करता है और श्रम बल को बड़ा करता है; लाभांश तभी प्राप्त होता है जब ये श्रमिक स्वस्थ, कुशल और उत्पादक रूप से नियोजित हों। वृद्ध होती जनसंख्या इसे पलट देती है।"},
  {"id":"eco-sectors-schemes-124","question":"In a district, 2,000 people are aged 15 and above: 1,000 are employed, 100 are without work but seeking or available for it, and the rest are outside the labour force. Which set of indicators is correct?","options":["LFPR 55%, WPR 50%, unemployment rate 5.0%","LFPR 50%, WPR 55%, unemployment rate 9.1%","LFPR 55%, WPR 50%, unemployment rate 9.1%","LFPR 55%, WPR 45%, unemployment rate 10.0%"],"answer":2,"explanation":"LFPR = 1,100/2,000 = 55%; WPR = 1,000/2,000 = 50%; the unemployment rate is measured against the labour force, 100/1,100 ≈ 9.1%. Dividing by the whole population gives the wrong 5%.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"एक ज़िले में 15 वर्ष और उससे अधिक आयु के 2,000 लोग हैं: 1,000 नियोजित हैं, 100 काम के बिना हैं पर काम की तलाश में या उपलब्ध हैं, और शेष श्रम बल से बाहर हैं। संकेतकों का कौन-सा समूह सही है?","optionsHi":["LFPR 55%, WPR 50%, बेरोज़गारी दर 5.0%","LFPR 50%, WPR 55%, बेरोज़गारी दर 9.1%","LFPR 55%, WPR 50%, बेरोज़गारी दर 9.1%","LFPR 55%, WPR 45%, बेरोज़गारी दर 10.0%"],"explanationHi":"LFPR = 1,100/2,000 = 55%; WPR = 1,000/2,000 = 50%; बेरोज़गारी दर श्रम बल के अनुपात में मापी जाती है, 100/1,100 ≈ 9.1%। पूरी जनसंख्या से भाग देना गलत 5% देता है।"},
  {"id":"eco-sectors-schemes-125","question":"Under the usual principal and subsidiary status (UPSS) approach of the PLFS, a person whose main activity in the past year was not work is still counted as employed if he or she worked in a subsidiary capacity for at least:","options":["15 days","30 days","60 days","183 days"],"answer":1,"explanation":"Usual principal status uses the activity of the major part of the year (183 days or more); a person outside work on that basis is added to the workforce if engaged in subsidiary work for 30 days or more.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"PLFS के सामान्य प्रधान और सहायक स्थिति (UPSS) दृष्टिकोण के अंतर्गत, जिस व्यक्ति की पिछले वर्ष की मुख्य गतिविधि काम नहीं थी, उसे भी नियोजित गिना जाता है यदि उसने सहायक रूप में कम से कम कितने दिन काम किया हो?","optionsHi":["15 दिन","30 दिन","60 दिन","183 दिन"],"explanationHi":"सामान्य प्रधान स्थिति वर्ष के प्रमुख भाग (183 दिन या अधिक) की गतिविधि का उपयोग करती है; उस आधार पर काम से बाहर रहने वाले व्यक्ति को कार्यबल में जोड़ा जाता है यदि वह 30 दिन या अधिक सहायक कार्य में लगा हो।"},
  {"id":"eco-sectors-schemes-126","question":"Which approach to measuring unemployment usually gives the highest unemployment rate, because it records joblessness on individual days within a week?","options":["Usual principal status","Usual principal and subsidiary status","Current weekly status","Current daily status"],"answer":3,"explanation":"Current daily status counts person-days, so a worker who finds work on only some days of the week is partly unemployed. Usual status takes a whole-year view and gives the lowest rate.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"बेरोज़गारी मापने का कौन-सा दृष्टिकोण सामान्यतः सबसे ऊँची बेरोज़गारी दर देता है, क्योंकि वह एक सप्ताह के भीतर अलग-अलग दिनों की बेकारी दर्ज करता है?","optionsHi":["सामान्य प्रधान स्थिति","सामान्य प्रधान और सहायक स्थिति","वर्तमान साप्ताहिक स्थिति","वर्तमान दैनिक स्थिति"],"explanationHi":"वर्तमान दैनिक स्थिति व्यक्ति-दिवस गिनती है, इसलिए जिस श्रमिक को सप्ताह के केवल कुछ दिन काम मिलता है वह आंशिक रूप से बेरोज़गार है। सामान्य स्थिति पूरे वर्ष का दृष्टिकोण लेती है और सबसे कम दर देती है।"},
  {"id":"eco-sectors-schemes-127","question":"As first designed in 2017, the Periodic Labour Force Survey of the NSO gave quarterly estimates of labour-force indicators in current weekly status for:","options":["Rural areas only","Both rural and urban areas","Urban areas only","Only the organised sector"],"answer":2,"explanation":"The PLFS replaced the five-yearly employment–unemployment rounds; it gave quarterly CWS estimates for urban areas and annual estimates, in both usual and weekly status, for rural and urban areas together.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"2017 में पहली बार डिज़ाइन किए गए NSO के आवधिक श्रम बल सर्वेक्षण ने वर्तमान साप्ताहिक स्थिति में श्रम बल संकेतकों के तिमाही अनुमान किसके लिए दिए?","optionsHi":["केवल ग्रामीण क्षेत्रों के लिए","ग्रामीण और शहरी दोनों क्षेत्रों के लिए","केवल शहरी क्षेत्रों के लिए","केवल संगठित क्षेत्र के लिए"],"explanationHi":"PLFS ने पंचवर्षीय रोज़गार–बेरोज़गारी दौरों का स्थान लिया; इसने शहरी क्षेत्रों के लिए तिमाही CWS अनुमान दिए, और ग्रामीण तथा शहरी क्षेत्रों के लिए मिलाकर वार्षिक अनुमान, सामान्य और साप्ताहिक दोनों स्थितियों में।"},
  {"id":"eco-sectors-schemes-128","question":"A software tester loses her job because testing is now done by automated tools, and she lacks the skills that the new jobs need. This is best described as:","options":["Frictional unemployment","Cyclical (demand-deficient) unemployment","Disguised unemployment","Technological unemployment"],"answer":3,"explanation":"Unemployment caused by labour-saving technology, which leaves workers’ skills mismatched with new jobs, is technological (a form of structural) unemployment. Frictional unemployment is the short gap while changing jobs.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"एक सॉफ्टवेयर टेस्टर की नौकरी इसलिए चली जाती है कि अब परीक्षण स्वचालित उपकरणों से होता है, और उसके पास नई नौकरियों के लिए आवश्यक कौशल नहीं हैं। इसका सबसे उपयुक्त वर्णन क्या है?","optionsHi":["घर्षणात्मक बेरोज़गारी","चक्रीय (मांग-अभाव) बेरोज़गारी","प्रच्छन्न बेरोज़गारी","तकनीकी बेरोज़गारी"],"explanationHi":"श्रम-बचत तकनीक से उत्पन्न बेरोज़गारी, जिसमें श्रमिकों के कौशल नई नौकरियों से मेल नहीं खाते, तकनीकी (संरचनात्मक का एक रूप) बेरोज़गारी है। घर्षणात्मक बेरोज़गारी नौकरी बदलते समय का छोटा अंतराल है।"},
  {"id":"eco-sectors-schemes-129","question":"After successive dereservations following the 1991 industrial policy, which areas remain reserved exclusively for the public sector?","options":["Atomic energy and railway operations","Defence production and railway operations","Atomic energy and coal mining","Railway operations and civil aviation"],"answer":0,"explanation":"The 1991 policy cut the reserved list from 17 industries to 8, and later changes left only atomic energy (with specified minerals) and railway operations. Coal and defence were opened to private players.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"1991 की औद्योगिक नीति के बाद क्रमिक आरक्षण-समाप्ति के पश्चात, कौन-से क्षेत्र अब भी केवल सार्वजनिक क्षेत्र के लिए आरक्षित हैं?","optionsHi":["परमाणु ऊर्जा और रेल परिचालन","रक्षा उत्पादन और रेल परिचालन","परमाणु ऊर्जा और कोयला खनन","रेल परिचालन और नागरिक उड्डयन"],"explanationHi":"1991 की नीति ने आरक्षित सूची को 17 उद्योगों से घटाकर 8 किया, और बाद के बदलावों ने केवल परमाणु ऊर्जा (निर्दिष्ट खनिजों सहित) और रेल परिचालन को छोड़ा। कोयला और रक्षा निजी खिलाड़ियों के लिए खोल दिए गए।"},
  {"id":"eco-sectors-schemes-130","question":"Which of these industries still needs a compulsory industrial licence in India?","options":["Manufacture of passenger cars and utility vehicles","Manufacture of Portland cement and clinker","Manufacture of finished and alloy steel","Manufacture of cigars and cigarettes of tobacco"],"answer":3,"explanation":"Compulsory licensing now covers only a few industries for health, safety or strategic reasons: alcoholic drinks, tobacco cigars and cigarettes, electronic aerospace and defence equipment, industrial explosives and hazardous chemicals.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"भारत में इनमें से किस उद्योग के लिए अब भी अनिवार्य औद्योगिक लाइसेंस चाहिए?","optionsHi":["यात्री कारों और उपयोगिता वाहनों का विनिर्माण","पोर्टलैंड सीमेंट और क्लिंकर का विनिर्माण","तैयार और मिश्र धातु इस्पात का विनिर्माण","तंबाकू के सिगार और सिगरेट का विनिर्माण"],"explanationHi":"अनिवार्य लाइसेंसिंग अब स्वास्थ्य, सुरक्षा या रणनीतिक कारणों से केवल कुछ उद्योगों पर लागू है: मादक पेय, तंबाकू के सिगार और सिगरेट, इलेक्ट्रॉनिक एयरोस्पेस और रक्षा उपकरण, औद्योगिक विस्फोटक और खतरनाक रसायन।"},
  {"id":"eco-sectors-schemes-131","question":"The Monopolies and Restrictive Trade Practices (MRTP) Act, 1969 was replaced by the:","options":["Competition Act, 2002","Consumer Protection Act, 1986","Industries (Development and Regulation) Act, 1951","Foreign Exchange Management Act, 1999"],"answer":0,"explanation":"The Competition Act, 2002, administered by the Competition Commission of India, shifted the focus from curbing big business to preventing anti-competitive conduct and abuse of dominance.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"एकाधिकार और प्रतिबंधात्मक व्यापार व्यवहार (MRTP) अधिनियम, 1969 का स्थान किसने लिया?","optionsHi":["प्रतिस्पर्धा अधिनियम, 2002","उपभोक्ता संरक्षण अधिनियम, 1986","उद्योग (विकास और विनियमन) अधिनियम, 1951","विदेशी मुद्रा प्रबंधन अधिनियम, 1999"],"explanationHi":"भारतीय प्रतिस्पर्धा आयोग द्वारा प्रशासित प्रतिस्पर्धा अधिनियम, 2002 ने ध्यान बड़े व्यवसाय पर अंकुश से हटाकर प्रतिस्पर्धा-विरोधी आचरण और प्रभुत्व के दुरुपयोग को रोकने पर केंद्रित किया।"},
  {"id":"eco-sectors-schemes-132","question":"A key difference between the Foreign Exchange Management Act, 1999 and the FERA it replaced is that under FEMA, violations are:","options":["Criminal offences tried only by special economic courts","Civil wrongs, dealt with mainly by monetary penalties","Settled only by the RBI, with no right of appeal at all","Cognisable offences punishable under the Indian Penal Code"],"answer":1,"explanation":"FERA (1973) aimed at conserving scarce foreign exchange and treated violations as criminal; FEMA aims at facilitating external trade and payments, treating most contraventions as civil matters with penalties.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"विदेशी मुद्रा प्रबंधन अधिनियम, 1999 और उसके द्वारा प्रतिस्थापित FERA के बीच एक प्रमुख अंतर यह है कि FEMA के अंतर्गत उल्लंघन हैं:","optionsHi":["आपराधिक अपराध, जिनकी सुनवाई केवल विशेष आर्थिक न्यायालयों में होती है","दीवानी दोष, जिनसे मुख्यतः आर्थिक दंड द्वारा निपटा जाता है","केवल RBI द्वारा निपटाए जाने वाले, जिनमें अपील का कोई अधिकार नहीं","संज्ञेय अपराध जो भारतीय दंड संहिता के अंतर्गत दंडनीय हैं"],"explanationHi":"FERA (1973) का लक्ष्य दुर्लभ विदेशी मुद्रा का संरक्षण था और वह उल्लंघनों को आपराधिक मानता था; FEMA का लक्ष्य बाह्य व्यापार और भुगतान को सुगम बनाना है, और अधिकांश उल्लंघनों को दीवानी मामले मानकर दंड लगाता है।"},
  {"id":"eco-sectors-schemes-133","question":"To be considered for Navratna status, a central public sector enterprise must first be:","options":["A listed company with at least 25% of its shares held by the public","A Maharatna company that has slipped below the Maharatna criteria","A Miniratna Category-I, Schedule ‘A’ CPSE with good MoU ratings","Any profit-making CPSE with a positive net worth for three years"],"answer":2,"explanation":"Navratna status is open to Miniratna Category-I, Schedule ‘A’ CPSEs with ‘excellent’ or ‘very good’ MoU ratings in three of the last five years and a qualifying score on performance indicators. Maharatna is the higher tier.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"नवरत्न दर्जे पर विचार के लिए किसी केंद्रीय सार्वजनिक क्षेत्र उद्यम को पहले क्या होना चाहिए?","optionsHi":["सूचीबद्ध कंपनी जिसके कम से कम 25% शेयर जनता के पास हों","एक महारत्न कंपनी जो महारत्न मानदंडों से नीचे फिसल गई हो","श्रेणी-I, अनुसूची ‘A’ की एक मिनीरत्न CPSE, जिसकी MoU रेटिंग अच्छी हो","कोई भी लाभ कमाने वाली CPSE जिसकी तीन वर्ष से निवल मूल्य धनात्मक हो"],"explanationHi":"नवरत्न दर्जा उन श्रेणी-I, अनुसूची ‘A’ मिनीरत्न CPSE के लिए खुला है जिनकी पिछले पाँच में से तीन वर्षों में MoU रेटिंग ‘उत्कृष्ट’ या ‘बहुत अच्छी’ रही हो और जो निष्पादन संकेतकों पर योग्यता अंक पाते हों। महारत्न उच्च श्रेणी है।"},
  {"id":"eco-sectors-schemes-134","question":"The Department of Disinvestment was renamed the Department of Investment and Public Asset Management (DIPAM) in:","options":["2014","2019","2016","2021"],"answer":2,"explanation":"The 2016 renaming, with DIPAM under the Finance Ministry, reflected a wider remit covering management of the government’s equity, not just stake sales.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"विनिवेश विभाग का नाम बदलकर निवेश और सार्वजनिक परिसंपत्ति प्रबंधन विभाग (DIPAM) किस वर्ष किया गया?","optionsHi":["2014","2019","2016","2021"],"explanationHi":"2016 में नाम बदलकर वित्त मंत्रालय के अधीन DIPAM किया गया, जो सरकार की इक्विटी के प्रबंधन तक विस्तृत दायरे को दर्शाता है, केवल हिस्सेदारी की बिक्री तक नहीं।"},
  {"id":"eco-sectors-schemes-135","question":"Under the New Public Sector Enterprise Policy announced in 2021, in the designated strategic sectors the government will:","options":["Keep all existing CPSEs and set up new ones to expand public presence","Exit fully by selling every enterprise in these sectors to private buyers","Retain all CPSEs but list every one of them on the stock exchanges","Keep a bare minimum presence and privatise, merge or shut the rest"],"answer":3,"explanation":"For the four broad strategic sectors the policy keeps a minimum public presence; in non-strategic sectors CPSEs are to be privatised or closed where feasible.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"2021 में घोषित नई सार्वजनिक क्षेत्र उद्यम नीति के अंतर्गत, निर्दिष्ट रणनीतिक क्षेत्रों में सरकार क्या करेगी?","optionsHi":["सभी मौजूदा CPSE रखेगी और सार्वजनिक उपस्थिति बढ़ाने के लिए नए CPSE बनाएगी","इन क्षेत्रों के हर उद्यम को निजी क्रेताओं को बेचकर पूरी तरह बाहर निकल जाएगी","सभी CPSE रखेगी पर हर एक को स्टॉक एक्सचेंज में सूचीबद्ध करेगी","न्यूनतम उपस्थिति रखेगी और शेष का निजीकरण, विलय या बंद करेगी"],"explanationHi":"चार व्यापक रणनीतिक क्षेत्रों के लिए नीति न्यूनतम सार्वजनिक उपस्थिति रखती है; गैर-रणनीतिक क्षेत्रों में जहाँ संभव हो CPSE का निजीकरण या बंदी होनी है।"},
  {"id":"eco-sectors-schemes-136","question":"The monthly Index of Eight Core Industries is compiled and released by:","options":["The National Statistics Office under MoSPI","The Office of the Economic Adviser, DPIIT","The Reserve Bank of India","The Central Electricity Authority"],"answer":1,"explanation":"The Office of the Economic Adviser in DPIIT (Commerce and Industry Ministry) releases the core index, which is also a lead indicator for the IIP. The IIP itself is compiled by the NSO.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"आठ प्रमुख उद्योगों का मासिक सूचकांक किसके द्वारा संकलित और जारी किया जाता है?","optionsHi":["सांख्यिकी और कार्यक्रम कार्यान्वयन मंत्रालय के अधीन राष्ट्रीय सांख्यिकी कार्यालय","DPIIT का आर्थिक सलाहकार कार्यालय","भारतीय रिज़र्व बैंक","केंद्रीय विद्युत प्राधिकरण"],"explanationHi":"DPIIT (वाणिज्य एवं उद्योग मंत्रालय) में आर्थिक सलाहकार कार्यालय प्रमुख उद्योगों का सूचकांक जारी करता है, जो IIP का एक अग्रणी संकेतक भी है। IIP का संकलन स्वयं NSO करता है।"},
  {"id":"eco-sectors-schemes-137","question":"Which of the following is NOT a use-based category of the Index of Industrial Production?","options":["Infrastructure/construction goods","Consumer durables","Intermediate goods","Basic metals"],"answer":3,"explanation":"The use-based groups are primary, capital, intermediate, infrastructure/construction, consumer durable and consumer non-durable goods. Basic metals is an industry group under the sectoral (NIC) classification.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"निम्नलिखित में से कौन औद्योगिक उत्पादन सूचकांक की उपयोग-आधारित श्रेणी नहीं है?","optionsHi":["अवसंरचना/निर्माण वस्तुएँ","उपभोक्ता टिकाऊ वस्तुएँ","मध्यवर्ती वस्तुएँ","मूल धातुएँ"],"explanationHi":"उपयोग-आधारित समूह हैं: प्राथमिक, पूंजीगत, मध्यवर्ती, अवसंरचना/निर्माण, उपभोक्ता टिकाऊ और उपभोक्ता गैर-टिकाऊ वस्तुएँ। मूल धातुएँ क्षेत्रीय (NIC) वर्गीकरण के अंतर्गत एक उद्योग समूह है।"},
  {"id":"eco-sectors-schemes-138","question":"Under the MSMED Act, 2006, if a buyer fails to pay a micro or small supplier within the agreed period (which cannot exceed 45 days), the buyer must pay:","options":["Simple interest at the RBI’s bank rate for the period of delay","Compound interest, monthly rests, at three times the bank rate","Simple interest at the repo rate plus two percentage points","A flat penalty of 10% of the amount due, payable once"],"answer":1,"explanation":"Sections 15 and 16 of the MSMED Act cap the credit period at 45 days and impose compound interest at three times the RBI’s bank rate, with monthly rests, on delayed payments, to protect small suppliers’ cash flows.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"MSMED अधिनियम, 2006 के अंतर्गत, यदि कोई क्रेता किसी सूक्ष्म या लघु आपूर्तिकर्ता को सहमत अवधि (जो 45 दिन से अधिक नहीं हो सकती) में भुगतान नहीं करता, तो क्रेता को क्या चुकाना होगा?","optionsHi":["विलंब की अवधि के लिए RBI की बैंक दर पर साधारण ब्याज","बैंक दर के तीन गुना पर, मासिक अंतराल से, चक्रवृद्धि ब्याज","रेपो दर जमा दो प्रतिशत अंक पर साधारण ब्याज","देय राशि का 10% का एकमुश्त दंड, एक बार देय"],"explanationHi":"MSMED अधिनियम की धाराएँ 15 और 16 ऋण अवधि को 45 दिन तक सीमित करती हैं और विलंबित भुगतानों पर RBI की बैंक दर के तीन गुना पर मासिक अंतराल से चक्रवृद्धि ब्याज लगाती हैं, ताकि छोटे आपूर्तिकर्ताओं का नकदी प्रवाह सुरक्षित रहे।"},
  {"id":"eco-sectors-schemes-139","question":"The Trade Receivables electronic Discounting System (TReDS) helps MSMEs mainly by:","options":["Giving them collateral-free term loans at a fixed concessional rate","Letting financiers bid to discount invoices raised on big buyers","Guaranteeing their exports against non-payment by foreign buyers","Allowing them to list their shares on a special SME exchange"],"answer":1,"explanation":"On TReDS platforms set up under RBI guidelines, an MSME’s invoices accepted by corporate or government buyers are auctioned to banks and NBFCs, so the seller is paid early without recourse to it.","difficulty":"hard","source":"RBI Grade B","questionHi":"ट्रेड रिसीवेबल्स इलेक्ट्रॉनिक डिस्काउंटिंग सिस्टम (TReDS) MSME की मुख्यतः कैसे मदद करता है?","optionsHi":["उन्हें एक निश्चित रियायती दर पर बिना संपार्श्विक सावधि ऋण देकर","बड़े क्रेताओं पर बनाए गए बिलों की बट्टा-कटौती के लिए वित्तदाताओं को बोली लगाने देकर","विदेशी क्रेताओं द्वारा भुगतान न करने के विरुद्ध उनके निर्यात की गारंटी देकर","उन्हें एक विशेष SME एक्सचेंज पर अपने शेयर सूचीबद्ध करने देकर"],"explanationHi":"RBI के दिशानिर्देशों के अंतर्गत बने TReDS मंचों पर, कॉर्पोरेट या सरकारी क्रेताओं द्वारा स्वीकृत MSME के बिलों की बैंकों और NBFC को नीलामी होती है, जिससे विक्रेता को बिना उसके विरुद्ध दावे के जल्दी भुगतान मिल जाता है।"},
  {"id":"eco-sectors-schemes-140","question":"The Credit Guarantee Fund Trust for Micro and Small Enterprises, which backs collateral-free loans to such units, was set up in 2000 by the Government of India and:","options":["NABARD","The Reserve Bank of India","SIDBI","State Bank of India"],"answer":2,"explanation":"CGTMSE was set up jointly by the Government of India (Ministry of MSME) and SIDBI; it guarantees a large part of loans given without collateral or third-party guarantee to micro and small enterprises.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"सूक्ष्म और लघु उद्यमों के लिए ऋण गारंटी निधि न्यास, जो ऐसी इकाइयों को बिना संपार्श्विक ऋणों का समर्थन करता है, 2000 में भारत सरकार और किसके द्वारा स्थापित किया गया?","optionsHi":["NABARD","भारतीय रिज़र्व बैंक","SIDBI","भारतीय स्टेट बैंक"],"explanationHi":"CGTMSE की स्थापना भारत सरकार (MSME मंत्रालय) और SIDBI ने संयुक्त रूप से की; यह सूक्ष्म और लघु उद्यमों को बिना संपार्श्विक या तृतीय-पक्ष गारंटी के दिए गए ऋणों के बड़े हिस्से की गारंटी देता है।"},
  {"id":"eco-sectors-schemes-141","question":"The Prime Minister’s Employment Generation Programme (PMEGP), formed in 2008 by merging PMRY and REGP, is implemented at the national level by:","options":["SIDBI","NABARD","The National Skill Development Corporation (NSDC)","The Khadi and Village Industries Commission"],"answer":3,"explanation":"PMEGP is a credit-linked subsidy scheme of the MSME Ministry for setting up micro enterprises; KVIC is the national nodal agency, working with State KVIBs and District Industries Centres.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"PMRY और REGP को मिलाकर 2008 में बने प्रधानमंत्री रोज़गार सृजन कार्यक्रम (PMEGP) का राष्ट्रीय स्तर पर क्रियान्वयन कौन करता है?","optionsHi":["SIDBI","NABARD","राष्ट्रीय कौशल विकास निगम (NSDC)","खादी और ग्रामोद्योग आयोग"],"explanationHi":"PMEGP सूक्ष्म उद्यम स्थापित करने के लिए MSME मंत्रालय की ऋण-संबद्ध अनुदान योजना है; KVIC राष्ट्रीय नोडल एजेंसी है, जो राज्य KVIB और ज़िला उद्योग केंद्रों के साथ काम करती है।"},
  {"id":"eco-sectors-schemes-142","question":"‘Udyam Registration’, introduced on 1 July 2020 for micro, small and medium enterprises, replaced the:","options":["Udyog Aadhaar Memorandum","Shops and Establishments licence","GST registration","Factories Act licence"],"answer":0,"explanation":"Udyam Registration is an online, paperless, self-declaration system linked to PAN and GST data; it replaced the Udyog Aadhaar Memorandum and uses the revised investment-plus-turnover criteria.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"सूक्ष्म, लघु और मध्यम उद्यमों के लिए 1 जुलाई 2020 को शुरू किए गए ‘उद्यम पंजीकरण’ ने किसका स्थान लिया?","optionsHi":["उद्योग आधार ज्ञापन","दुकान और प्रतिष्ठान लाइसेंस","GST पंजीकरण","कारखाना अधिनियम लाइसेंस"],"explanationHi":"उद्यम पंजीकरण ऑनलाइन, कागज़ रहित, स्व-घोषणा प्रणाली है जो PAN और GST डेटा से जुड़ी है; इसने उद्योग आधार ज्ञापन का स्थान लिया और संशोधित निवेश-और-टर्नओवर मानदंडों का उपयोग करती है।"},
  {"id":"eco-sectors-schemes-143","question":"In India’s Agriculture Census, an operational holding of 3 hectares falls in which size class?","options":["Small","Semi-medium","Medium","Marginal"],"answer":1,"explanation":"The classes are marginal (below 1 ha), small (1–2 ha), semi-medium (2–4 ha), medium (4–10 ha) and large (10 ha and above), so 3 ha is semi-medium. Marginal and small together form the great majority of holdings.","difficulty":"very-hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"भारत की कृषि गणना में 3 हेक्टेयर की संचालन जोत किस आकार वर्ग में आती है?","optionsHi":["लघु","अर्ध-मध्यम","मध्यम","सीमांत"],"explanationHi":"वर्ग हैं: सीमांत (1 ha से कम), लघु (1–2 ha), अर्ध-मध्यम (2–4 ha), मध्यम (4–10 ha) और बड़ी (10 ha और अधिक), इसलिए 3 ha अर्ध-मध्यम है। सीमांत और लघु मिलकर जोतों का बहुत बड़ा भाग हैं।"},
  {"id":"eco-sectors-schemes-144","question":"How many of these statements are correct? I. The Commission for Agricultural Costs and Prices is a statutory body. II. MSPs for kharif and rabi crops are announced by the Government after considering CACP’s recommendations. III. The fair and remunerative price of sugarcane is fixed under the Sugarcane (Control) Order, 1966. IV. MSP is legally enforceable, so private traders must buy at or above it.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and III are correct. CACP is an attached office of the Agriculture Ministry, not a statutory body, and MSP is a policy price used for government procurement with no legal force on private trade.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"इनमें से कितने कथन सही हैं? I. कृषि लागत और मूल्य आयोग एक सांविधिक निकाय है। II. खरीफ और रबी फसलों के MSP की घोषणा सरकार CACP की सिफारिशों पर विचार के बाद करती है। III. गन्ने का उचित और लाभकारी मूल्य गन्ना (नियंत्रण) आदेश, 1966 के अंतर्गत तय होता है। IV. MSP कानूनी रूप से प्रवर्तनीय है, इसलिए निजी व्यापारियों को उससे ऊपर या उसी पर खरीदना होगा।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"II और III सही हैं। CACP कृषि मंत्रालय का संलग्न कार्यालय है, सांविधिक निकाय नहीं, और MSP सरकारी खरीद के लिए प्रयुक्त नीतिगत मूल्य है जिसका निजी व्यापार पर कोई कानूनी बल नहीं है।"},
  {"id":"eco-sectors-schemes-145","question":"In CACP cost concepts, cost C2 differs from cost A2+FL mainly because C2 also includes:","options":["The imputed value of the unpaid labour of family members","Paid-out costs on seeds, fertilisers and hired labour","Rent on owned land and interest on owned fixed capital","Depreciation on implements and farm buildings"],"answer":2,"explanation":"A2 covers paid-out costs (including depreciation), A2+FL adds unpaid family labour, and C2 further adds imputed rent on owned land and interest on owned capital, making it the most comprehensive cost.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"CACP की लागत अवधारणाओं में, लागत C2 लागत A2+FL से मुख्यतः इसलिए भिन्न है क्योंकि C2 में और क्या शामिल होता है?","optionsHi":["परिवार के सदस्यों के अवैतनिक श्रम का आरोपित मूल्य","बीज, उर्वरक और किराये के श्रम पर चुकाई गई लागत","स्वामित्व वाली भूमि पर किराया और स्वामित्व वाली स्थायी पूंजी पर ब्याज","औज़ारों और कृषि भवनों पर मूल्यह्रास"],"explanationHi":"A2 में चुकाई गई लागत (मूल्यह्रास सहित) आती है, A2+FL में अवैतनिक पारिवारिक श्रम जुड़ता है, और C2 में स्वामित्व वाली भूमि का आरोपित किराया और स्वामित्व वाली पूंजी पर ब्याज भी जुड़ जाते हैं, जिससे यह सबसे व्यापक लागत है।"},
  {"id":"eco-sectors-schemes-146","question":"Since 2018–19, the Centre has fixed the MSPs of mandated crops at a level of at least 1.5 times the:","options":["A2 cost","A2+FL cost","C2 cost","B2 cost"],"answer":1,"explanation":"The 2018–19 Budget promised MSP of at least one and a half times the cost of production, and the cost used is A2+FL. The National Commission on Farmers had recommended 1.5 times the C2 cost.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"2018–19 से केंद्र ने अधिदेशित फसलों के MSP को किस लागत के कम से कम 1.5 गुना के स्तर पर तय किया है?","optionsHi":["A2 लागत","A2+FL लागत","C2 लागत","B2 लागत"],"explanationHi":"2018–19 के बजट ने उत्पादन लागत के कम से कम डेढ़ गुना MSP का वादा किया, और प्रयुक्त लागत A2+FL है। राष्ट्रीय किसान आयोग ने C2 लागत का 1.5 गुना सिफारिश किया था।"},
  {"id":"eco-sectors-schemes-147","question":"Match the ‘revolution’ with its product: A. Yellow  B. Blue  C. White  D. Round; 1. Milk  2. Potato  3. Oilseeds  4. Fish","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-1, B-4, C-3, D-2"],"answer":2,"explanation":"The Yellow Revolution was in oilseeds, the Blue in fisheries, the White in milk (Operation Flood) and the Round in potatoes.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"‘क्रांति’ का उसके उत्पाद से मिलान कीजिए: A. पीली  B. नीली  C. श्वेत  D. गोल; 1. दूध  2. आलू  3. तिलहन  4. मछली","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-1, B-4, C-3, D-2"],"explanationHi":"पीली क्रांति तिलहनों में, नीली मत्स्य पालन में, श्वेत दूध में (ऑपरेशन फ्लड) और गोल आलू में थी।"},
  {"id":"eco-sectors-schemes-148","question":"Operation Flood, launched in 1970 to create a national milk grid linking producers with urban consumers, was implemented by:","options":["The National Dairy Development Board","Amul (Kaira District Co-operative Milk Producers’ Union)","NABARD","The Ministry of Food Processing Industries"],"answer":0,"explanation":"NDDB, headed by Verghese Kurien, ran Operation Flood in three phases up to 1996, replicating the Anand-pattern cooperatives across the country. Amul was the model, not the implementing agency.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"उत्पादकों को शहरी उपभोक्ताओं से जोड़ने वाला राष्ट्रीय दुग्ध ग्रिड बनाने के लिए 1970 में शुरू किया गया ऑपरेशन फ्लड किसके द्वारा क्रियान्वित किया गया?","optionsHi":["राष्ट्रीय डेयरी विकास बोर्ड","अमूल (कैरा ज़िला सहकारी दुग्ध उत्पादक संघ)","NABARD","खाद्य प्रसंस्करण उद्योग मंत्रालय"],"explanationHi":"वर्गीज़ कुरियन की अध्यक्षता वाले NDDB ने ऑपरेशन फ्लड को 1996 तक तीन चरणों में चलाया और आनंद पैटर्न की सहकारी समितियाँ पूरे देश में फैलाईं। अमूल मॉडल था, क्रियान्वयन एजेंसी नहीं।"},
  {"id":"eco-sectors-schemes-149","question":"The Technology Mission on Oilseeds (1986), which drove the ‘Yellow Revolution’, is associated with:","options":["M. S. Swaminathan","Verghese Kurien","Sam Pitroda","Norman Borlaug"],"answer":2,"explanation":"The Technology Mission on Oilseeds was one of the technology missions under Rajiv Gandhi led by Sam Pitroda. Swaminathan and Borlaug are linked with the Green Revolution, Kurien with the White Revolution.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"तिलहन पर प्रौद्योगिकी मिशन (1986), जिसने ‘पीली क्रांति’ को आगे बढ़ाया, किससे संबद्ध है?","optionsHi":["एम. एस. स्वामीनाथन","वर्गीज़ कुरियन","सैम पित्रोदा","नॉर्मन बोरलॉग"],"explanationHi":"तिलहन पर प्रौद्योगिकी मिशन राजीव गांधी के समय के उन प्रौद्योगिकी मिशनों में से एक था जिनका नेतृत्व सैम पित्रोदा ने किया। स्वामीनाथन और बोरलॉग हरित क्रांति से जुड़े हैं, कुरियन श्वेत क्रांति से।"},
  {"id":"eco-sectors-schemes-150","question":"Assertion (A): The early gains of the Green Revolution were concentrated mainly in wheat in the irrigated north-west of India. Reason (R): The high-yielding varieties needed assured irrigation and heavy use of fertilisers.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"HYV seeds paid off only with assured water and inputs, which Punjab, Haryana and western Uttar Pradesh had; this widened regional and crop disparities, with rice and rain-fed areas gaining later.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"अभिकथन (A): हरित क्रांति के शुरुआती लाभ मुख्यतः भारत के सिंचित उत्तर-पश्चिम में गेहूँ में केंद्रित थे। कारण (R): उच्च उपज वाली किस्मों को सुनिश्चित सिंचाई और उर्वरकों के भारी उपयोग की आवश्यकता थी।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"HYV बीज तभी फल देते थे जब सुनिश्चित जल और आगत हों, जो पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश के पास थे; इससे क्षेत्रीय और फसल असमानताएँ बढ़ीं, जबकि चावल और वर्षा-आधारित क्षेत्रों को बाद में लाभ हुआ।"},
  {"id":"eco-sectors-schemes-151","question":"‘Per Drop More Crop’, which promotes micro-irrigation such as drip and sprinklers, is a component of:","options":["Pradhan Mantri Krishi Sinchayee Yojana","Mission for Integrated Development of Horticulture","Paramparagat Krishi Vikas Yojana","Pradhan Mantri Fasal Bima Yojana"],"answer":0,"explanation":"PMKSY, launched in 2015, has components such as ‘Har Khet Ko Pani’ (expanding irrigation) and ‘Per Drop More Crop’ (water-use efficiency at the farm).","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"‘प्रति बूँद अधिक फसल’, जो ड्रिप और स्प्रिंकलर जैसी सूक्ष्म सिंचाई को बढ़ावा देता है, किसका घटक है?","optionsHi":["प्रधानमंत्री कृषि सिंचाई योजना","बागवानी के एकीकृत विकास का मिशन","परंपरागत कृषि विकास योजना","प्रधानमंत्री फसल बीमा योजना"],"explanationHi":"2015 में शुरू PMKSY के घटकों में ‘हर खेत को पानी’ (सिंचाई का विस्तार) और ‘प्रति बूँद अधिक फसल’ (खेत पर जल-उपयोग दक्षता) शामिल हैं।"},
  {"id":"eco-sectors-schemes-152","question":"The Paramparagat Krishi Vikas Yojana, launched in 2015, mainly promotes:","options":["Organic farming through clusters of farmers with group certification","Crop insurance for traditional rice and millet varieties at low premium","Revival of old village irrigation tanks through the gram panchayats","Traditional handloom and handicraft clusters in rural districts"],"answer":0,"explanation":"PKVY organises farmers into clusters to take up organic farming, supports inputs and marketing, and uses the Participatory Guarantee System (PGS-India) for certification.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"2015 में शुरू की गई परंपरागत कृषि विकास योजना मुख्यतः किसे बढ़ावा देती है?","optionsHi":["किसानों के समूहों के माध्यम से समूह प्रमाणन के साथ जैविक खेती","पारंपरिक चावल और मोटे अनाज की किस्मों के लिए कम प्रीमियम पर फसल बीमा","ग्राम पंचायतों के माध्यम से पुराने ग्रामीण सिंचाई तालाबों का पुनरुद्धार","ग्रामीण ज़िलों में पारंपरिक हथकरघा और हस्तशिल्प समूह"],"explanationHi":"PKVY किसानों को जैविक खेती अपनाने के लिए समूहों में संगठित करती है, आगतों और विपणन में सहायता देती है, और प्रमाणन के लिए सहभागी गारंटी प्रणाली (PGS-India) का उपयोग करती है।"},
  {"id":"eco-sectors-schemes-153","question":"The Agriculture Infrastructure Fund, set up in 2020, mainly provides:","options":["Direct cash transfers to farmers for buying tractors and machinery","Grants to the States for building new APMC mandi yards and roads","Equity capital to agri-startups through a dedicated fund of funds","Subsidised, guaranteed loans for post-harvest and community assets"],"answer":3,"explanation":"The ₹1 lakh crore financing facility gives 3% interest subvention and credit guarantee cover on loans up to ₹2 crore for warehouses, cold chains, processing units and similar assets.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"2020 में स्थापित कृषि अवसंरचना कोष मुख्यतः क्या प्रदान करता है?","optionsHi":["ट्रैक्टर और मशीनरी खरीदने के लिए किसानों को प्रत्यक्ष नकद अंतरण","नए APMC मंडी प्रांगण और सड़कें बनाने के लिए राज्यों को अनुदान","समर्पित फंड ऑफ फंड्स के माध्यम से कृषि-स्टार्टअप्स को इक्विटी पूंजी","फसलोत्तर और सामुदायिक परिसंपत्तियों के लिए अनुदानित, गारंटीशुदा ऋण"],"explanationHi":"₹1 लाख करोड़ की यह वित्तपोषण सुविधा गोदामों, शीत शृंखलाओं, प्रसंस्करण इकाइयों और ऐसी ही परिसंपत्तियों के लिए ₹2 करोड़ तक के ऋणों पर 3% ब्याज अनुदान और ऋण गारंटी कवर देती है।"},
  {"id":"eco-sectors-schemes-154","question":"Operation Greens, announced in 2018 under the Ministry of Food Processing Industries, initially aimed to stabilise the supply and prices of:","options":["Pulses, oilseeds and maize","Wheat, rice and coarse cereals","Milk, eggs and fish","Tomato, onion and potato"],"answer":3,"explanation":"Modelled on Operation Flood, it began with the ‘TOP’ crops, whose prices swing sharply; in 2020 it was extended to other fruits and vegetables.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"खाद्य प्रसंस्करण उद्योग मंत्रालय के अंतर्गत 2018 में घोषित ऑपरेशन ग्रीन्स का आरंभिक उद्देश्य किसकी आपूर्ति और कीमतों को स्थिर करना था?","optionsHi":["दालें, तिलहन और मक्का","गेहूँ, चावल और मोटे अनाज","दूध, अंडे और मछली","टमाटर, प्याज और आलू"],"explanationHi":"ऑपरेशन फ्लड की तर्ज पर इसकी शुरुआत ‘TOP’ फसलों से हुई, जिनकी कीमतें तेज़ी से उतार-चढ़ाव करती हैं; 2020 में इसे अन्य फलों और सब्ज़ियों तक बढ़ाया गया।"},
  {"id":"eco-sectors-schemes-155","question":"The e-Shram portal, launched in 2021, is meant to:","options":["Build an Aadhaar-linked national database of unorganised workers","Register start-ups for tax benefits under the Startup India scheme","Pay MGNREGA wages directly into the bank accounts of workers","Match young graduates with apprenticeship places in industry"],"answer":0,"explanation":"Run by the Ministry of Labour and Employment, e-Shram registers unorganised workers, including migrants and gig workers, and gives each a Universal Account Number to help deliver social security benefits.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"2021 में शुरू किए गए e-श्रम पोर्टल का उद्देश्य क्या है?","optionsHi":["असंगठित श्रमिकों का आधार से जुड़ा राष्ट्रीय डेटाबेस बनाना","स्टार्टअप इंडिया योजना के अंतर्गत कर लाभों के लिए स्टार्टअप का पंजीकरण करना","MGNREGA की मज़दूरी सीधे श्रमिकों के बैंक खातों में पहुँचाना","युवा स्नातकों को उद्योग में प्रशिक्षुता के अवसरों से जोड़ना"],"explanationHi":"श्रम और रोज़गार मंत्रालय द्वारा संचालित e-श्रम प्रवासियों और गिग श्रमिकों सहित असंगठित श्रमिकों का पंजीकरण करता है और सामाजिक सुरक्षा लाभ पहुँचाने में मदद के लिए हर एक को सार्वभौमिक खाता संख्या देता है।"},
  {"id":"eco-sectors-schemes-156","question":"The Jawahar Rozgar Yojana, launched in 1989, was formed by merging:","options":["IRDP and TRYSEM","EAS and JGSY","NREP and RLEGP","SGSY and DWCRA"],"answer":2,"explanation":"JRY combined the National Rural Employment Programme (1980) and the Rural Landless Employment Guarantee Programme (1983). EAS and JGSY were later merged into SGRY in 2001.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"1989 में शुरू की गई जवाहर रोज़गार योजना किनको मिलाकर बनी थी?","optionsHi":["IRDP और TRYSEM","EAS और JGSY","NREP और RLEGP","SGSY और DWCRA"],"explanationHi":"JRY ने राष्ट्रीय ग्रामीण रोज़गार कार्यक्रम (1980) और ग्रामीण भूमिहीन रोज़गार गारंटी कार्यक्रम (1983) को मिलाया। EAS और JGSY बाद में 2001 में SGRY में मिलाए गए।"},
  {"id":"eco-sectors-schemes-157","question":"Which of the following was NOT merged into the Swarnjayanti Gram Swarozgar Yojana in 1999?","options":["Integrated Rural Development Programme","Training of Rural Youth for Self-Employment","Development of Women and Children in Rural Areas","National Food for Work Programme"],"answer":3,"explanation":"SGSY brought together IRDP, TRYSEM, DWCRA, SITRA, GKY and the Million Wells Scheme as one self-employment programme. The Food for Work Programme came later (2004) and was folded into NREGA.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"निम्नलिखित में से कौन 1999 में स्वर्णजयंती ग्राम स्वरोज़गार योजना में विलीन नहीं किया गया था?","optionsHi":["एकीकृत ग्रामीण विकास कार्यक्रम","स्वरोज़गार के लिए ग्रामीण युवाओं का प्रशिक्षण","ग्रामीण क्षेत्रों में महिलाओं और बच्चों का विकास","राष्ट्रीय काम के बदले अनाज कार्यक्रम"],"explanationHi":"SGSY ने IRDP, TRYSEM, DWCRA, SITRA, GKY और दस लाख कुआँ योजना को एक स्वरोज़गार कार्यक्रम के रूप में एक साथ लाया। काम के बदले अनाज कार्यक्रम बाद में (2004) आया और NREGA में मिला दिया गया।"},
  {"id":"eco-sectors-schemes-158","question":"Arrange in time order: 1. Sampoorna Grameen Rozgar Yojana launched  2. NREGA comes into force in 200 districts  3. Jawahar Rozgar Yojana launched  4. National Food for Work Programme launched","options":["3, 1, 4, 2","3, 4, 1, 2","1, 3, 4, 2","3, 1, 2, 4"],"answer":0,"explanation":"JRY came in 1989, SGRY in 2001, the National Food for Work Programme in 2004, and NREGA came into force on 2 February 2006; it was renamed after Mahatma Gandhi in 2009.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"कालक्रम से व्यवस्थित कीजिए: 1. संपूर्ण ग्रामीण रोज़गार योजना शुरू हुई  2. NREGA 200 ज़िलों में लागू हुआ  3. जवाहर रोज़गार योजना शुरू हुई  4. राष्ट्रीय काम के बदले अनाज कार्यक्रम शुरू हुआ","optionsHi":["3, 1, 4, 2","3, 4, 1, 2","1, 3, 4, 2","3, 1, 2, 4"],"explanationHi":"JRY 1989 में, SGRY 2001 में, राष्ट्रीय काम के बदले अनाज कार्यक्रम 2004 में आया, और NREGA 2 फरवरी 2006 को लागू हुआ; 2009 में इसका नाम महात्मा गांधी के नाम पर रखा गया।"},
  {"id":"eco-sectors-schemes-159","question":"Under MGNREGA, an applicant who is not given work within 15 days is entitled to an unemployment allowance of at least:","options":["Half the wage rate for the first 30 days and the full wage thereafter","One-fourth of the wage rate for the first 30 days and half thereafter","One-third of the wage rate throughout the rest of the financial year","The full notified wage rate from the first day of delay"],"answer":1,"explanation":"Section 7 of the Act sets the allowance at not less than one-fourth of the wage rate for the first 30 days in a financial year and not less than half for the rest of the year; it is paid by the State.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"MGNREGA के अंतर्गत, जिस आवेदक को 15 दिन के भीतर काम नहीं दिया जाता, वह कम से कम कितने बेरोज़गारी भत्ते का हकदार है?","optionsHi":["पहले 30 दिन के लिए मज़दूरी दर का आधा और उसके बाद पूरी मज़दूरी","पहले 30 दिन के लिए मज़दूरी दर का एक-चौथाई और उसके बाद आधा","वित्तीय वर्ष के शेष भाग भर मज़दूरी दर का एक-तिहाई","विलंब के पहले दिन से पूरी अधिसूचित मज़दूरी दर"],"explanationHi":"अधिनियम की धारा 7 भत्ते को वित्तीय वर्ष के पहले 30 दिन के लिए मज़दूरी दर के कम से कम एक-चौथाई और वर्ष के शेष भाग के लिए कम से कम आधे पर तय करती है; इसका भुगतान राज्य करता है।"},
  {"id":"eco-sectors-schemes-160","question":"How many of these statements about MGNREGA are correct? I. Job cards are issued to households free of cost. II. Contractors are not allowed in carrying out the works. III. As far as practicable, works are to be done by manual labour rather than machines. IV. The Central Government notifies the wage rate for each State.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four reflect the Act: free job cards, a ban on contractors, a preference for manual labour over labour-displacing machines, and wage rates notified by the Centre under Section 6(1).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"MGNREGA के बारे में इनमें से कितने कथन सही हैं? I. जॉब कार्ड परिवारों को निःशुल्क जारी किए जाते हैं। II. कार्यों के निष्पादन में ठेकेदारों की अनुमति नहीं है। III. जहाँ तक व्यावहारिक हो, कार्य मशीनों के बजाय शारीरिक श्रम से कराए जाएँ। IV. केंद्र सरकार प्रत्येक राज्य के लिए मज़दूरी दर अधिसूचित करती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों अधिनियम को दर्शाते हैं: निःशुल्क जॉब कार्ड, ठेकेदारों पर प्रतिबंध, श्रम-विस्थापक मशीनों के बजाय शारीरिक श्रम को प्राथमिकता, और धारा 6(1) के अंतर्गत केंद्र द्वारा अधिसूचित मज़दूरी दरें।"},
  {"id":"eco-sectors-schemes-161","question":"The National Social Assistance Programme, launched in 1995 with old age, widow and disability pensions, gives effect mainly to which Directive Principle?","options":["Article 39A","Article 43","Article 41","Article 47"],"answer":2,"explanation":"Article 41 asks the State to provide public assistance in cases of old age, sickness, disablement and undeserved want. Article 39A covers free legal aid, 43 a living wage, and 47 nutrition and public health.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"1995 में वृद्धावस्था, विधवा और विकलांगता पेंशन के साथ शुरू किया गया राष्ट्रीय सामाजिक सहायता कार्यक्रम मुख्यतः किस नीति निदेशक तत्व को प्रभावी बनाता है?","optionsHi":["अनुच्छेद 39A","अनुच्छेद 43","अनुच्छेद 41","अनुच्छेद 47"],"explanationHi":"अनुच्छेद 41 राज्य से वृद्धावस्था, बीमारी, अपंगता और अनर्जित अभाव के मामलों में लोक सहायता देने की अपेक्षा करता है। अनुच्छेद 39A निःशुल्क विधिक सहायता, 43 निर्वाह मज़दूरी, और 47 पोषण तथा लोक स्वास्थ्य से संबंधित है।"},
  {"id":"eco-sectors-schemes-162","question":"Under the National Family Benefit Scheme, part of NSAP, assistance is given:","options":["As a monthly pension to every widow living in a BPL household","As a cash incentive to BPL families on the birth of a girl child","As a lump sum to a BPL household when its main earner dies","As free life insurance cover for all members of a BPL household"],"answer":2,"explanation":"NFBS pays a one-time lump sum to a poor household when its main earner, aged 18 to 59, dies. Widow pensions come under a separate NSAP component.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"NSAP के भाग, राष्ट्रीय परिवार लाभ योजना के अंतर्गत सहायता किस रूप में दी जाती है?","optionsHi":["BPL परिवार में रहने वाली हर विधवा को मासिक पेंशन के रूप में","बालिका के जन्म पर BPL परिवारों को नकद प्रोत्साहन के रूप में","BPL परिवार के मुख्य कमाने वाले की मृत्यु होने पर एकमुश्त राशि के रूप में","BPL परिवार के सभी सदस्यों के लिए निःशुल्क जीवन बीमा कवर के रूप में"],"explanationHi":"NFBS किसी गरीब परिवार के मुख्य कमाने वाले की, जिसकी आयु 18 से 59 वर्ष हो, मृत्यु होने पर एकमुश्त राशि देती है। विधवा पेंशन NSAP का एक अलग घटक है।"},
  {"id":"eco-sectors-schemes-163","question":"The Annapurna scheme provides:","options":["Free cooked midday meals to all school children up to Class VIII","Subsidised grain to Antyodaya households at a nominal token price","10 kg of free grain a month to needy elderly without a pension","Free LPG refills every month to elderly women living in villages"],"answer":2,"explanation":"Annapurna, part of NSAP since 2000, gives 10 kg of free foodgrains a month to senior citizens who qualify for an old age pension but are not receiving it.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"अन्नपूर्णा योजना क्या प्रदान करती है?","optionsHi":["आठवीं कक्षा तक के सभी स्कूली बच्चों को निःशुल्क पका हुआ मध्याह्न भोजन","अंत्योदय परिवारों को सांकेतिक नाममात्र कीमत पर अनुदानित अनाज","पेंशन न पाने वाले ज़रूरतमंद बुज़ुर्गों को हर माह 10 kg निःशुल्क अनाज","गाँवों में रहने वाली बुज़ुर्ग महिलाओं को हर माह निःशुल्क LPG रिफिल"],"explanationHi":"2000 से NSAP का भाग अन्नपूर्णा उन वरिष्ठ नागरिकों को हर माह 10 kg निःशुल्क खाद्यान्न देती है जो वृद्धावस्था पेंशन के पात्र हैं पर उसे पा नहीं रहे।"},
  {"id":"eco-sectors-schemes-164","question":"Which of these is NOT one of the six services provided under the Integrated Child Development Services (ICDS) scheme?","options":["Supplementary nutrition","Pre-school non-formal education","Immunisation and health check-ups","Free secondary-school textbooks"],"answer":3,"explanation":"Since 1975, ICDS has offered supplementary nutrition, pre-school education, nutrition and health education, immunisation, health check-ups and referral services through anganwadi centres. School textbooks are not part of it.","difficulty":"very-hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"इनमें से कौन एकीकृत बाल विकास सेवाएँ (ICDS) योजना के अंतर्गत दी जाने वाली छह सेवाओं में से नहीं है?","optionsHi":["पूरक पोषण","पूर्व-विद्यालयी अनौपचारिक शिक्षा","टीकाकरण और स्वास्थ्य जाँच","माध्यमिक स्कूल की निःशुल्क पाठ्यपुस्तकें"],"explanationHi":"1975 से ICDS आँगनवाड़ी केंद्रों के माध्यम से पूरक पोषण, पूर्व-विद्यालयी शिक्षा, पोषण और स्वास्थ्य शिक्षा, टीकाकरण, स्वास्थ्य जाँच और रेफरल सेवाएँ देती रही है। स्कूली पाठ्यपुस्तकें इसका भाग नहीं हैं।"},
  {"id":"eco-sectors-schemes-165","question":"The Janani Suraksha Yojana, launched in 2005 under the National Rural Health Mission, mainly aims to:","options":["Promote hospital births among poor mothers through cash aid","Provide free contraceptives to all married couples in villages","Insure mothers against the cost of caesarean surgery in hospitals","Give free nutrition kits to all children below six years of age"],"answer":0,"explanation":"JSY is a conditional cash transfer that rewards delivery in a health facility, to cut maternal and newborn deaths; ASHA workers help mothers reach facilities.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"राष्ट्रीय ग्रामीण स्वास्थ्य मिशन के अंतर्गत 2005 में शुरू की गई जननी सुरक्षा योजना का मुख्य उद्देश्य क्या है?","optionsHi":["नकद सहायता से गरीब माताओं में अस्पताल में प्रसव को बढ़ावा देना","गाँवों के सभी विवाहित दंपतियों को निःशुल्क गर्भनिरोधक देना","अस्पतालों में सिजेरियन शल्य-क्रिया की लागत के विरुद्ध माताओं का बीमा करना","छह वर्ष से कम आयु के सभी बच्चों को निःशुल्क पोषण किट देना"],"explanationHi":"JSY एक सशर्त नकद अंतरण है जो स्वास्थ्य केंद्र में प्रसव को पुरस्कृत करता है, ताकि मातृ और नवजात मृत्यु घटें; आशा कार्यकर्ता माताओं को केंद्रों तक पहुँचने में मदद करती हैं।"},
  {"id":"eco-sectors-schemes-166","question":"The Pradhan Mantri Matru Vandana Yojana, launched in 2017, provides:","options":["Free hospital delivery for all women in government hospitals","Monthly pensions to widows aged above 40 in poor rural households","Cash support to pregnant and lactating women for lost wages","Free sanitary products to all adolescent girls in government schools"],"answer":2,"explanation":"PMMVY is a maternity benefit scheme giving cash in instalments, mainly for the first living child, to partly compensate for wage loss and encourage health-seeking behaviour.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"2017 में शुरू की गई प्रधानमंत्री मातृ वंदना योजना क्या प्रदान करती है?","optionsHi":["सरकारी अस्पतालों में सभी महिलाओं को निःशुल्क अस्पताल प्रसव","गरीब ग्रामीण परिवारों की 40 वर्ष से अधिक आयु की विधवाओं को मासिक पेंशन","गर्भवती और स्तनपान कराने वाली महिलाओं को खोई मज़दूरी के लिए नकद सहायता","सरकारी स्कूलों की सभी किशोरियों को निःशुल्क सैनिटरी उत्पाद"],"explanationHi":"PMMVY एक मातृत्व लाभ योजना है जो मुख्यतः पहले जीवित बच्चे के लिए किस्तों में नकद देती है, ताकि मज़दूरी की हानि की आंशिक भरपाई हो और स्वास्थ्य-सजग व्यवहार को प्रोत्साहन मिले।"},
  {"id":"eco-sectors-schemes-167","question":"Samagra Shiksha, launched in 2018 as an integrated scheme for school education, subsumed:","options":["SSA, RMSA and Teacher Education","SSA, mid-day meals and Teacher Education","RMSA, RUSA and the National Means-cum-Merit Scheme","SSA, RUSA and Kendriya Vidyalayas"],"answer":0,"explanation":"It merged Sarva Shiksha Abhiyan, Rashtriya Madhyamik Shiksha Abhiyan and Teacher Education to treat schooling from pre-school to Class XII as a continuum. RUSA is for higher education and mid-day meals remain a separate scheme.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"2018 में स्कूली शिक्षा के लिए एकीकृत योजना के रूप में शुरू की गई समग्र शिक्षा ने किन्हें समाहित किया?","optionsHi":["SSA, RMSA और शिक्षक शिक्षा","SSA, मध्याह्न भोजन और शिक्षक शिक्षा","RMSA, RUSA और राष्ट्रीय साधन-सह-मेधा छात्रवृत्ति योजना","SSA, RUSA और केंद्रीय विद्यालय"],"explanationHi":"इसने सर्व शिक्षा अभियान, राष्ट्रीय माध्यमिक शिक्षा अभियान और शिक्षक शिक्षा को मिलाया, ताकि पूर्व-विद्यालय से कक्षा XII तक की स्कूली शिक्षा को एक सतत शृंखला माना जाए। RUSA उच्च शिक्षा के लिए है और मध्याह्न भोजन एक अलग योजना है।"},
  {"id":"eco-sectors-schemes-168","question":"The two pillars of Ayushman Bharat, launched in 2018, are:","options":["PM-JAY and the National Health Mission","Health and Wellness Centres and PM-JAY","Jan Aushadhi Kendras and Health and Wellness Centres","PM-JAY and the Ayushman Bharat Digital Mission"],"answer":1,"explanation":"Ayushman Bharat combines Health and Wellness Centres (now Ayushman Arogya Mandirs) for comprehensive primary care with PM-JAY, which covers secondary and tertiary hospitalisation.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"2018 में शुरू किए गए आयुष्मान भारत के दो स्तंभ कौन-से हैं?","optionsHi":["PM-JAY और राष्ट्रीय स्वास्थ्य मिशन","स्वास्थ्य एवं कल्याण केंद्र और PM-JAY","जन औषधि केंद्र और स्वास्थ्य एवं कल्याण केंद्र","PM-JAY और आयुष्मान भारत डिजिटल मिशन"],"explanationHi":"आयुष्मान भारत व्यापक प्राथमिक देखभाल के लिए स्वास्थ्य एवं कल्याण केंद्रों (अब आयुष्मान आरोग्य मंदिर) को PM-JAY से जोड़ता है, जो द्वितीयक और तृतीयक अस्पताल में भर्ती को कवर करती है।"},
  {"id":"eco-sectors-schemes-169","question":"The ABHA number created under the Ayushman Bharat Digital Mission (2021) is:","options":["A card that entitles the holder to free treatment in hospitals","A health ID that links a person’s digital health records","A licence number issued to registered doctors and hospitals","A policy number for the PM-JAY hospitalisation cover"],"answer":1,"explanation":"The Ayushman Bharat Health Account is a unique health ID that lets records from different providers be linked and shared with the person’s consent; it does not itself give insurance or free care.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"आयुष्मान भारत डिजिटल मिशन (2021) के अंतर्गत बनाया गया ABHA नंबर क्या है?","optionsHi":["एक कार्ड जो धारक को अस्पतालों में निःशुल्क इलाज का हकदार बनाता है","एक स्वास्थ्य पहचान पत्र जो व्यक्ति के डिजिटल स्वास्थ्य रिकॉर्ड को जोड़ता है","पंजीकृत डॉक्टरों और अस्पतालों को जारी लाइसेंस संख्या","PM-JAY अस्पताल में भर्ती कवर की पॉलिसी संख्या"],"explanationHi":"आयुष्मान भारत स्वास्थ्य खाता एक विशिष्ट स्वास्थ्य पहचान है जो विभिन्न सेवा प्रदाताओं के रिकॉर्ड को व्यक्ति की सहमति से जोड़ने और साझा करने देती है; यह स्वयं बीमा या निःशुल्क इलाज नहीं देती।"},
  {"id":"eco-sectors-schemes-170","question":"Accredited Social Health Activists (ASHAs), the community health workers in villages, were introduced under:","options":["The ICDS scheme in 1975","The National Urban Health Mission in 2013","Ayushman Bharat in 2018","The National Rural Health Mission in 2005"],"answer":3,"explanation":"NRHM created the ASHA, a trained woman volunteer from the village who links households with the health system. ICDS works through anganwadi workers, a different cadre.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"मान्यता प्राप्त सामाजिक स्वास्थ्य कार्यकर्ता (आशा), जो गाँवों में सामुदायिक स्वास्थ्य कार्यकर्ता हैं, किसके अंतर्गत शुरू की गईं?","optionsHi":["1975 में ICDS योजना","2013 में राष्ट्रीय शहरी स्वास्थ्य मिशन","2018 में आयुष्मान भारत","2005 में राष्ट्रीय ग्रामीण स्वास्थ्य मिशन"],"explanationHi":"NRHM ने आशा का सृजन किया, जो गाँव की एक प्रशिक्षित महिला स्वयंसेविका है और परिवारों को स्वास्थ्य प्रणाली से जोड़ती है। ICDS आँगनवाड़ी कार्यकर्ताओं के माध्यम से काम करती है, जो एक अलग संवर्ग है।"},
  {"id":"eco-sectors-schemes-171","question":"Beneficiaries under the Pradhan Mantri Awaas Yojana – Gramin are selected mainly using:","options":["The BPL lists prepared by the States in the 2002 census of the poor","Households holding Antyodaya ration cards under the NFSA, 2013","Housing deprivation data of SECC 2011, verified by Gram Sabhas","Farmers enrolled for income support under the PM-KISAN scheme"],"answer":2,"explanation":"PMAY-G, which replaced Indira Awaas Yojana in 2016, uses the Socio-Economic and Caste Census 2011 to identify houseless and kutcha-house households, with the list validated by the Gram Sabha.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"प्रधानमंत्री आवास योजना – ग्रामीण के लाभार्थियों का चयन मुख्यतः किसके आधार पर होता है?","optionsHi":["गरीबों की 2002 की गणना में राज्यों द्वारा तैयार BPL सूचियाँ","NFSA, 2013 के अंतर्गत अंत्योदय राशन कार्ड रखने वाले परिवार","SECC 2011 का आवास अभाव डेटा, जिसे ग्राम सभाएँ सत्यापित करती हैं","PM-KISAN योजना के अंतर्गत आय सहायता के लिए नामांकित किसान"],"explanationHi":"2016 में इंदिरा आवास योजना का स्थान लेने वाली PMAY-G, बेघर और कच्चे मकान वाले परिवारों की पहचान के लिए सामाजिक-आर्थिक और जाति जनगणना 2011 का उपयोग करती है, और सूची को ग्राम सभा से मान्य कराया जाता है।"},
  {"id":"eco-sectors-schemes-172","question":"Under the Saansad Adarsh Gram Yojana, launched in 2014, each Member of Parliament:","options":["Gets a separate central fund to build a model village in the constituency","Adopts a gram panchayat and develops it using existing schemes","Must adopt his or her own native village and develop it as a model","Chooses villages that the Planning Commission listed as most backward"],"answer":1,"explanation":"SAGY has no separate allocation; MPs use MPLADS and existing schemes to develop a chosen gram panchayat. They may not choose their own or their spouse’s village.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"2014 में शुरू की गई सांसद आदर्श ग्राम योजना के अंतर्गत प्रत्येक सांसद:","optionsHi":["निर्वाचन क्षेत्र में आदर्श गाँव बनाने के लिए अलग केंद्रीय निधि पाता है","एक ग्राम पंचायत को गोद लेता है और मौजूदा योजनाओं से उसका विकास करता है","अपना पैतृक गाँव अनिवार्य रूप से गोद लेकर उसे आदर्श के रूप में विकसित करता है","योजना आयोग द्वारा सबसे पिछड़े घोषित गाँवों में से चुनाव करता है"],"explanationHi":"SAGY में कोई अलग आवंटन नहीं है; सांसद चुनी गई ग्राम पंचायत के विकास के लिए MPLADS और मौजूदा योजनाओं का उपयोग करते हैं। वे अपना या अपने जीवनसाथी का गाँव नहीं चुन सकते।"},
  {"id":"eco-sectors-schemes-173","question":"The Shyama Prasad Mukherji Rurban Mission (2016) aims to:","options":["Develop clusters of villages with urban-like amenities","Resettle slum dwellers from cities into new rural townships","Build national highways linking district towns to villages","Merge small villages into municipal bodies of nearby towns"],"answer":0,"explanation":"The mission develops ‘Rurban’ clusters, groups of villages with growth potential, providing infrastructure and skills so they can grow without losing their rural character.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"श्यामा प्रसाद मुखर्जी रुर्बन मिशन (2016) का उद्देश्य क्या है?","optionsHi":["गाँवों के ऐसे समूह विकसित करना जिनमें शहरों जैसी सुविधाएँ हों","शहरों की झुग्गी-झोपड़ी के निवासियों को नए ग्रामीण नगरों में बसाना","ज़िला मुख्यालयों को गाँवों से जोड़ने वाले राष्ट्रीय राजमार्ग बनाना","छोटे गाँवों को पास के शहरों की नगर निकायों में मिलाना"],"explanationHi":"मिशन ‘रुर्बन’ समूह विकसित करता है, यानी विकास की संभावना वाले गाँवों के समूह, जिन्हें अवसंरचना और कौशल दिए जाते हैं ताकि वे अपना ग्रामीण स्वरूप खोए बिना आगे बढ़ सकें।"},
  {"id":"eco-sectors-schemes-174","question":"Deen Dayal Upadhyaya Grameen Kaushalya Yojana (2014) is:","options":["A placement-linked skilling scheme for poor rural youth","A crop insurance scheme for tenant farmers in backward districts","A pension scheme for rural artisans aged 60 and above","A scheme for electrifying villages and separating farm feeders"],"answer":0,"explanation":"DDU-GKY, run by the Ministry of Rural Development, trains poor rural youth, mostly aged 15–35, and places them in wage jobs. Village electrification came under the similarly named DDUGJY.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"दीन दयाल उपाध्याय ग्रामीण कौशल्य योजना (2014) क्या है?","optionsHi":["गरीब ग्रामीण युवाओं के लिए नियुक्ति-संबद्ध कौशल योजना","पिछड़े ज़िलों में काश्तकार किसानों के लिए फसल बीमा योजना","60 वर्ष और उससे अधिक आयु के ग्रामीण कारीगरों के लिए पेंशन योजना","गाँवों के विद्युतीकरण और कृषि फीडरों को अलग करने की योजना"],"explanationHi":"ग्रामीण विकास मंत्रालय द्वारा संचालित DDU-GKY गरीब ग्रामीण युवाओं, जिनमें अधिकांश 15–35 वर्ष के हैं, को प्रशिक्षित करती है और उन्हें वेतन वाली नौकरियों में लगाती है। गाँवों का विद्युतीकरण इसी से मिलते-जुलते नाम की DDUGJY के अंतर्गत आया।"},
  {"id":"eco-sectors-schemes-175","question":"Match the scheme with its nodal ministry: A. DDU-GKY  B. DAY-NULM  C. PMKVY  D. PM-SYM; 1. Housing and Urban Affairs  2. Labour and Employment  3. Rural Development  4. Skill Development and Entrepreneurship","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4"],"answer":0,"explanation":"DDU-GKY is a rural development scheme and DAY-NULM its urban counterpart under Housing and Urban Affairs; PMKVY belongs to the Skill Development Ministry and the PM-SYM pension scheme to Labour and Employment.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"योजना का उसके नोडल मंत्रालय से मिलान कीजिए: A. DDU-GKY  B. DAY-NULM  C. PMKVY  D. PM-SYM; 1. आवास और शहरी कार्य  2. श्रम और रोज़गार  3. ग्रामीण विकास  4. कौशल विकास और उद्यमिता","optionsHi":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4"],"explanationHi":"DDU-GKY ग्रामीण विकास की योजना है और DAY-NULM आवास और शहरी कार्य के अंतर्गत उसका शहरी समकक्ष; PMKVY कौशल विकास मंत्रालय की है और PM-SYM पेंशन योजना श्रम और रोज़गार की।"},
  {"id":"eco-sectors-schemes-176","question":"How many of these statements about the Pradhan Mantri Shram Yogi Maan-dhan (PM-SYM) scheme of 2019 are correct? I. Unorganised workers aged 18 to 40 can join. II. The Central Government contributes an amount equal to the worker’s contribution. III. It offers an assured pension of ₹3,000 a month from the age of 60. IV. Members of the EPFO, ESIC or NPS can also join it.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The scheme is meant for workers outside formal social security, so members of EPFO, ESIC or NPS, and income-tax payers, are excluded; IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"2019 की प्रधानमंत्री श्रम योगी मान-धन (PM-SYM) योजना के बारे में इनमें से कितने कथन सही हैं? I. 18 से 40 वर्ष के असंगठित श्रमिक जुड़ सकते हैं। II. केंद्र सरकार श्रमिक के अंशदान के बराबर राशि का योगदान देती है। III. यह 60 वर्ष की आयु से ₹3,000 प्रति माह की सुनिश्चित पेंशन देती है। IV. EPFO, ESIC या NPS के सदस्य भी इसमें जुड़ सकते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। योजना औपचारिक सामाजिक सुरक्षा से बाहर के श्रमिकों के लिए है, इसलिए EPFO, ESIC या NPS के सदस्य और आयकर दाता बाहर हैं; IV गलत है।"},
  {"id":"eco-sectors-schemes-177","question":"Under the definition notified in 2019 for Startup India, an entity is recognised as a startup for up to how many years from incorporation, provided its turnover has not exceeded ₹100 crore in any year?","options":["5 years","7 years","15 years","10 years"],"answer":3,"explanation":"DPIIT’s 2019 notification raised the age limit to 10 years and the turnover limit to ₹100 crore; the entity must also be working on innovation or a scalable business model.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"स्टार्टअप इंडिया के लिए 2019 में अधिसूचित परिभाषा के अंतर्गत, कोई इकाई निगमन से अधिकतम कितने वर्षों तक स्टार्टअप के रूप में मान्य होती है, बशर्ते उसका टर्नओवर किसी वर्ष ₹100 करोड़ से अधिक न हुआ हो?","optionsHi":["5 वर्ष","7 वर्ष","15 वर्ष","10 वर्ष"],"explanationHi":"DPIIT की 2019 की अधिसूचना ने आयु सीमा 10 वर्ष और टर्नओवर सीमा ₹100 करोड़ कर दी; इकाई को नवाचार या मापनीय व्यावसायिक मॉडल पर भी काम करना चाहिए।"},
  {"id":"eco-sectors-schemes-178","question":"The Fund of Funds for Startups (2016) supports startups by:","options":["Lending directly to startups at concessional rates through banks","Investing in SEBI-registered AIFs, which then invest in startups","Buying shares of startups that are listed on the SME exchanges","Guaranteeing working capital loans given by NBFCs to startups"],"answer":1,"explanation":"The fund, managed by SIDBI, does not invest in startups directly; it commits capital to SEBI-registered AIFs, which then invest in startups, drawing in private money.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"स्टार्टअप्स के लिए फंड ऑफ फंड्स (2016) स्टार्टअप की सहायता कैसे करता है?","optionsHi":["बैंकों के माध्यम से रियायती दरों पर स्टार्टअप्स को सीधे ऋण देकर","SEBI-पंजीकृत AIF में निवेश करके, जो फिर स्टार्टअप्स में निवेश करते हैं","SME एक्सचेंजों पर सूचीबद्ध स्टार्टअप्स के शेयर खरीदकर","NBFC द्वारा स्टार्टअप्स को दिए गए कार्यशील पूंजी ऋणों की गारंटी देकर"],"explanationHi":"SIDBI द्वारा प्रबंधित यह कोष स्टार्टअप्स में सीधे निवेश नहीं करता; यह SEBI-पंजीकृत AIF को पूंजी देता है, जो फिर स्टार्टअप्स में निवेश करते हैं, और निजी धन भी आकर्षित होता है।"},
  {"id":"eco-sectors-schemes-179","question":"Atal Tinkering Labs, which give school students space and tools to build and experiment, are set up under:","options":["Atal Innovation Mission of NITI Aayog","Samagra Shiksha of the Education Ministry","Digital India of the IT Ministry","Startup India of DPIIT"],"answer":0,"explanation":"The Atal Innovation Mission, set up by NITI Aayog in 2016, runs Atal Tinkering Labs in schools and Atal Incubation Centres to build a culture of innovation.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"अटल टिंकरिंग लैब, जो स्कूली छात्रों को निर्माण और प्रयोग के लिए स्थान और उपकरण देती हैं, किसके अंतर्गत स्थापित की जाती हैं?","optionsHi":["नीति आयोग का अटल नवाचार मिशन","शिक्षा मंत्रालय की समग्र शिक्षा","IT मंत्रालय का डिजिटल इंडिया","DPIIT का स्टार्टअप इंडिया"],"explanationHi":"नीति आयोग द्वारा 2016 में स्थापित अटल नवाचार मिशन स्कूलों में अटल टिंकरिंग लैब और नवाचार की संस्कृति बनाने के लिए अटल इन्क्यूबेशन केंद्र चलाता है।"},
  {"id":"eco-sectors-schemes-180","question":"The Delhi–Mumbai Industrial Corridor was planned along which piece of transport infrastructure?","options":["The Golden Quadrilateral national highway","The Western Dedicated Freight Corridor","The Mumbai–Ahmedabad high-speed rail line","The Sagarmala chain of coastal ports"],"answer":1,"explanation":"DMIC was conceived in the late 2000s around the high-capacity Western Dedicated Freight Corridor between Dadri and JNPT, with new industrial cities along it. The Golden Quadrilateral and the high-speed rail line are separate projects, and Sagarmala is a port programme.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"दिल्ली–मुंबई औद्योगिक गलियारे की योजना परिवहन अवसंरचना के किस भाग के साथ-साथ बनाई गई थी?","optionsHi":["स्वर्णिम चतुर्भुज राष्ट्रीय राजमार्ग","पश्चिमी समर्पित माल गलियारा","मुंबई–अहमदाबाद हाई-स्पीड रेल लाइन","सागरमाला तटीय बंदरगाह श्रृंखला"],"explanationHi":"DMIC की परिकल्पना 2000 के दशक के अंत में दादरी और JNPT के बीच उच्च क्षमता वाले पश्चिमी समर्पित माल गलियारे के इर्द-गिर्द की गई थी, जिसके साथ-साथ नए औद्योगिक नगर बनने थे। स्वर्णिम चतुर्भुज और हाई-स्पीड रेल अलग परियोजनाएँ हैं, और सागरमाला बंदरगाह कार्यक्रम है।"},
  {"id":"eco-sectors-schemes-181","question":"The Western Dedicated Freight Corridor runs between:","options":["Ludhiana and Dankuni via Sonnagar","Sonnagar and Dankuni in the east","Delhi and Kandla Port in Gujarat","Dadri and Jawaharlal Nehru Port"],"answer":3,"explanation":"The Western DFC links Dadri in Uttar Pradesh with JNPT near Mumbai; the Eastern DFC links Ludhiana with Sonnagar, with an extension planned to Dankuni.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"पश्चिमी समर्पित माल गलियारा किनके बीच चलता है?","optionsHi":["सोननगर के रास्ते लुधियाना और दानकुनी","पूर्व में सोननगर और दानकुनी","दिल्ली और गुजरात में कांडला बंदरगाह","दादरी और जवाहरलाल नेहरू बंदरगाह"],"explanationHi":"पश्चिमी DFC उत्तर प्रदेश के दादरी को मुंबई के पास JNPT से जोड़ता है; पूर्वी DFC लुधियाना को सोननगर से जोड़ता है, जिसका दानकुनी तक विस्तार प्रस्तावित है।"},
  {"id":"eco-sectors-schemes-182","question":"Under the UDAN regional connectivity scheme (2016), fares on routes to unserved airports are kept low mainly by:","options":["Fixing the fares of all seats on every domestic flight in India","Capping fares on some seats and giving viability gap funding","Exempting the airlines on these routes from all taxes and fees","Running these flights only through the public sector Air India"],"answer":1,"explanation":"Airlines bid for routes, cap fares on a share of seats and receive viability gap funding from the Centre, States and airport operators, part of it financed by a levy on other domestic flights.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"UDAN क्षेत्रीय संपर्कता योजना (2016) के अंतर्गत, असेवित हवाई अड्डों के मार्गों पर किराए मुख्यतः कैसे कम रखे जाते हैं?","optionsHi":["भारत की हर घरेलू उड़ान की सभी सीटों के किराए तय करके","कुछ सीटों पर किराया सीमित करके और व्यवहार्यता अंतर वित्तपोषण देकर","इन मार्गों की एयरलाइनों को सभी करों और शुल्कों से छूट देकर","इन उड़ानों को केवल सार्वजनिक क्षेत्र की एयर इंडिया से चलवाकर"],"explanationHi":"एयरलाइनें मार्गों के लिए बोली लगाती हैं, सीटों के एक हिस्से पर किराया सीमित करती हैं और केंद्र, राज्यों तथा हवाई अड्डा संचालकों से व्यवहार्यता अंतर वित्तपोषण पाती हैं, जिसका एक भाग अन्य घरेलू उड़ानों पर लगे शुल्क से जुटाया जाता है।"},
  {"id":"eco-sectors-schemes-183","question":"The UJALA scheme, implemented by Energy Efficiency Services Limited from 2015, mainly involved:","options":["Distributing LED bulbs to households at low prices","Installing solar pumps on farms with central subsidy","Providing free electricity connections to poor homes","Separating farm feeders from rural household feeders"],"answer":0,"explanation":"UJALA used bulk procurement to cut LED prices and sold them to households, saving power and reducing peak demand. Free connections came under Saubhagya and solar pumps under PM-KUSUM.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"2015 से एनर्जी एफिशिएंसी सर्विसेज लिमिटेड द्वारा क्रियान्वित उजाला योजना में मुख्यतः क्या शामिल था?","optionsHi":["परिवारों को कम कीमत पर LED बल्ब बाँटना","केंद्रीय सब्सिडी से खेतों में सौर पंप लगाना","गरीब घरों को निःशुल्क बिजली कनेक्शन देना","कृषि फीडरों को ग्रामीण घरेलू फीडरों से अलग करना"],"explanationHi":"उजाला ने थोक खरीद से LED की कीमतें घटाईं और उन्हें परिवारों को बेचा, जिससे बिजली की बचत और अधिकतम मांग में कमी हुई। निःशुल्क कनेक्शन सौभाग्य के अंतर्गत और सौर पंप PM-KUSUM के अंतर्गत आए।"},
  {"id":"eco-sectors-schemes-184","question":"Under the UDAY scheme of 2015 to revive power distribution companies, States were to take over what share of their discoms’ debt as on 30 September 2015?","options":["50%","75%","25%","100%"],"answer":1,"explanation":"States were to absorb 75% of discom debt over two years (50% in 2015–16 and 25% in 2016–17), while discoms committed to cut losses and close the gap between cost and revenue.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"बिजली वितरण कंपनियों को पुनर्जीवित करने की 2015 की उदय (UDAY) योजना के अंतर्गत, राज्यों को 30 सितंबर 2015 की स्थिति में अपनी डिस्कॉम के ऋण का कितना हिस्सा अपने ऊपर लेना था?","optionsHi":["50%","75%","25%","100%"],"explanationHi":"राज्यों को दो वर्षों में डिस्कॉम ऋण का 75% (2015–16 में 50% और 2016–17 में 25%) अपने ऊपर लेना था, जबकि डिस्कॉम ने घाटे घटाने और लागत तथा राजस्व के अंतर को पाटने का वचन दिया।"},
  {"id":"eco-sectors-schemes-185","question":"Which scheme, launched in 2017, aimed at giving electricity connections to all remaining households in rural and urban areas?","options":["Deen Dayal Upadhyaya Gram Jyoti Yojana (DDUGJY)","Ujwal DISCOM Assurance Yojana (UDAY)","Integrated Power Development Scheme (IPDS)","Sahaj Bijli Har Ghar Yojana (Saubhagya)"],"answer":3,"explanation":"Saubhagya targeted last-mile household connections. DDUGJY (2014) focused on village electrification and feeder separation, UDAY on discom finances and IPDS on urban networks.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"2017 में शुरू की गई कौन-सी योजना ग्रामीण और शहरी क्षेत्रों के सभी शेष परिवारों को बिजली कनेक्शन देने के लिए थी?","optionsHi":["दीन दयाल उपाध्याय ग्राम ज्योति योजना (DDUGJY)","उज्ज्वल डिस्कॉम आश्वासन योजना (UDAY)","एकीकृत विद्युत विकास योजना (IPDS)","सहज बिजली हर घर योजना (सौभाग्य)"],"explanationHi":"सौभाग्य ने अंतिम छोर के घरेलू कनेक्शनों को लक्षित किया। DDUGJY (2014) गाँवों के विद्युतीकरण और फीडर पृथक्करण पर, UDAY डिस्कॉम की वित्तीय स्थिति पर और IPDS शहरी नेटवर्क पर केंद्रित थी।"},
  {"id":"eco-sectors-schemes-186","question":"Match the PM-KUSUM component with its purpose: A. Component A  B. Component B  C. Component C; 1. Solarising existing grid-connected farm pumps  2. Small solar or other renewable power plants on barren or fallow land  3. Standalone off-grid solar pumps","options":["A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2","A-2, B-3, C-1"],"answer":3,"explanation":"Component A sets up decentralised grid-connected plants on farmers’ land, B gives standalone solar pumps where there is no grid, and C solarises existing grid-connected pumps so farmers can sell surplus power.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"PM-KUSUM के घटक का उसके उद्देश्य से मिलान कीजिए: A. घटक A  B. घटक B  C. घटक C; 1. ग्रिड से जुड़े मौजूदा कृषि पंपों का सौरीकरण  2. बंजर या परती भूमि पर छोटे सौर या अन्य नवीकरणीय ऊर्जा संयंत्र  3. स्वतंत्र, ऑफ-ग्रिड सौर पंप","optionsHi":["A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2","A-2, B-3, C-1"],"explanationHi":"घटक A किसानों की भूमि पर विकेंद्रीकृत ग्रिड-जुड़े संयंत्र लगाता है, B जहाँ ग्रिड नहीं है वहाँ स्वतंत्र सौर पंप देता है, और C मौजूदा ग्रिड-जुड़े पंपों का सौरीकरण करता है ताकि किसान अधिशेष बिजली बेच सकें।"},
  {"id":"eco-sectors-schemes-187","question":"The Lead Bank Scheme, introduced in 1969, under which one bank coordinates credit planning in each district, grew out of the recommendations of:","options":["The Narasimham Working Group and the Shivaraman Committee","The Gadgil Study Group and the Nariman Committee","The Khusro Committee and the Rangarajan Committee","The Tandon Committee and the Chore Committee"],"answer":1,"explanation":"The Gadgil Study Group proposed an ‘area approach’ to bank lending and the Nariman Committee suggested that each district be allotted to a lead bank. Narasimham’s 1975 group led to the RRBs.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"1969 में शुरू की गई अग्रणी बैंक योजना, जिसके अंतर्गत एक बैंक प्रत्येक ज़िले में ऋण नियोजन का समन्वय करता है, किनकी सिफारिशों से निकली थी?","optionsHi":["नरसिम्हम कार्य समूह और शिवरामन समिति","गाडगिल अध्ययन समूह और नरीमन समिति","खुसरो समिति और रंगराजन समिति","टंडन समिति और चोर समिति"],"explanationHi":"गाडगिल अध्ययन समूह ने बैंक ऋण के लिए ‘क्षेत्र दृष्टिकोण’ प्रस्तावित किया और नरीमन समिति ने सुझाया कि प्रत्येक ज़िला एक अग्रणी बैंक को सौंपा जाए। नरसिम्हम के 1975 के समूह से RRB बने।"},
  {"id":"eco-sectors-schemes-188","question":"Regional Rural Banks were first set up in 1975 on the recommendation of the:","options":["Narasimham Working Group","Khusro Committee on Agricultural Credit","Rangarajan Committee","Venkatachalam Committee"],"answer":0,"explanation":"The 1975 Working Group on Rural Banks under M. Narasimham recommended RRBs to combine local feel with commercial bank organisation; the first RRBs began in October 1975 and the RRB Act followed in 1976.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"क्षेत्रीय ग्रामीण बैंक पहली बार 1975 में किसकी सिफारिश पर स्थापित किए गए?","optionsHi":["नरसिम्हम कार्य समूह","कृषि ऋण पर खुसरो समिति","रंगराजन समिति","वेंकटचलम समिति"],"explanationHi":"एम. नरसिम्हम की अध्यक्षता वाले ग्रामीण बैंकों पर 1975 के कार्य समूह ने स्थानीय समझ को वाणिज्यिक बैंक संगठन से जोड़ने के लिए RRB की सिफारिश की; पहले RRB अक्टूबर 1975 में शुरू हुए और RRB अधिनियम 1976 में आया।"},
  {"id":"eco-sectors-schemes-189","question":"NABARD was set up in 1982 on the recommendation of a committee (CRAFICARD) appointed by the RBI and chaired by:","options":["M. Narasimham","A. M. Khusro","B. Sivaraman","C. Rangarajan"],"answer":2,"explanation":"The Committee to Review Arrangements for Institutional Credit for Agriculture and Rural Development, under B. Sivaraman, recommended an apex development bank, and NABARD took over the RBI’s agricultural credit functions.","difficulty":"hard","source":"RBI Grade B","questionHi":"NABARD की स्थापना 1982 में RBI द्वारा नियुक्त और किसकी अध्यक्षता वाली एक समिति (CRAFICARD) की सिफारिश पर हुई?","optionsHi":["एम. नरसिम्हम","ए. एम. खुसरो","बी. शिवरामन","सी. रंगराजन"],"explanationHi":"कृषि और ग्रामीण विकास के लिए संस्थागत ऋण व्यवस्थाओं की समीक्षा समिति ने, बी. शिवरामन की अध्यक्षता में, एक शीर्ष विकास बैंक की सिफारिश की, और NABARD ने RBI के कृषि ऋण कार्य संभाल लिए।"},
  {"id":"eco-sectors-schemes-190","question":"For domestic scheduled commercial banks, the overall priority sector lending target, as a share of adjusted net bank credit (or credit equivalent of off-balance-sheet exposure, whichever is higher), is:","options":["18%","32%","75%","40%"],"answer":3,"explanation":"Domestic commercial banks must lend 40% of ANBC to the priority sector, within which agriculture has an 18% sub-target. Regional Rural Banks have a higher overall target of 75%.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"घरेलू अनुसूचित वाणिज्यिक बैंकों के लिए, समायोजित निवल बैंक ऋण (या तुलन-पत्र से बाहर जोखिम के ऋण-समतुल्य, जो भी अधिक हो) के हिस्से के रूप में समग्र प्राथमिकता क्षेत्र ऋण लक्ष्य कितना है?","optionsHi":["18%","32%","75%","40%"],"explanationHi":"घरेलू वाणिज्यिक बैंकों को ANBC का 40% प्राथमिकता क्षेत्र को देना होता है, जिसके भीतर कृषि का उप-लक्ष्य 18% है। क्षेत्रीय ग्रामीण बैंकों का समग्र लक्ष्य अधिक, 75%, है।"},
  {"id":"eco-sectors-schemes-191","question":"Priority Sector Lending Certificates (PSLCs), introduced by the RBI in 2016, allow a bank that has exceeded its priority sector targets to:","options":["Sell the underlying loans outright to a bank that has fallen short","Convert its surplus priority loans into tax-free infrastructure bonds","Sell its surplus achievement to a short bank while keeping the loans","Carry the surplus forward to meet its targets over the next five years"],"answer":2,"explanation":"A PSLC trades only the priority sector ‘achievement’: the buyer counts it towards its target while the loans and their credit risk stay with the seller. This rewards banks good at such lending.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"2016 में RBI द्वारा शुरू किए गए प्राथमिकता क्षेत्र ऋण प्रमाणपत्र (PSLC) उस बैंक को, जिसने अपने प्राथमिकता क्षेत्र लक्ष्य पार कर लिए हों, क्या करने देते हैं?","optionsHi":["कमी वाले बैंक को अंतर्निहित ऋण सीधे बेच देना","अपने अधिशेष प्राथमिकता ऋणों को कर-मुक्त अवसंरचना बॉन्ड में बदलना","अपनी अधिशेष उपलब्धि कमी वाले बैंक को बेचना, जबकि ऋण अपने पास रखना","अधिशेष को आगे ले जाकर अगले पाँच वर्षों में अपने लक्ष्य पूरे करना"],"explanationHi":"PSLC केवल प्राथमिकता क्षेत्र की ‘उपलब्धि’ का व्यापार करता है: क्रेता इसे अपने लक्ष्य में गिनता है, जबकि ऋण और उनका ऋण-जोखिम विक्रेता के पास रहता है। इससे ऐसे ऋण देने में कुशल बैंकों को पुरस्कार मिलता है।"},
  {"id":"eco-sectors-schemes-192","question":"In 2018–19, the Kisan Credit Card facility was extended to:","options":["Farmers engaged in animal husbandry and fisheries","Tenant farmers in the North-Eastern States only","Agricultural labourers without any land","Farmer producer companies with large annual turnover"],"answer":0,"explanation":"The KCC, introduced in 1998 for crop loans, was extended to the working capital needs of farmers in animal husbandry and fisheries, recognising that many farm households depend on livestock and fish.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"2018–19 में किसान क्रेडिट कार्ड सुविधा का विस्तार किन तक किया गया?","optionsHi":["पशुपालन और मत्स्य पालन में लगे किसान","केवल पूर्वोत्तर राज्यों के काश्तकार किसान","बिना किसी भूमि के खेतिहर मज़दूर","बड़े वार्षिक टर्नओवर वाली किसान उत्पादक कंपनियाँ"],"explanationHi":"1998 में फसल ऋण के लिए शुरू हुए KCC का विस्तार पशुपालन और मत्स्य पालन में लगे किसानों की कार्यशील पूंजी ज़रूरतों तक किया गया, यह मानते हुए कि अनेक किसान परिवार पशुधन और मछली पर निर्भर हैं।"},
  {"id":"eco-sectors-schemes-193","question":"Under the Modified Interest Subvention Scheme, short-term crop loans of up to ₹3 lakh are given at 7% a year. What effective rate does a farmer who repays promptly pay?","options":["5.5%","3%","4%","7%"],"answer":2,"explanation":"Banks lend at 7% with interest subvention from the Centre, and farmers who repay on time get a further 3% prompt repayment incentive, so their effective rate is 4%.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"संशोधित ब्याज सहायता योजना के अंतर्गत ₹3 लाख तक के अल्पकालिक फसल ऋण 7% प्रति वर्ष पर दिए जाते हैं। समय पर चुकाने वाला किसान प्रभावी रूप से कितनी दर चुकाता है?","optionsHi":["5.5%","3%","4%","7%"],"explanationHi":"बैंक केंद्र से ब्याज सहायता के साथ 7% पर ऋण देते हैं, और समय पर चुकाने वाले किसानों को 3% का और शीघ्र भुगतान प्रोत्साहन मिलता है, इसलिए उनकी प्रभावी दर 4% है।"},
  {"id":"eco-sectors-schemes-194","question":"Under the traditional APMC system, a farmer generally had to sell notified produce:","options":["Directly to the Food Corporation of India at the minimum support price","To any buyer anywhere in the country through an online trading platform","Only to registered cooperatives at prices fixed by the State government","At regulated market yards via licensed traders and commission agents"],"answer":3,"explanation":"State APMC Acts required notified produce to be traded in regulated market yards, with licensed traders and commission agents. This curbed exploitation but also fragmented markets, which e-NAM and model Acts tried to fix.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"पारंपरिक APMC प्रणाली के अंतर्गत किसान को सामान्यतः अधिसूचित उपज कहाँ बेचनी होती थी?","optionsHi":["न्यूनतम समर्थन मूल्य पर सीधे भारतीय खाद्य निगम को","ऑनलाइन व्यापार मंच के माध्यम से देश में कहीं भी किसी भी क्रेता को","केवल पंजीकृत सहकारी समितियों को, राज्य सरकार द्वारा तय कीमतों पर","लाइसेंस प्राप्त व्यापारियों और कमीशन एजेंटों के माध्यम से विनियमित मंडी प्रांगणों में"],"explanationHi":"राज्य APMC अधिनियमों में अधिसूचित उपज का व्यापार लाइसेंस प्राप्त व्यापारियों और कमीशन एजेंटों के साथ विनियमित मंडी प्रांगणों में अनिवार्य था। इससे शोषण घटा, पर बाज़ार बँटे भी, जिन्हें e-NAM और मॉडल अधिनियमों ने सुधारना चाहा।"},
  {"id":"eco-sectors-schemes-195","question":"The central scheme launched in 2020 for forming and promoting Farmer Producer Organisations set a target of how many new FPOs?","options":["1,000","5,000","10,000","50,000"],"answer":2,"explanation":"The scheme for 10,000 new FPOs gives them handholding support for five years, an equity grant and credit guarantee, so that small farmers can gain bargaining power by pooling produce.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"2020 में किसान उत्पादक संगठनों के गठन और संवर्धन के लिए शुरू की गई केंद्रीय योजना ने कितने नए FPO का लक्ष्य रखा?","optionsHi":["1,000","5,000","10,000","50,000"],"explanationHi":"10,000 नए FPO की यह योजना उन्हें पाँच वर्ष तक सहयोग, इक्विटी अनुदान और ऋण गारंटी देती है, ताकि छोटे किसान उपज को एकत्र कर सौदेबाज़ी की शक्ति पा सकें।"},
  {"id":"eco-sectors-schemes-196","question":"Negotiable warehouse receipts issued by warehouses registered with the WDRA help farmers mainly by:","options":["Guaranteeing that the government will buy the stored produce at the MSP","Exempting the stored produce from GST until it is finally sold to a buyer","Letting them pledge stored produce for loans, not sell at harvest","Allowing them to export the stored produce without any export licence"],"answer":2,"explanation":"Under the Warehousing (Development and Regulation) Act, 2007, a negotiable receipt can be used as collateral or transferred, so farmers get credit against stored grain and can wait for better prices.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"WDRA के साथ पंजीकृत गोदामों द्वारा जारी परक्राम्य गोदाम रसीदें किसानों की मुख्यतः कैसे मदद करती हैं?","optionsHi":["यह गारंटी देकर कि सरकार भंडारित उपज MSP पर खरीदेगी","भंडारित उपज को अंतिम रूप से क्रेता को बिकने तक GST से छूट देकर","उन्हें कटाई के समय बेचने के बजाय भंडारित उपज गिरवी रखकर ऋण लेने देकर","उन्हें बिना निर्यात लाइसेंस के भंडारित उपज निर्यात करने देकर"],"explanationHi":"गोदाम (विकास और विनियमन) अधिनियम, 2007 के अंतर्गत परक्राम्य रसीद को संपार्श्विक के रूप में उपयोग या हस्तांतरित किया जा सकता है, इसलिए किसान भंडारित अनाज के बदले ऋण पाते हैं और बेहतर कीमतों की प्रतीक्षा कर सकते हैं।"},
  {"id":"eco-sectors-schemes-197","question":"The Food Corporation of India was set up in 1965 under:","options":["A resolution of the Union Cabinet","The Food Corporations Act, 1964","The Essential Commodities Act, 1955","The Companies Act, 1956"],"answer":1,"explanation":"FCI is a statutory body created under the Food Corporations Act, 1964, to procure, store and distribute foodgrains and maintain buffer stocks. The Agricultural Prices Commission was set up the same year.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"भारतीय खाद्य निगम की स्थापना 1965 में किसके अंतर्गत हुई?","optionsHi":["केंद्रीय मंत्रिमंडल का एक संकल्प","खाद्य निगम अधिनियम, 1964","आवश्यक वस्तु अधिनियम, 1955","कंपनी अधिनियम, 1956"],"explanationHi":"FCI खाद्य निगम अधिनियम, 1964 के अंतर्गत बना एक सांविधिक निकाय है, जो खाद्यान्न की खरीद, भंडारण और वितरण करता है तथा बफर स्टॉक रखता है। कृषि मूल्य आयोग उसी वर्ष स्थापित हुआ।"},
  {"id":"eco-sectors-schemes-198","question":"The Pradhan Mantri Matsya Sampada Yojana, launched in 2020, is aimed at the development of:","options":["Fisheries and aquaculture","Dairy and animal husbandry","Horticulture and floriculture","Sericulture and apiculture"],"answer":0,"explanation":"PMMSY is a flagship scheme of the Department of Fisheries to raise fish production, modernise the value chain and improve the welfare of fishers, a key part of the ‘Blue Revolution’.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"2020 में शुरू की गई प्रधानमंत्री मत्स्य संपदा योजना किसके विकास के लिए है?","optionsHi":["मत्स्य पालन और जलीय कृषि","डेयरी और पशुपालन","बागवानी और पुष्प-कृषि","रेशम कीट पालन और मधुमक्खी पालन"],"explanationHi":"PMMSY मत्स्य पालन विभाग की प्रमुख योजना है, जो मछली उत्पादन बढ़ाने, मूल्य शृंखला के आधुनिकीकरण और मछुआरों के कल्याण को सुधारने के लिए है; यह ‘नीली क्रांति’ का महत्वपूर्ण भाग है।"},
  {"id":"eco-sectors-schemes-199","question":"The Rashtriya Gokul Mission, launched in 2014, focuses on:","options":["Raising milk output through imported exotic cattle breeds","Conserving and improving indigenous bovine breeds","Building milk-chilling plants for village dairy cooperatives","Insuring cattle owners against loss from disease"],"answer":1,"explanation":"The mission promotes the development and conservation of indigenous cattle and buffalo breeds through breeding programmes, artificial insemination and Gokul Grams.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"2014 में शुरू किया गया राष्ट्रीय गोकुल मिशन किस पर केंद्रित है?","optionsHi":["आयातित विदेशी नस्ल के पशुओं से दूध उत्पादन बढ़ाना","देशी गोवंशीय नस्लों का संरक्षण और सुधार","ग्रामीण डेयरी सहकारी समितियों के लिए दूध शीतलन संयंत्र बनाना","पशु मालिकों का रोग से हुई हानि के विरुद्ध बीमा करना"],"explanationHi":"मिशन प्रजनन कार्यक्रमों, कृत्रिम गर्भाधान और गोकुल ग्रामों के माध्यम से देशी गाय और भैंस नस्लों के विकास और संरक्षण को बढ़ावा देता है।"},
  {"id":"eco-sectors-schemes-200","question":"Operation Barga, launched in West Bengal in 1978, was mainly about:","options":["Distributing surplus land acquired under the land ceiling laws","Recording sharecroppers to secure their tenancy rights","Consolidating scattered holdings into compact plots for each farmer","Settling landless families on forest land as cultivators"],"answer":1,"explanation":"Operation Barga registered bargadars (sharecroppers) in the land records, giving them security of tenancy and a legal share of the crop; it was a tenancy reform rather than land redistribution.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"1978 में पश्चिम बंगाल में शुरू किया गया ऑपरेशन बर्गा मुख्यतः किस बारे में था?","optionsHi":["भूमि सीमा कानूनों के अंतर्गत अधिगृहीत अधिशेष भूमि का वितरण","बटाईदारों का पंजीकरण कर उनके काश्तकारी अधिकारों को सुरक्षित करना","बिखरी जोतों को प्रत्येक किसान के लिए सघन भूखंडों में समेकित करना","भूमिहीन परिवारों को वन भूमि पर खेतिहर के रूप में बसाना"],"explanationHi":"ऑपरेशन बर्गा ने बर्गादारों (बटाईदारों) को भूमि अभिलेखों में दर्ज किया, जिससे उन्हें काश्तकारी की सुरक्षा और फसल में कानूनी हिस्सा मिला; यह भूमि पुनर्वितरण नहीं, बल्कि काश्तकारी सुधार था।"},
  {"id":"eco-sectors-schemes-201","question":"The Bhoodan movement, in which landowners were asked to donate land for the landless, was started in 1951 by:","options":["Jayaprakash Narayan","Vinoba Bhave","Ram Manohar Lohia","Acharya Kripalani"],"answer":1,"explanation":"Vinoba Bhave began Bhoodan at Pochampally in present-day Telangana in 1951, and it later grew into Gramdan; Jayaprakash Narayan joined and supported the movement.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"भूदान आंदोलन, जिसमें भूस्वामियों से भूमिहीनों के लिए भूमि दान करने को कहा गया, 1951 में किसने शुरू किया?","optionsHi":["जयप्रकाश नारायण","विनोबा भावे","राम मनोहर लोहिया","आचार्य कृपलानी"],"explanationHi":"विनोबा भावे ने 1951 में वर्तमान तेलंगाना के पोचमपल्ली में भूदान शुरू किया, जो बाद में ग्रामदान में विकसित हुआ; जयप्रकाश नारायण आंदोलन से जुड़े और उसका समर्थन किया।"},
  {"id":"eco-sectors-schemes-202","question":"‘Baumol’s cost disease’ explains why:","options":["Manufacturing costs rise faster than service costs as the economy grows richer over time","Farm costs fall as mechanisation spreads, pushing surplus labour from villages into cities","Public sector costs fall steadily when services are outsourced to private firms","Costs of services like teaching rise, as productivity lags but wages keep pace"],"answer":3,"explanation":"In services like education, health care and live arts, output per worker grows little, but wages must keep up with high-productivity sectors, so their relative cost and share of spending rise.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"‘बाउमोल का लागत रोग’ किसकी व्याख्या करता है?","optionsHi":["अर्थव्यवस्था के समृद्ध होने पर विनिर्माण लागतें सेवा लागतों से तेज़ क्यों बढ़ती हैं","यंत्रीकरण फैलने पर कृषि लागतें क्यों घटती हैं, जिससे अधिशेष श्रम गाँवों से शहरों में जाता है","सेवाएँ निजी फर्मों को आउटसोर्स होने पर सार्वजनिक क्षेत्र की लागतें लगातार क्यों घटती हैं","शिक्षण जैसी सेवाओं की लागत क्यों बढ़ती है, जबकि उत्पादकता पिछड़ती है पर मज़दूरी साथ-साथ बढ़ती है"],"explanationHi":"शिक्षा, स्वास्थ्य सेवा और मंचीय कलाओं जैसी सेवाओं में प्रति श्रमिक उत्पादन बहुत कम बढ़ता है, पर मज़दूरी को उच्च उत्पादकता वाले क्षेत्रों के साथ चलना पड़ता है, इसलिए उनकी सापेक्ष लागत और व्यय में हिस्सा बढ़ता है।"},
  {"id":"eco-sectors-schemes-203","question":"‘Premature deindustrialisation’, a term linked with Dani Rodrik, describes economies in which:","options":["Manufacturing’s share peaks at far lower incomes than for early industrialisers","Manufacturing grows faster than services before the economy reaches middle income","Governments close loss-making state factories before they privatise the rest of them","Agriculture’s share of employment falls before its share of national output does"],"answer":0,"explanation":"Many developing countries, India among the cases discussed, are moving into services while manufacturing’s share is still small and incomes are low, unlike the path of the early industrialisers.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"‘समय-पूर्व विऔद्योगीकरण’, जो डैनी रॉड्रिक से जुड़ा शब्द है, किन अर्थव्यवस्थाओं का वर्णन करता है?","optionsHi":["जिनमें विनिर्माण का हिस्सा शुरुआती औद्योगीकरण करने वालों की तुलना में कहीं कम आय पर शिखर पर पहुँच जाता है","जिनमें मध्यम आय तक पहुँचने से पहले विनिर्माण सेवाओं से तेज़ बढ़ता है","जिनमें सरकारें शेष का निजीकरण करने से पहले घाटे वाले सरकारी कारखाने बंद करती हैं","जिनमें कृषि का रोज़गार में हिस्सा उसके राष्ट्रीय उत्पादन में हिस्से से पहले गिरता है"],"explanationHi":"अनेक विकासशील देश, जिनमें भारत भी चर्चित उदाहरणों में है, तब सेवाओं की ओर बढ़ रहे हैं जब विनिर्माण का हिस्सा अब भी छोटा और आय कम है, जो शुरुआती औद्योगीकरण करने वालों के मार्ग से भिन्न है।"},
  {"id":"eco-sectors-schemes-204","question":"‘Dutch disease’ refers to a situation in which:","options":["A resource-export boom lifts the real exchange rate and hurts manufacturing","A country’s farm sector shrinks because of repeated floods and rising sea levels","High import tariffs protect domestic manufacturing but raise prices for consumers","An outflow of skilled workers lowers productivity in the country’s service sector"],"answer":0,"explanation":"The term comes from the Netherlands after its gas discoveries: resource exports and inflows push up the currency and wages, making manufacturing and other exports less competitive.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"‘डच रोग’ किस स्थिति को कहते हैं?","optionsHi":["संसाधन-निर्यात में तेज़ी जो वास्तविक विनिमय दर बढ़ाकर विनिर्माण को हानि पहुँचाती है","बार-बार की बाढ़ और बढ़ते समुद्र स्तर के कारण किसी देश के कृषि क्षेत्र का सिकुड़ना","ऊँचे आयात शुल्क जो घरेलू विनिर्माण की रक्षा करते हैं पर उपभोक्ताओं के लिए कीमतें बढ़ाते हैं","कुशल श्रमिकों का बाहर जाना जो देश के सेवा क्षेत्र की उत्पादकता घटाता है"],"explanationHi":"यह शब्द नीदरलैंड से आया, जहाँ गैस की खोज के बाद संसाधन निर्यात और आवक ने मुद्रा और मज़दूरी बढ़ा दी, जिससे विनिर्माण और अन्य निर्यात कम प्रतिस्पर्धी हो गए।"},
  {"id":"eco-sectors-schemes-205","question":"Albert Hirschman’s strategy of ‘unbalanced growth’ favoured putting scarce investment into industries that:","options":["Need the least amount of capital per worker employed","Have the strongest backward and forward linkages","Earn the most foreign exchange in the short run","Serve the largest number of final consumers"],"answer":1,"explanation":"Hirschman argued that investing in key sectors with strong linkages creates shortages and pressures that induce investment elsewhere. Nurkse, by contrast, argued for balanced growth across many sectors at once.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"अल्बर्ट हिर्शमैन की ‘असंतुलित वृद्धि’ की रणनीति दुर्लभ निवेश को किन उद्योगों में लगाने के पक्ष में थी?","optionsHi":["जिनमें प्रति नियोजित श्रमिक सबसे कम पूंजी लगती हो","जिनके पश्च और अग्र संबंध सबसे मज़बूत हों","जो अल्पकाल में सबसे अधिक विदेशी मुद्रा कमाते हों","जो सबसे अधिक अंतिम उपभोक्ताओं की सेवा करते हों"],"explanationHi":"हिर्शमैन का तर्क था कि मज़बूत संबंधों वाले प्रमुख क्षेत्रों में निवेश ऐसी कमियाँ और दबाव पैदा करता है जो अन्यत्र निवेश को प्रेरित करते हैं। इसके विपरीत नर्क्से ने एक साथ अनेक क्षेत्रों में संतुलित वृद्धि का तर्क दिया।"},
  {"id":"eco-sectors-schemes-206","question":"Rosenstein-Rodan’s ‘big push’ theory argues that a poor economy needs:","options":["A large, coordinated investment across many complementary industries at once","Gradual growth led by small farms, village crafts and cottage industries","Rapid opening to imports so that foreign competition forces domestic efficiency","Large foreign loans so that it can first repay all its old external debt"],"answer":0,"explanation":"Because industries depend on each other for demand and inputs, isolated investments may fail; a simultaneous push across sectors lets each create markets for the others, overcoming indivisibilities.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"रोज़ेनस्टाइन-रोडन का ‘बिग पुश’ सिद्धांत तर्क देता है कि गरीब अर्थव्यवस्था को किसकी आवश्यकता है?","optionsHi":["एक साथ अनेक पूरक उद्योगों में बड़ा, समन्वित निवेश","छोटे खेतों, ग्रामीण शिल्पों और कुटीर उद्योगों के नेतृत्व में क्रमिक वृद्धि","आयात के लिए तेज़ी से खुलना ताकि विदेशी प्रतिस्पर्धा घरेलू दक्षता को विवश करे","बड़े विदेशी ऋण ताकि वह पहले अपना सारा पुराना बाह्य ऋण चुका सके"],"explanationHi":"चूँकि उद्योग मांग और आगतों के लिए एक-दूसरे पर निर्भर हैं, अलग-थलग निवेश विफल हो सकते हैं; क्षेत्रों में एक साथ धक्का हर एक को दूसरों के लिए बाज़ार बनाने देता है और अविभाज्यताओं को पार करता है।"},
  {"id":"eco-sectors-schemes-207","question":"In the Harris–Todaro model, migrants compare the rural wage with the expected urban wage. If the rural wage is ₹300 a day and the urban formal-sector wage ₹750, migration stops when the urban unemployment rate reaches:","options":["40%","45%","25%","60%"],"answer":3,"explanation":"Migration stops when (probability of getting an urban job) × 750 = 300, i.e. a 40% chance of employment, which means 60% urban unemployment. Answering 40% confuses the employment probability with the unemployment rate.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"हैरिस–टोडारो मॉडल में प्रवासी ग्रामीण मज़दूरी की तुलना अपेक्षित शहरी मज़दूरी से करते हैं। यदि ग्रामीण मज़दूरी ₹300 प्रतिदिन और शहरी औपचारिक क्षेत्र की मज़दूरी ₹750 है, तो प्रवास तब रुकता है जब शहरी बेरोज़गारी दर पहुँचती है:","optionsHi":["40%","45%","25%","60%"],"explanationHi":"प्रवास तब रुकता है जब (शहरी नौकरी पाने की संभावना) × 750 = 300, यानी रोज़गार की 40% संभावना, जिसका अर्थ है 60% शहरी बेरोज़गारी। 40% उत्तर देना रोज़गार की संभावना को बेरोज़गारी दर से उलझाना है।"},
  {"id":"eco-sectors-schemes-208","question":"Engel’s law helps explain the falling share of agriculture in national output because:","options":["Farm prices always rise faster than industrial prices","As incomes rise, the share of spending on food falls","Land is fixed, so farm output cannot grow at all","Governments tax agriculture more heavily than industry"],"answer":1,"explanation":"Food demand grows more slowly than income, so as incomes rise, a smaller share of spending goes to farm products and demand shifts to industry and services.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"एंगेल का नियम राष्ट्रीय उत्पादन में कृषि के घटते हिस्से की व्याख्या में क्यों सहायक है?","optionsHi":["क्योंकि कृषि कीमतें हमेशा औद्योगिक कीमतों से तेज़ बढ़ती हैं","क्योंकि आय बढ़ने पर खाद्य पर व्यय का हिस्सा घटता है","क्योंकि भूमि स्थिर है, इसलिए कृषि उत्पादन बिल्कुल नहीं बढ़ सकता","क्योंकि सरकारें कृषि पर उद्योग से अधिक भारी कर लगाती हैं"],"explanationHi":"खाद्य की मांग आय से धीमी बढ़ती है, इसलिए आय बढ़ने पर व्यय का छोटा हिस्सा कृषि उत्पादों पर जाता है और मांग उद्योग तथा सेवाओं की ओर खिसकती है।"},
  {"id":"eco-sectors-schemes-209","question":"The National Commission for Enterprises in the Unorganised Sector (2007), under Arjun Sengupta, defined the unorganised sector as unincorporated private enterprises owned by individuals or households, employing fewer than:","options":["5 workers","10 workers","20 workers","50 workers"],"answer":1,"explanation":"NCEUS counted enterprises run on a proprietary or partnership basis with fewer than ten workers as unorganised; unorganised workers also include informal workers in the organised sector who lack social security.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"असंगठित क्षेत्र में उद्यमों के लिए राष्ट्रीय आयोग (2007), अर्जुन सेनगुप्ता की अध्यक्षता में, ने असंगठित क्षेत्र को व्यक्तियों या परिवारों के स्वामित्व वाले अनिगमित निजी उद्यमों के रूप में परिभाषित किया, जिनमें कितने से कम श्रमिक हों?","optionsHi":["5 श्रमिक","10 श्रमिक","20 श्रमिक","50 श्रमिक"],"explanationHi":"NCEUS ने स्वामित्व या साझेदारी आधार पर चलने वाले दस से कम श्रमिकों वाले उद्यमों को असंगठित माना; असंगठित श्रमिकों में संगठित क्षेत्र के वे अनौपचारिक श्रमिक भी आते हैं जिन्हें सामाजिक सुरक्षा नहीं मिलती।"},
  {"id":"eco-sectors-schemes-210","question":"The Industrial Relations Code, 2020 raised the threshold above which an industrial establishment needs prior government permission for lay-off, retrenchment or closure from 100 workers to:","options":["200 workers","250 workers","500 workers","300 workers"],"answer":3,"explanation":"The Code raised the limit to 300 workers, and lets the government raise it further by notification, to give firms more flexibility; earlier the Industrial Disputes Act set it at 100.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"औद्योगिक संबंध संहिता, 2020 ने छँटनी, कार्य-बंदी या बंदी के लिए किसी औद्योगिक प्रतिष्ठान को सरकार की पूर्व अनुमति की जो सीमा 100 श्रमिकों से बढ़ाई, वह कितनी है?","optionsHi":["200 श्रमिक","250 श्रमिक","500 श्रमिक","300 श्रमिक"],"explanationHi":"संहिता ने सीमा 300 श्रमिक कर दी, और सरकार को अधिसूचना द्वारा इसे और बढ़ाने देती है, ताकि फर्मों को अधिक लचीलापन मिले; पहले औद्योगिक विवाद अधिनियम ने इसे 100 पर रखा था।"},
  {"id":"eco-sectors-schemes-211","question":"The Code on Wages, 2019 empowers the Central Government to fix a ‘floor wage’. Its effect is that:","options":["Every employer must pay at least the floor wage plus a dearness allowance","No State may fix a minimum wage below the floor wage","The floor wage replaces all State minimum wages","Only Central Government employees are paid the floor wage"],"answer":1,"explanation":"The Centre fixes the floor wage, possibly different for different areas, considering minimum living standards; State minimum wages cannot be lower than it.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"मज़दूरी संहिता, 2019 केंद्र सरकार को ‘न्यूनतम आधार मज़दूरी’ (फ्लोर वेज) तय करने का अधिकार देती है। इसका प्रभाव है कि:","optionsHi":["हर नियोक्ता को कम से कम आधार मज़दूरी जमा महँगाई भत्ता देना होगा","कोई राज्य आधार मज़दूरी से कम न्यूनतम मज़दूरी तय नहीं कर सकता","आधार मज़दूरी सभी राज्य न्यूनतम मज़दूरियों का स्थान ले लेती है","केवल केंद्र सरकार के कर्मचारियों को आधार मज़दूरी दी जाती है"],"explanationHi":"केंद्र न्यूनतम जीवन स्तर को ध्यान में रखते हुए आधार मज़दूरी तय करता है, जो अलग-अलग क्षेत्रों के लिए अलग हो सकती है; राज्यों की न्यूनतम मज़दूरी उससे कम नहीं हो सकती।"},
  {"id":"eco-sectors-schemes-212","question":"The National Payments Corporation of India, which runs UPI and RuPay, is:","options":["A department of the Reserve Bank of India set up under the RBI Act, 1934","A public sector undertaking owned wholly by the Ministry of Finance","A statutory body created under the Payment and Settlement Systems Act, 2007","A not-for-profit company promoted by the RBI and Indian Banks’ Association"],"answer":3,"explanation":"NPCI was set up in 2008 as a not-for-profit (Section 8) company under the RBI’s guidance and the IBA, owned by banks, as an umbrella organisation for retail payments.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"भारतीय राष्ट्रीय भुगतान निगम, जो UPI और रुपे (RuPay) चलाता है, क्या है?","optionsHi":["RBI अधिनियम, 1934 के अंतर्गत स्थापित भारतीय रिज़र्व बैंक का एक विभाग","पूरी तरह वित्त मंत्रालय के स्वामित्व वाला सार्वजनिक क्षेत्र का उपक्रम","भुगतान और निपटान प्रणाली अधिनियम, 2007 के अंतर्गत बना सांविधिक निकाय","RBI और भारतीय बैंक संघ द्वारा प्रवर्तित एक गैर-लाभकारी कंपनी"],"explanationHi":"NPCI की स्थापना 2008 में RBI के मार्गदर्शन और IBA के साथ एक गैर-लाभकारी (धारा 8) कंपनी के रूप में हुई, जिसका स्वामित्व बैंकों के पास है, खुदरा भुगतानों के लिए एक छत्र संगठन के रूप में।"},
  {"id":"eco-sectors-schemes-213","question":"The Open Network for Digital Commerce (ONDC), backed by DPIIT, aims to:","options":["Set up a government-owned e-commerce company to compete with private platforms","Tax foreign e-commerce companies on all sales they make to buyers in India","Let buyers and sellers on different apps trade via common open protocols","Ban private-label goods sold by the large online marketplaces in India"],"answer":2,"explanation":"ONDC is a network, not a platform: open protocols let any buyer app reach any seller app, so small sellers are not locked into one marketplace.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"DPIIT समर्थित ओपन नेटवर्क फॉर डिजिटल कॉमर्स (ONDC) का उद्देश्य क्या है?","optionsHi":["निजी मंचों से प्रतिस्पर्धा के लिए सरकार के स्वामित्व वाली ई-कॉमर्स कंपनी बनाना","विदेशी ई-कॉमर्स कंपनियों की भारत में क्रेताओं को की गई सभी बिक्री पर कर लगाना","अलग-अलग ऐप पर मौजूद क्रेताओं और विक्रेताओं को साझा खुले प्रोटोकॉल से व्यापार करने देना","बड़े ऑनलाइन बाज़ारों द्वारा भारत में बेचे जाने वाले प्राइवेट-लेबल सामान पर रोक लगाना"],"explanationHi":"ONDC एक नेटवर्क है, मंच नहीं: खुले प्रोटोकॉल किसी भी क्रेता ऐप को किसी भी विक्रेता ऐप तक पहुँचने देते हैं, इसलिए छोटे विक्रेता एक ही बाज़ार में बँधे नहीं रहते।"},
  {"id":"eco-sectors-schemes-214","question":"BharatNet, earlier called the National Optical Fibre Network, aims to:","options":["Provide satellite phones to remote villages along the borders","Lay undersea optical cables to the island territories only","Connect all gram panchayats with broadband optical fibre","Give free smartphones to every poor rural household in India"],"answer":2,"explanation":"Started as NOFN in 2011 and renamed BharatNet in 2015, it builds optical fibre middle-mile connectivity to every gram panchayat so that broadband can reach villages.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"भारतनेट, जिसे पहले राष्ट्रीय ऑप्टिकल फाइबर नेटवर्क कहा जाता था, का उद्देश्य क्या है?","optionsHi":["सीमाओं पर दूरस्थ गाँवों को सैटेलाइट फ़ोन देना","केवल द्वीप क्षेत्रों तक समुद्र के नीचे ऑप्टिकल केबल बिछाना","सभी ग्राम पंचायतों को ब्रॉडबैंड ऑप्टिकल फाइबर से जोड़ना","भारत के हर गरीब ग्रामीण परिवार को निःशुल्क स्मार्टफ़ोन देना"],"explanationHi":"2011 में NOFN के रूप में शुरू और 2015 में भारतनेट नाम पाकर यह हर ग्राम पंचायत तक ऑप्टिकल फाइबर मध्य-मील संपर्कता बनाता है, ताकि ब्रॉडबैंड गाँवों तक पहुँच सके।"},
  {"id":"eco-sectors-schemes-215","question":"The National Investment and Infrastructure Fund (NIIF), set up in 2015, is best described as:","options":["A department of the Finance Ministry that directly funds highways","A non-banking finance company owned wholly by the Reserve Bank","A pension fund regulated by PFRDA for infrastructure workers","A quasi-sovereign wealth fund in which the Government holds 49%"],"answer":3,"explanation":"NIIF is India’s first quasi-sovereign wealth fund; the Government holds 49% so that it is not a government company, and the rest comes from domestic and foreign institutional investors.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"2015 में स्थापित राष्ट्रीय निवेश और अवसंरचना कोष (NIIF) का सबसे उपयुक्त वर्णन क्या है?","optionsHi":["वित्त मंत्रालय का एक विभाग जो सीधे राजमार्गों को वित्त देता है","पूरी तरह भारतीय रिज़र्व बैंक के स्वामित्व वाली गैर-बैंकिंग वित्त कंपनी","अवसंरचना श्रमिकों के लिए PFRDA द्वारा विनियमित पेंशन कोष","अर्ध-संप्रभु संपदा कोष जिसमें सरकार की 49% हिस्सेदारी है"],"explanationHi":"NIIF भारत का पहला अर्ध-संप्रभु संपदा कोष है; सरकार के पास 49% हिस्सेदारी है ताकि यह सरकारी कंपनी न हो, और शेष घरेलू तथा विदेशी संस्थागत निवेशकों से आता है।"},
  {"id":"eco-sectors-schemes-216","question":"How many of these statements about InvITs and REITs in India are correct? I. Both are regulated by SEBI under regulations issued in 2014. II. An InvIT holds income-generating infrastructure assets such as roads or power lines. III. A REIT holds completed, rent-generating real estate such as office parks. IV. Both are required to distribute a large part of their cash flows to unit holders.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Both are trust-based vehicles that pool investors’ money in yield-generating assets and pass on most of the cash flow, letting developers recycle capital.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"भारत में InvIT और REIT के बारे में इनमें से कितने कथन सही हैं? I. दोनों SEBI द्वारा 2014 में जारी विनियमों के अंतर्गत विनियमित हैं। II. InvIT सड़कों या बिजली लाइनों जैसी आय देने वाली अवसंरचना परिसंपत्तियाँ रखता है। III. REIT कार्यालय पार्कों जैसी तैयार, किराया देने वाली अचल संपत्ति रखता है। IV. दोनों से अपेक्षा है कि वे अपने नकदी प्रवाह का बड़ा भाग यूनिट धारकों में बाँटें।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। दोनों न्यास-आधारित माध्यम हैं जो निवेशकों का धन प्रतिफल देने वाली परिसंपत्तियों में जमा करते हैं और अधिकांश नकदी प्रवाह आगे देते हैं, जिससे डेवलपर अपनी पूंजी का पुनः उपयोग कर पाते हैं।"},
  {"id":"eco-sectors-schemes-217","question":"The National Monetisation Pipeline, announced in 2021, plans to raise money mainly by:","options":["Leasing brownfield assets to private firms for a period, keeping ownership","Selling government land outright to private developers through auctions","Issuing special bonds to the RBI against the value of infrastructure assets","Privatising all public sector banks and insurance companies in stages"],"answer":0,"explanation":"Under the NMP, assets such as roads, railway stations and pipelines are handed to private players through models like TOT and InvITs for a set period, after which they return to the government.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"2021 में घोषित राष्ट्रीय मुद्रीकरण पाइपलाइन मुख्यतः धन कैसे जुटाने की योजना बनाती है?","optionsHi":["स्वामित्व बनाए रखते हुए ब्राउनफील्ड परिसंपत्तियाँ एक अवधि के लिए निजी फर्मों को पट्टे पर देकर","नीलामी के माध्यम से सरकारी भूमि निजी डेवलपरों को सीधे बेचकर","अवसंरचना परिसंपत्तियों के मूल्य के बदले RBI को विशेष बॉन्ड जारी करके","सभी सार्वजनिक क्षेत्र के बैंकों और बीमा कंपनियों का चरणबद्ध निजीकरण करके"],"explanationHi":"NMP के अंतर्गत सड़कों, रेलवे स्टेशनों और पाइपलाइनों जैसी परिसंपत्तियाँ TOT और InvIT जैसे मॉडलों के माध्यम से एक निश्चित अवधि के लिए निजी पक्षों को दी जाती हैं, जिसके बाद वे सरकार को लौट आती हैं।"},
  {"id":"eco-sectors-schemes-218","question":"In the ‘Swiss challenge’ method of awarding public projects:","options":["The lowest bidder wins automatically after a single sealed round of bidding","The project goes to a foreign firm with a proven track record in such work","Rivals bid on an unsolicited proposal, whose author may match the best","The government negotiates privately with one firm without any open bidding"],"answer":2,"explanation":"A private party proposes a project; the government invites counter-proposals, and the original proponent gets the right to match the best offer to win the contract.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"सार्वजनिक परियोजनाएँ देने की ‘स्विस चैलेंज’ पद्धति में:","optionsHi":["बोली के एक बंद-लिफाफा दौर के बाद सबसे कम बोली वाला स्वतः जीत जाता है","परियोजना ऐसे कार्य में सिद्ध अनुभव वाली विदेशी फर्म को जाती है","प्रतिद्वंद्वी एक अनचाहे प्रस्ताव पर बोली लगाते हैं, जिसका प्रस्तावक सर्वोत्तम बोली की बराबरी कर सकता है","सरकार बिना किसी खुली बोली के एक फर्म से निजी तौर पर बातचीत करती है"],"explanationHi":"कोई निजी पक्ष परियोजना प्रस्तावित करता है; सरकार प्रति-प्रस्ताव आमंत्रित करती है, और मूल प्रस्तावक को ठेका जीतने के लिए सर्वोत्तम प्रस्ताव की बराबरी करने का अधिकार मिलता है।"},
  {"id":"eco-sectors-schemes-219","question":"The National Bank for Financing Infrastructure and Development (NaBFID) was set up in 2021 as:","options":["A development finance institution created by an Act of Parliament","A wholly owned subsidiary of the State Bank of India for infra loans","A division of NITI Aayog for infrastructure planning","A non-banking finance company jointly owned by the States"],"answer":0,"explanation":"NaBFID was created under the NaBFID Act, 2021 as a development finance institution for long-term infrastructure funding, reviving the DFI model that had faded after ICICI and IDBI turned into banks.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"राष्ट्रीय अवसंरचना वित्तपोषण और विकास बैंक (NaBFID) 2021 में किस रूप में स्थापित किया गया?","optionsHi":["संसद के अधिनियम द्वारा बनाई गई विकास वित्त संस्था","अवसंरचना ऋणों के लिए भारतीय स्टेट बैंक की पूर्ण स्वामित्व वाली सहायक कंपनी","अवसंरचना नियोजन के लिए नीति आयोग का एक प्रभाग","राज्यों के संयुक्त स्वामित्व वाली गैर-बैंकिंग वित्त कंपनी"],"explanationHi":"NaBFID को NaBFID अधिनियम, 2021 के अंतर्गत दीर्घकालिक अवसंरचना वित्तपोषण की विकास वित्त संस्था के रूप में बनाया गया, जिससे उस DFI मॉडल को पुनर्जीवित किया गया जो ICICI और IDBI के बैंक बन जाने के बाद फीका पड़ गया था।"},
  {"id":"eco-sectors-schemes-220","question":"PM-JANMAN, launched in November 2023, is a mission specifically for:","options":["All Scheduled Caste households living in rural areas","Particularly Vulnerable Tribal Groups","Nomadic and denotified tribes living in cities","Forest dwellers who hold rights under the Forest Rights Act"],"answer":1,"explanation":"The Pradhan Mantri Janjati Adivasi Nyaya Maha Abhiyan targets the 75 PVTGs, bringing housing, roads, water, health and other services to their habitations through several ministries.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"नवंबर 2023 में शुरू किया गया PM-JANMAN विशेष रूप से किसके लिए मिशन है?","optionsHi":["ग्रामीण क्षेत्रों में रहने वाले सभी अनुसूचित जाति परिवार","विशेष रूप से कमज़ोर जनजातीय समूह","शहरों में रहने वाली घुमंतू और विमुक्त जनजातियाँ","वन अधिकार अधिनियम के अंतर्गत अधिकार रखने वाले वनवासी"],"explanationHi":"प्रधानमंत्री जनजातीय आदिवासी न्याय महा अभियान 75 PVTG को लक्षित करता है, और कई मंत्रालयों के माध्यम से उनकी बस्तियों तक आवास, सड़कें, पानी, स्वास्थ्य और अन्य सेवाएँ पहुँचाता है।"},
  {"id":"eco-sectors-schemes-221","question":"The Pradhan Mantri Van Dhan Yojana, launched in 2018 through TRIFED, mainly aims to:","options":["Plant trees on degraded forest land with MGNREGA labour and funds","Pay tribal families a yearly fee for protecting forests from fire","Add value to minor forest produce through tribal producer groups","Give tribal youth bank loans to set up timber trading businesses"],"answer":2,"explanation":"Van Dhan Vikas Kendras organise tribal gatherers into groups that process, package and market minor forest produce, raising the share of the final price that reaches them.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"TRIFED के माध्यम से 2018 में शुरू की गई प्रधानमंत्री वन धन योजना का मुख्य उद्देश्य क्या है?","optionsHi":["MGNREGA के श्रम और धन से क्षरित वन भूमि पर वृक्ष लगाना","आदिवासी परिवारों को वनों को आग से बचाने के लिए वार्षिक शुल्क देना","जनजातीय उत्पादक समूहों के माध्यम से लघु वनोपज का मूल्य संवर्धन करना","आदिवासी युवाओं को इमारती लकड़ी व्यापार शुरू करने के लिए बैंक ऋण देना"],"explanationHi":"वन धन विकास केंद्र जनजातीय संग्राहकों को समूहों में संगठित करते हैं जो लघु वनोपज का प्रसंस्करण, पैकेजिंग और विपणन करते हैं, जिससे अंतिम कीमत में उन तक पहुँचने वाला हिस्सा बढ़ता है।"},
  {"id":"eco-sectors-schemes-222","question":"A ‘Lakhpati Didi’ under the initiative announced in 2023 is a member of a self-help group who:","options":["Has taken a bank loan of at least ₹1 lakh for her business","Has saved at least ₹1 lakh in her SHG savings account","Has received a one-time grant of ₹1 lakh from the State","Earns a household income of at least ₹1 lakh a year"],"answer":3,"explanation":"The initiative under DAY-NRLM aims to help SHG women reach a sustained annual household income of ₹1 lakh or more through livelihood activities, skills and credit.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"2023 में घोषित पहल के अंतर्गत ‘लखपति दीदी’ स्वयं सहायता समूह की वह सदस्य है जो:","optionsHi":["अपने व्यवसाय के लिए कम से कम ₹1 लाख का बैंक ऋण ले चुकी हो","अपने SHG बचत खाते में कम से कम ₹1 लाख बचा चुकी हो","राज्य से ₹1 लाख का एकमुश्त अनुदान पा चुकी हो","कम से कम ₹1 लाख वार्षिक की पारिवारिक आय अर्जित करती हो"],"explanationHi":"DAY-NRLM के अंतर्गत यह पहल आजीविका गतिविधियों, कौशल और ऋण के माध्यम से SHG महिलाओं को ₹1 लाख या अधिक की सतत वार्षिक पारिवारिक आय तक पहुँचाने का लक्ष्य रखती है।"},
  {"id":"eco-sectors-schemes-223","question":"Under Phase II of the Swachh Bharat Mission (Grameen), the goal of ‘ODF Plus’ means:","options":["Building a second, separate toilet in every rural household","Declaring all towns as well as all villages open-defecation free","Replacing all rural pit latrines with piped sewer connections","Sustaining ODF status plus solid and liquid waste management"],"answer":3,"explanation":"Phase II (from 2020–21) moved beyond toilet building to keeping villages ODF and managing solid and liquid waste so that villages are visibly clean.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"स्वच्छ भारत मिशन (ग्रामीण) के चरण II के अंतर्गत ‘ODF प्लस’ लक्ष्य का क्या अर्थ है?","optionsHi":["हर ग्रामीण परिवार में दूसरा, अलग शौचालय बनाना","सभी कस्बों के साथ-साथ सभी गाँवों को खुले में शौच से मुक्त घोषित करना","सभी ग्रामीण गड्ढे वाले शौचालयों को पाइप वाले सीवर कनेक्शनों से बदलना","ODF दर्जा बनाए रखना तथा ठोस और तरल अपशिष्ट प्रबंधन करना"],"explanationHi":"चरण II (2020–21 से) शौचालय निर्माण से आगे बढ़कर गाँवों को ODF बनाए रखने और ठोस तथा तरल अपशिष्ट का प्रबंधन करने पर केंद्रित हुआ, ताकि गाँव स्पष्ट रूप से स्वच्छ दिखें।"},
  {"id":"eco-sectors-schemes-224","question":"The Credit Linked Subsidy Scheme (CLSS) under PMAY-Urban provided:","options":["Free houses built by the government for the urban homeless","Interest subsidy on home loans for EWS, LIG and MIG families","Rent support to migrant workers in rental housing complexes","Grants to builders who construct affordable housing projects"],"answer":1,"explanation":"Under CLSS, the subsidy on the interest of a home loan was credited upfront to the borrower’s loan account, lowering EMIs for economically weaker sections and low- and middle-income groups.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"PMAY-शहरी के अंतर्गत ऋण-संबद्ध सब्सिडी योजना (CLSS) क्या प्रदान करती थी?","optionsHi":["शहरी बेघरों के लिए सरकार द्वारा बनाए गए निःशुल्क मकान","EWS, LIG और MIG परिवारों के लिए गृह ऋण पर ब्याज सब्सिडी","किराये के आवास परिसरों में प्रवासी श्रमिकों को किराया सहायता","किफायती आवास परियोजनाएँ बनाने वाले बिल्डरों को अनुदान"],"explanationHi":"CLSS के अंतर्गत गृह ऋण के ब्याज पर सब्सिडी अग्रिम रूप से उधारकर्ता के ऋण खाते में जमा की जाती थी, जिससे आर्थिक रूप से कमज़ोर वर्गों और निम्न तथा मध्यम आय समूहों की EMI घटती थी।"},
  {"id":"eco-sectors-schemes-225","question":"The Atal Bhujal Yojana, launched in 2019 with World Bank support, focuses on:","options":["Piped drinking water connections to every rural home","Interlinking rivers to move surplus water to drought-prone regions","Community-led management of groundwater in water-stressed areas","Building large storage dams in drought-prone districts"],"answer":2,"explanation":"Atal Jal works in water-stressed areas of seven States, using incentives for gram panchayats that plan water budgets and reduce groundwater use. Tap connections are the Jal Jeevan Mission’s job.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"2019 में विश्व बैंक के सहयोग से शुरू की गई अटल भूजल योजना किस पर केंद्रित है?","optionsHi":["हर ग्रामीण घर में नल से पेयजल कनेक्शन","अधिशेष जल को सूखा-प्रवण क्षेत्रों में ले जाने के लिए नदियों को जोड़ना","जल-संकटग्रस्त क्षेत्रों में भूजल का समुदाय-आधारित प्रबंधन","सूखा-प्रवण ज़िलों में बड़े भंडारण बाँध बनाना"],"explanationHi":"अटल जल सात राज्यों के जल-संकटग्रस्त क्षेत्रों में काम करती है, उन ग्राम पंचायतों के लिए प्रोत्साहनों के साथ जो जल बजट बनाती हैं और भूजल का उपयोग घटाती हैं। नल कनेक्शन जल जीवन मिशन का काम है।"},
  {"id":"eco-sectors-schemes-226","question":"The National Food Security Mission, launched in 2007–08, was originally meant to raise the production of:","options":["Rice, wheat and pulses","Oilseeds, sugarcane and cotton","Fruits, vegetables and spices","Milk, eggs and fish"],"answer":0,"explanation":"NFSM began with rice, wheat and pulses through area expansion and productivity gains in identified districts; coarse cereals and nutri-cereals were added later.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"2007–08 में शुरू किया गया राष्ट्रीय खाद्य सुरक्षा मिशन मूलतः किसके उत्पादन को बढ़ाने के लिए था?","optionsHi":["चावल, गेहूँ और दालें","तिलहन, गन्ना और कपास","फल, सब्ज़ियाँ और मसाले","दूध, अंडे और मछली"],"explanationHi":"NFSM की शुरुआत चावल, गेहूँ और दालों से चिह्नित ज़िलों में क्षेत्र विस्तार और उत्पादकता वृद्धि के माध्यम से हुई; मोटे अनाज और पोषक-अनाज बाद में जोड़े गए।"},
  {"id":"eco-sectors-schemes-227","question":"The Rashtriya Krishi Vikas Yojana (2007) differs from many other farm schemes because it:","options":["Pays a fixed sum directly into every farmer’s bank account","Lets States plan and choose their own farm projects","Is funded entirely through loans taken from the World Bank","Is run only in districts with no assured irrigation"],"answer":1,"explanation":"RKVY was designed to encourage States to raise farm investment, letting them prepare district and State agriculture plans and pick projects suited to local needs.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"राष्ट्रीय कृषि विकास योजना (2007) अनेक अन्य कृषि योजनाओं से इस प्रकार भिन्न है कि वह:","optionsHi":["हर किसान के बैंक खाते में सीधे निश्चित राशि देती है","राज्यों को अपनी कृषि परियोजनाएँ बनाने और चुनने देती है","पूरी तरह विश्व बैंक से लिए ऋणों से वित्तपोषित है","केवल उन ज़िलों में चलती है जहाँ सुनिश्चित सिंचाई नहीं है"],"explanationHi":"RKVY राज्यों को कृषि निवेश बढ़ाने के लिए प्रोत्साहित करने हेतु बनी थी, जिसमें वे ज़िला और राज्य कृषि योजनाएँ बनाकर स्थानीय ज़रूरतों के अनुरूप परियोजनाएँ चुन सकते हैं।"},
  {"id":"eco-sectors-schemes-228","question":"Under the National Food Security Act, 2013, if a beneficiary is not supplied the entitled foodgrains or meals, he or she is entitled to:","options":["Double the quantity of foodgrains in the next month","A food security allowance from the State government","A cash refund paid by the Food Corporation of India","Free foodgrains from the Centre for the next six months"],"answer":1,"explanation":"Section 8 of the Act requires the State government to pay a food security allowance in such cases. It is one of the provisions that make the Act a legal entitlement rather than a welfare scheme.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"राष्ट्रीय खाद्य सुरक्षा अधिनियम, 2013 के अंतर्गत, यदि किसी लाभार्थी को पात्र खाद्यान्न या भोजन नहीं दिया जाता, तो वह किसका हकदार है?","optionsHi":["अगले माह खाद्यान्न की दोगुनी मात्रा","राज्य सरकार से खाद्य सुरक्षा भत्ता","भारतीय खाद्य निगम द्वारा नकद वापसी","केंद्र से अगले छह माह का निःशुल्क खाद्यान्न"],"explanationHi":"अधिनियम की धारा 8 ऐसे मामलों में राज्य सरकार से खाद्य सुरक्षा भत्ता देने की अपेक्षा करती है। यह उन प्रावधानों में से है जो अधिनियम को कल्याण योजना के बजाय कानूनी पात्रता बनाते हैं।"},
  {"id":"eco-sectors-schemes-229","question":"The National Manufacturing Policy of 2011 aimed to raise the share of manufacturing in GDP, over a decade, to:","options":["25%","15%","35%","50%"],"answer":0,"explanation":"The policy targeted a 25% share and 100 million additional jobs, and proposed National Investment and Manufacturing Zones; the share stayed far below this, closer to the mid-teens.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"2011 की राष्ट्रीय विनिर्माण नीति का लक्ष्य एक दशक में GDP में विनिर्माण का हिस्सा कितना करना था?","optionsHi":["25%","15%","35%","50%"],"explanationHi":"नीति ने 25% हिस्से और 100 मिलियन अतिरिक्त रोज़गारों का लक्ष्य रखा, तथा राष्ट्रीय निवेश और विनिर्माण क्षेत्र प्रस्तावित किए; हिस्सा इससे बहुत नीचे, मध्य-किशोर प्रतिशत के निकट, ही रहा।"},
  {"id":"eco-sectors-schemes-230","question":"The Jan Vishwas (Amendment of Provisions) Act, 2023 sought to improve ease of doing business mainly by:","options":["Replacing jail terms for minor offences with civil penalties","Abolishing all licences needed for setting up new factories","Merging the central labour laws into four new labour codes","Allowing 100% FDI in all sectors through the automatic route"],"answer":0,"explanation":"The Act amended about 180 provisions across 42 central Acts, turning many minor, technical or procedural lapses into civil matters with monetary penalties to reduce fear of prosecution.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"जन विश्वास (प्रावधानों का संशोधन) अधिनियम, 2023 ने कारोबार सुगमता को मुख्यतः कैसे सुधारना चाहा?","optionsHi":["छोटे अपराधों के लिए जेल की सज़ा की जगह दीवानी दंड रखकर","नए कारखाने लगाने के लिए आवश्यक सभी लाइसेंस समाप्त करके","केंद्रीय श्रम कानूनों को चार नई श्रम संहिताओं में मिलाकर","स्वचालित मार्ग से सभी क्षेत्रों में 100% FDI की अनुमति देकर"],"explanationHi":"अधिनियम ने 42 केंद्रीय अधिनियमों के लगभग 180 प्रावधानों में संशोधन किया, जिससे अनेक छोटी, तकनीकी या प्रक्रियात्मक चूकें मुकदमे के भय को घटाने के लिए आर्थिक दंड वाले दीवानी मामलों में बदल गईं।"},
  {"id":"eco-sectors-schemes-231","question":"In 2020 the coal sector in India was opened to commercial mining, which means that:","options":["Private firms may mine coal for sale, not only for captive use","Coal India Limited was privatised through a majority stake sale","Coal imports were banned to protect the domestic mining industry","States lost their right to receive royalty on coal mined there"],"answer":0,"explanation":"Earlier, private firms could mine coal only for captive use in their own power, steel or cement plants. Commercial auctions allow sale without end-use restrictions, while Coal India stays public.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"2020 में भारत में कोयला क्षेत्र को वाणिज्यिक खनन के लिए खोला गया, जिसका अर्थ है कि:","optionsHi":["निजी फर्में बिक्री के लिए कोयला खनन कर सकती हैं, केवल स्वयं के उपयोग के लिए नहीं","बहुलांश हिस्सेदारी की बिक्री से कोल इंडिया लिमिटेड का निजीकरण कर दिया गया","घरेलू खनन उद्योग की रक्षा के लिए कोयले के आयात पर प्रतिबंध लगा दिया गया","राज्यों ने वहाँ खनन किए गए कोयले पर रॉयल्टी पाने का अधिकार खो दिया"],"explanationHi":"पहले निजी फर्में कोयला केवल अपने बिजली, इस्पात या सीमेंट संयंत्रों के स्वयं उपयोग के लिए खनन कर सकती थीं। वाणिज्यिक नीलामी अंतिम-उपयोग प्रतिबंध के बिना बिक्री की अनुमति देती है, जबकि कोल इंडिया सार्वजनिक रहती है।"},
  {"id":"eco-sectors-schemes-232","question":"District Mineral Foundations, provided for by the MMDR Amendment Act, 2015, are funded mainly by:","options":["Grants from the Union budget for the most backward districts","A share of the GST collected on minerals and mining services","Loans from NABARD to districts with large mining activity","Mining leaseholders’ contributions linked to their royalty"],"answer":3,"explanation":"Leaseholders pay a contribution related to their royalty into the DMF of the district, which spends it on people and areas affected by mining, guided by the PMKKKY scheme.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"MMDR संशोधन अधिनियम, 2015 द्वारा प्रावधानित ज़िला खनिज फाउंडेशन का वित्तपोषण मुख्यतः किससे होता है?","optionsHi":["सबसे पिछड़े ज़िलों के लिए केंद्रीय बजट से अनुदान","खनिजों और खनन सेवाओं पर वसूले गए GST का एक हिस्सा","बड़ी खनन गतिविधि वाले ज़िलों को NABARD से ऋण","खनन पट्टाधारकों के अंशदान, जो उनकी रॉयल्टी से जुड़े हों"],"explanationHi":"पट्टाधारक अपनी रॉयल्टी से संबंधित अंशदान ज़िले के DMF में देते हैं, जो उसे खनन से प्रभावित लोगों और क्षेत्रों पर खर्च करता है, और PMKKKY योजना इसका मार्गदर्शन करती है।"},
  {"id":"eco-sectors-schemes-233","question":"The Swadesh Darshan scheme of the Ministry of Tourism is meant to:","options":["Give tax refunds to foreign tourists on goods bought in India","Develop theme-based tourist circuits across the country","Fund pilgrimage trips for senior citizens","Promote Indian films abroad to attract visitors"],"answer":1,"explanation":"Launched in 2014–15, it funds integrated infrastructure on theme-based circuits such as Buddhist, coastal or heritage circuits; PRASHAD covers pilgrimage sites separately.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"पर्यटन मंत्रालय की स्वदेश दर्शन योजना का उद्देश्य क्या है?","optionsHi":["विदेशी पर्यटकों को भारत में खरीदे सामान पर कर वापसी देना","देश भर में विषय-आधारित पर्यटन परिपथ विकसित करना","वरिष्ठ नागरिकों की तीर्थ यात्राओं को वित्त देना","पर्यटकों को आकर्षित करने के लिए विदेश में भारतीय फ़िल्मों का प्रचार करना"],"explanationHi":"2014–15 में शुरू यह योजना बौद्ध, तटीय या विरासत परिपथों जैसे विषय-आधारित परिपथों पर एकीकृत अवसंरचना को वित्त देती है; तीर्थ स्थलों को प्रसाद योजना अलग से कवर करती है।"},
  {"id":"eco-sectors-schemes-234","question":"The India Semiconductor Mission, launched in 2021, works as a specialised division under:","options":["The Department of Science and Technology","The Indian Space Research Organisation","Digital India Corporation under MeitY","The Ministry of Heavy Industries"],"answer":2,"explanation":"ISM operates within Digital India Corporation under MeitY, running the incentive programmes for semiconductor fabs, display fabs, and assembly and testing units.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"2021 में शुरू किया गया इंडिया सेमीकंडक्टर मिशन किसके अधीन एक विशेषीकृत प्रभाग के रूप में काम करता है?","optionsHi":["विज्ञान और प्रौद्योगिकी विभाग","भारतीय अंतरिक्ष अनुसंधान संगठन","MeitY के अंतर्गत डिजिटल इंडिया कॉर्पोरेशन","भारी उद्योग मंत्रालय"],"explanationHi":"ISM MeitY के अंतर्गत डिजिटल इंडिया कॉर्पोरेशन के भीतर काम करता है और सेमीकंडक्टर फैब, डिस्प्ले फैब तथा असेंबली और परीक्षण इकाइयों के प्रोत्साहन कार्यक्रम चलाता है।"},
  {"id":"eco-sectors-schemes-235","question":"The Software Technology Parks of India (STPI) scheme, started in 1991, helped the IT industry mainly by:","options":["Reserving all government software work for public sector firms","Fixing the salaries of software engineers across the country","Banning imports of foreign software to protect Indian firms","Giving export software units tax breaks and fast data links"],"answer":3,"explanation":"STPI gave 100% export-oriented software units single-window clearance, duty-free imports, tax holidays and high-speed satellite data links, which helped IT exports take off in the 1990s.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"1991 में शुरू की गई भारतीय सॉफ्टवेयर प्रौद्योगिकी पार्क (STPI) योजना ने IT उद्योग की मुख्यतः कैसे मदद की?","optionsHi":["सभी सरकारी सॉफ्टवेयर कार्य सार्वजनिक क्षेत्र की फर्मों के लिए आरक्षित करके","देश भर में सॉफ्टवेयर इंजीनियरों के वेतन तय करके","भारतीय फर्मों की रक्षा के लिए विदेशी सॉफ्टवेयर के आयात पर रोक लगाकर","निर्यात सॉफ्टवेयर इकाइयों को कर छूट और तेज़ डेटा लिंक देकर"],"explanationHi":"STPI ने 100% निर्यात-उन्मुख सॉफ्टवेयर इकाइयों को एकल खिड़की मंजूरी, शुल्क-मुक्त आयात, कर अवकाश और तेज़ गति के उपग्रह डेटा लिंक दिए, जिससे 1990 के दशक में IT निर्यात ने रफ़्तार पकड़ी।"},
  {"id":"eco-sectors-schemes-236","question":"The ‘U-shaped’ pattern of female labour force participation, discussed by Claudia Goldin, suggests that as an economy develops:","options":["Women’s participation rises steadily with income","Women’s participation falls steadily with income","Women’s participation first falls and then rises","Women’s participation stays flat at all income levels"],"answer":2,"explanation":"As farm-based family work declines and household incomes rise, participation first falls; it rises again as women’s education grows and suitable service-sector jobs expand. It is one lens on India’s low female LFPR.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"क्लॉडिया गोल्डिन द्वारा विश्लेषित महिला श्रम बल भागीदारी का ‘U-आकार’ प्रतिरूप सुझाता है कि अर्थव्यवस्था के विकसित होने पर:","optionsHi":["महिलाओं की भागीदारी आय के साथ लगातार बढ़ती है","महिलाओं की भागीदारी आय के साथ लगातार घटती है","महिलाओं की भागीदारी पहले घटती है और फिर बढ़ती है","महिलाओं की भागीदारी सभी आय स्तरों पर स्थिर रहती है"],"explanationHi":"जैसे-जैसे खेती-आधारित पारिवारिक कार्य घटता है और परिवारों की आय बढ़ती है, भागीदारी पहले घटती है; महिलाओं की शिक्षा बढ़ने और उपयुक्त सेवा क्षेत्र की नौकरियाँ फैलने पर वह फिर बढ़ती है। यह भारत की कम महिला LFPR को समझने का एक नज़रिया है।"},
  {"id":"eco-sectors-schemes-237","question":"A worker who works only 20 hours a week and is willing and available to work more is an example of:","options":["Visible underemployment","Disguised unemployment","Frictional unemployment","Open unemployment"],"answer":0,"explanation":"Visible underemployment means working fewer hours than normal while wanting more work. Disguised unemployment is when extra workers add nothing to output, though they appear fully engaged.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"जो श्रमिक सप्ताह में केवल 20 घंटे काम करता है और अधिक काम करने को इच्छुक तथा उपलब्ध है, वह किसका उदाहरण है?","optionsHi":["दृश्य अल्प-रोज़गार","प्रच्छन्न बेरोज़गारी","घर्षणात्मक बेरोज़गारी","खुली बेरोज़गारी"],"explanationHi":"दृश्य अल्प-रोज़गार का अर्थ है सामान्य से कम घंटे काम करना जबकि अधिक काम चाहना। प्रच्छन्न बेरोज़गारी तब होती है जब अतिरिक्त श्रमिक उत्पादन में कुछ नहीं जोड़ते, यद्यपि वे पूरी तरह लगे दिखते हैं।"},
  {"id":"eco-sectors-schemes-238","question":"On a Lorenz curve diagram, the area between the line of equality and the Lorenz curve is 0.15 (the whole square has area 1). The Gini coefficient is:","options":["0.15","0.30","0.35","0.70"],"answer":1,"explanation":"Gini = area between the line of equality and the Lorenz curve ÷ total area under the line of equality (0.5) = 0.15/0.5 = 0.30. Taking 0.15 directly forgets that the triangle is half the square.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"लॉरेंज वक्र आरेख पर, समानता रेखा और लॉरेंज वक्र के बीच का क्षेत्रफल 0.15 है (पूरे वर्ग का क्षेत्रफल 1 है)। गिनी गुणांक है:","optionsHi":["0.15","0.30","0.35","0.70"],"explanationHi":"गिनी = समानता रेखा और लॉरेंज वक्र के बीच का क्षेत्रफल ÷ समानता रेखा के नीचे का कुल क्षेत्रफल (0.5) = 0.15/0.5 = 0.30। सीधे 0.15 लेना यह भूलना है कि त्रिभुज वर्ग का आधा है।"},
  {"id":"eco-sectors-schemes-239","question":"The 1979 Task Force under Y. K. Alagh defined the poverty line using calorie norms of:","options":["2,100 kcal a day in rural areas and 2,400 in urban areas","2,400 kcal a day in rural areas and 2,100 in urban areas","2,250 kcal a day in both rural and urban areas","1,800 kcal a day in rural areas and 2,100 in urban areas"],"answer":1,"explanation":"Rural people were assumed to need more energy for manual work, hence 2,400 kcal rural and 2,100 kcal urban; the poverty line was the spending at which these were met.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"वाई. के. अलघ के अधीन 1979 के कार्य बल ने गरीबी रेखा को किन कैलोरी मानदंडों से परिभाषित किया?","optionsHi":["ग्रामीण क्षेत्रों में प्रतिदिन 2,100 kcal और शहरी क्षेत्रों में 2,400","ग्रामीण क्षेत्रों में प्रतिदिन 2,400 kcal और शहरी क्षेत्रों में 2,100","ग्रामीण और शहरी दोनों में प्रतिदिन 2,250 kcal","ग्रामीण क्षेत्रों में प्रतिदिन 1,800 kcal और शहरी क्षेत्रों में 2,100"],"explanationHi":"माना गया कि ग्रामीण लोगों को शारीरिक श्रम के लिए अधिक ऊर्जा चाहिए, इसलिए ग्रामीण 2,400 kcal और शहरी 2,100 kcal; गरीबी रेखा वह व्यय थी जिस पर ये पूरे होते थे।"},
  {"id":"eco-sectors-schemes-240","question":"A key change made by the Tendulkar Committee (2009) in measuring poverty was that it:","options":["Raised the calorie norm for rural areas to 2,700 kcal a day per person","Dropped the calorie anchor and used one basket for rural and urban areas","Measured poverty by household income rather than by consumption spending","Counted only food spending and left out health and education costs"],"answer":1,"explanation":"Tendulkar moved away from calorie norms, used the urban poverty line basket for both rural and urban areas with price adjustments, and allowed for private spending on health and education.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"तेंदुलकर समिति (2009) द्वारा गरीबी मापने में किया गया एक प्रमुख परिवर्तन क्या था?","optionsHi":["ग्रामीण क्षेत्रों के लिए कैलोरी मानदंड बढ़ाकर प्रतिदिन प्रति व्यक्ति 2,700 kcal करना","कैलोरी आधार को छोड़कर ग्रामीण और शहरी दोनों के लिए एक ही टोकरी का उपयोग करना","गरीबी को उपभोग व्यय के बजाय पारिवारिक आय से मापना","केवल खाद्य व्यय को गिनना और स्वास्थ्य तथा शिक्षा की लागतों को छोड़ देना"],"explanationHi":"तेंदुलकर ने कैलोरी मानदंडों से हटकर, मूल्य समायोजन के साथ ग्रामीण और शहरी दोनों के लिए शहरी गरीबी रेखा की टोकरी का उपयोग किया, और स्वास्थ्य तथा शिक्षा पर निजी व्यय का भी प्रावधान रखा।"},
  {"id":"eco-sectors-schemes-241","question":"In a region, 20% of people are multidimensionally poor (H) and on average they are deprived in 45% of the weighted indicators (A). The Multidimensional Poverty Index is:","options":["0.20","0.45","0.09","0.65"],"answer":2,"explanation":"MPI = H × A = 0.20 × 0.45 = 0.09. It falls if fewer people are poor or if the poor become less deprived, which the head-count ratio alone would miss.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"किसी क्षेत्र में 20% लोग बहुआयामी रूप से गरीब हैं (H) और औसतन वे भारित संकेतकों के 45% में वंचित हैं (A)। बहुआयामी गरीबी सूचकांक है:","optionsHi":["0.20","0.45","0.09","0.65"],"explanationHi":"MPI = H × A = 0.20 × 0.45 = 0.09। यह तब घटता है जब कम लोग गरीब हों या गरीब कम वंचित हो जाएँ, जो अकेला हेड-काउंट अनुपात नहीं पकड़ पाता।"},
  {"id":"eco-sectors-schemes-242","question":"The Inequality-adjusted Human Development Index (IHDI) differs from the HDI in that it:","options":["Adds a fourth dimension measuring gaps between women and men","Uses only income per head and ignores health and education","Compares a country’s HDI with the average of its neighbours","Discounts each dimension for how unequally it is spread"],"answer":3,"explanation":"The IHDI lowers each dimension’s value according to inequality within the population; the gap between HDI and IHDI shows the loss in human development due to inequality.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"असमानता-समायोजित मानव विकास सूचकांक (IHDI) HDI से किस प्रकार भिन्न है?","optionsHi":["यह महिलाओं और पुरुषों के बीच अंतर मापने वाला चौथा आयाम जोड़ता है","यह केवल प्रति व्यक्ति आय का उपयोग करता है और स्वास्थ्य तथा शिक्षा को छोड़ देता है","यह किसी देश के HDI की तुलना उसके पड़ोसियों के औसत से करता है","यह प्रत्येक आयाम को इस आधार पर घटाता है कि वह कितनी असमानता से बँटा है"],"explanationHi":"IHDI जनसंख्या के भीतर असमानता के अनुसार प्रत्येक आयाम का मान घटाता है; HDI और IHDI का अंतर असमानता के कारण मानव विकास की हानि दर्शाता है।"},
  {"id":"eco-sectors-schemes-243","question":"In a country, 25% of the population is aged 0–14, 68% is aged 15–64 and 7% is 65 or older. Its total dependency ratio is about:","options":["32%","37%","68%","47%"],"answer":3,"explanation":"Dependency ratio = (0–14 + 65+)/(15–64) = 32/68 ≈ 47%. Using 32% forgets to divide by the working-age group; 37% counts only the young.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"किसी देश में जनसंख्या का 25% 0–14 आयु का, 68% 15–64 आयु का और 7% 65 या उससे अधिक आयु का है। उसका कुल निर्भरता अनुपात लगभग कितना है?","optionsHi":["32%","37%","68%","47%"],"explanationHi":"निर्भरता अनुपात = (0–14 + 65+)/(15–64) = 32/68 ≈ 47%। 32% लेना कार्य-आयु समूह से भाग देना भूलना है; 37% केवल युवाओं को गिनता है।"},
  {"id":"eco-sectors-schemes-244","question":"Under the RBI’s regulatory framework for microfinance of 2022, a microfinance loan is a collateral-free loan to a household with an annual income of up to:","options":["₹1.25 lakh","₹2 lakh","₹5 lakh","₹3 lakh"],"answer":3,"explanation":"The 2022 framework set a common income ceiling of ₹3 lakh for rural and urban households, applied it to all regulated lenders, and capped loan repayments at 50% of household income.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"RBI के 2022 के सूक्ष्म वित्त नियामक ढाँचे के अंतर्गत, सूक्ष्म वित्त ऋण उस परिवार को दिया गया बिना संपार्श्विक ऋण है जिसकी वार्षिक आय कितनी तक हो?","optionsHi":["₹1.25 लाख","₹2 लाख","₹5 लाख","₹3 लाख"],"explanationHi":"2022 के ढाँचे ने ग्रामीण और शहरी परिवारों के लिए ₹3 लाख की साझा आय सीमा तय की, उसे सभी विनियमित ऋणदाताओं पर लागू किया, और ऋण चुकौतियों को परिवार की आय के 50% तक सीमित किया।"},
  {"id":"eco-sectors-schemes-245","question":"Mission Amrit Sarovar, launched in 2022, aims to:","options":["Build or revive 75 water bodies in every district","Clean 75 polluted stretches of the river Ganga and tributaries","Provide piped water to 75 towns in each State","Set up 75 sewage treatment plants in big cities"],"answer":0,"explanation":"The mission, marking 75 years of independence, set a target of 75 Amrit Sarovars (ponds) per district, largely using MGNREGA and other schemes, to conserve rainwater.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"2022 में शुरू किए गए मिशन अमृत सरोवर का उद्देश्य क्या है?","optionsHi":["हर ज़िले में 75 जल निकाय बनाना या पुनर्जीवित करना","गंगा और सहायक नदियों के 75 प्रदूषित हिस्सों को साफ़ करना","हर राज्य के 75 कस्बों को पाइप से पानी देना","बड़े शहरों में 75 सीवेज उपचार संयंत्र लगाना"],"explanationHi":"स्वतंत्रता के 75 वर्ष को चिह्नित करते हुए मिशन ने प्रत्येक ज़िले में 75 अमृत सरोवरों (तालाबों) का लक्ष्य रखा, जिन्हें मुख्यतः MGNREGA और अन्य योजनाओं से बनाया गया, ताकि वर्षा जल का संरक्षण हो।"},
  {"id":"eco-sectors-schemes-246","question":"Which MSME Ministry scheme, relaunched in 2022, certifies units at Bronze, Silver and Gold levels on both product quality and environmental impact?","options":["Lean Manufacturing Competitiveness Scheme","BIS product certification (ISI mark)","ZED Certification Scheme","Udyam Registration"],"answer":2,"explanation":"ZED (Zero Defect Zero Effect) certifies MSMEs in Bronze, Silver and Gold tiers for quality and low environmental impact. The Lean scheme is tempting because it targets waste and productivity, but it is a consultancy-support scheme, not a graded quality-and-environment certification.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"MSME मंत्रालय की कौन-सी योजना, जो 2022 में पुनः शुरू की गई, इकाइयों को उत्पाद गुणवत्ता और पर्यावरणीय प्रभाव दोनों पर कांस्य, रजत और स्वर्ण स्तरों पर प्रमाणित करती है?","optionsHi":["लीन विनिर्माण प्रतिस्पर्धात्मकता योजना","BIS उत्पाद प्रमाणन (ISI चिह्न)","ZED प्रमाणन योजना","उद्यम पंजीकरण"],"explanationHi":"ZED (ज़ीरो डिफेक्ट ज़ीरो इफेक्ट) MSME को गुणवत्ता और कम पर्यावरणीय प्रभाव के लिए कांस्य, रजत और स्वर्ण स्तरों में प्रमाणित करता है। लीन योजना भ्रामक है क्योंकि वह अपव्यय और उत्पादकता को लक्षित करती है, पर वह परामर्श-सहायता योजना है, गुणवत्ता और पर्यावरण का श्रेणीबद्ध प्रमाणन नहीं।"},
  {"id":"eco-sectors-schemes-247","question":"Guarantees under the Emergency Credit Line Guarantee Scheme, launched in 2020 to help businesses through the pandemic, were provided by:","options":["The Reserve Bank of India","SIDBI","National Credit Guarantee Trustee Company","Export Credit Guarantee Corporation of India"],"answer":2,"explanation":"ECLGS loans by banks and NBFCs carried a full guarantee from NCGTC, a company of the Department of Financial Services, so lenders could extend extra credit to MSMEs and others hit by COVID-19.","difficulty":"very-hard","source":"RBI Grade B","questionHi":"महामारी में व्यवसायों की मदद के लिए 2020 में शुरू की गई आपातकालीन ऋण सुविधा गारंटी योजना के अंतर्गत गारंटी किसने दी?","optionsHi":["भारतीय रिज़र्व बैंक","SIDBI","राष्ट्रीय ऋण गारंटी न्यासी कंपनी","भारतीय निर्यात ऋण गारंटी निगम"],"explanationHi":"बैंकों और NBFC के ECLGS ऋणों को NCGTC की पूर्ण गारंटी मिली, जो वित्तीय सेवा विभाग की एक कंपनी है, ताकि ऋणदाता MSME तथा COVID-19 से प्रभावित अन्य को अतिरिक्त ऋण दे सकें।"},
  {"id":"eco-sectors-schemes-248","question":"Assertion (A): Many workers employed by organised-sector firms are counted as informal workers. Reason (R): Informality of employment depends on whether a worker has social security and a written contract, not just on the type of enterprise.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Contract and casual workers in registered firms often lack social security and job security, so they are informal workers in the organised sector; the distinction is between enterprise type and job type.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"अभिकथन (A): संगठित क्षेत्र की फर्मों द्वारा नियोजित अनेक श्रमिक अनौपचारिक श्रमिक गिने जाते हैं। कारण (R): रोज़गार की अनौपचारिकता इस पर निर्भर करती है कि श्रमिक को सामाजिक सुरक्षा और लिखित अनुबंध मिला है या नहीं, केवल उद्यम के प्रकार पर नहीं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"पंजीकृत फर्मों के अनुबंध और आकस्मिक श्रमिकों को प्रायः सामाजिक सुरक्षा और रोज़गार सुरक्षा नहीं मिलती, इसलिए वे संगठित क्षेत्र में अनौपचारिक श्रमिक हैं; भेद उद्यम के प्रकार और नौकरी के प्रकार के बीच है।"},
  {"id":"eco-sectors-schemes-249","question":"The Industries (Development and Regulation) Act, the main law behind industrial licensing, was enacted in:","options":["1948","1956","1951","1969"],"answer":2,"explanation":"The IDR Act of 1951 gave the Centre power to license and regulate industries; 1948 and 1956 were the Industrial Policy Resolutions, and 1969 saw the MRTP Act and bank nationalisation.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"उद्योग (विकास और विनियमन) अधिनियम, जो औद्योगिक लाइसेंसिंग के पीछे का मुख्य कानून है, किस वर्ष अधिनियमित हुआ?","optionsHi":["1948","1956","1951","1969"],"explanationHi":"1951 के IDR अधिनियम ने केंद्र को उद्योगों को लाइसेंस देने और विनियमित करने की शक्ति दी; 1948 और 1956 औद्योगिक नीति संकल्प थे, और 1969 में MRTP अधिनियम और बैंक राष्ट्रीयकरण हुए।"},
  {"id":"eco-sectors-schemes-250","question":"The PM Formalisation of Micro Food Processing Enterprises (PMFME) scheme, launched in 2020, follows which approach in choosing products for support?","options":["One District One Product","One Nation One Ration Card","One State One Crop","One Block One Cluster"],"answer":0,"explanation":"PMFME, under the Ministry of Food Processing Industries, supports micro food units with credit-linked subsidy, and uses ODOP to gain scale in buying inputs, common services and marketing.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"2020 में शुरू की गई सूक्ष्म खाद्य प्रसंस्करण उद्यमों के औपचारिकीकरण की PM योजना (PMFME) समर्थन के लिए उत्पाद चुनने में कौन-सा दृष्टिकोण अपनाती है?","optionsHi":["एक ज़िला एक उत्पाद","एक राष्ट्र एक राशन कार्ड","एक राज्य एक फसल","एक खंड एक समूह"],"explanationHi":"खाद्य प्रसंस्करण उद्योग मंत्रालय के अंतर्गत PMFME सूक्ष्म खाद्य इकाइयों को ऋण-संबद्ध अनुदान से सहारा देती है, और आगतों की खरीद, साझा सेवाओं तथा विपणन में पैमाना पाने के लिए ODOP का उपयोग करती है।"},
  {"id":"eco-sectors-schemes-251","question":"Which voluntary, contributory scheme launched in 2019 offers small and marginal farmers who join between the ages of 18 and 40 a pension of ₹3,000 a month from the age of 60?","options":["Atal Pension Yojana (APY)","PM Shram Yogi Maan-dhan","PM-KISAN income support scheme","PM Kisan Maan-Dhan Yojana"],"answer":3,"explanation":"PM-KMY is the farmers’ counterpart of PM-SYM (which covers unorganised workers): the Centre matches the farmer’s contribution and LIC manages the fund. PM-KISAN is income support, not a pension.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"2019 में शुरू की गई कौन-सी स्वैच्छिक, अंशदायी योजना 18 से 40 वर्ष के बीच जुड़ने वाले लघु और सीमांत किसानों को 60 वर्ष की आयु से ₹3,000 प्रति माह की पेंशन देती है?","optionsHi":["अटल पेंशन योजना (APY)","PM श्रम योगी मान-धन","PM-KISAN आय सहायता योजना","PM किसान मान-धन योजना"],"explanationHi":"PM-KMY, PM-SYM (जो असंगठित श्रमिकों को कवर करती है) का किसानों के लिए समकक्ष है: केंद्र किसान के अंशदान के बराबर राशि देता है और LIC कोष का प्रबंधन करती है। PM-KISAN आय सहायता है, पेंशन नहीं।"},
];

export default questions;
